{"command":"python3 - << 'PY'
import subprocess, os, pty
EXE="/workspace/executable"
def run(args,inp):
 p=subprocess.run([EXE]+args,input=inp,capture_output=True,text=True); print("PIPE",args,repr(p.stdout))
def runt(args,inp):
 master,slave=pty.openpty(); p=subprocess.Popen([EXE]+args,stdin=subprocess.PIPE,stdout=slave,stderr=slave); os.close(slave); p.stdin.write(inp.encode()); p.stdin.close(); out=b""
 while True:
  try:d=os.read(master,4096)
  except OSError:break
  if not d:break
  out+=d
 p.wait(); print("TTY",args,repr(out.decode()))
for args in [["--upper","a"],["--upper","a","--line-numbers"],["--upper","a","--only-matching"]]:
 run(args,"banana\nsplit\napple\n")
 runt(args,"banana\nsplit\napple\n")
PY"}

