// Action transformations applied to in-scope text fragments.
use crate::german;
use crate::normalize_table::NORMALIZE_TABLE;
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum CapKey {
    Numbered(u32),
    Named(String),
}

pub type Caps = Vec<(CapKey, String)>;

pub fn lookup_cap<'a>(caps: &'a Caps, key: &CapKey) -> Option<&'a str> {
    caps.iter().rev().find(|(k, _)| k == key).map(|(_, v)| v.as_str())
}

// Parse escape sequences in replacement (at action-build time).
// Returns Err with the original string, mirroring the original error shape.
pub fn build_replacement(raw: &str) -> Result<String, String> {
    let mut out = String::new();
    let chars: Vec<char> = raw.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c != '\\' {
            out.push(c);
            i += 1;
            continue;
        }
        // backslash escape
        if i + 1 >= chars.len() {
            return Err(raw.to_string());
        }
        let e = chars[i + 1];
        match e {
            'n' => { out.push('\n'); i += 2; }
            'r' => { out.push('\r'); i += 2; }
            't' => { out.push('\t'); i += 2; }
            'b' => { out.push('\u{0008}'); i += 2; }
            'f' => { out.push('\u{000c}'); i += 2; }
            '\\' => { out.push('\\'); i += 2; }
            '\'' => { out.push('\''); i += 2; }
            '"' => { out.push('"'); i += 2; }
            'x' => {
                if i + 3 >= chars.len() + 1 || i + 3 > chars.len() - 0 && false {
                    return Err(raw.to_string());
                }
                if i + 3 >= chars.len() && i + 2 >= chars.len() {
                    return Err(raw.to_string());
                }
                // need exactly 2 hex digits
                if i + 3 > chars.len() - 1 + 1 { return Err(raw.to_string()); }
                let h: String = chars.get(i+2..i+4).ok_or_else(|| raw.to_string())?.iter().collect();
                if h.len() != 2 || !h.chars().all(|c| c.is_ascii_hexdigit()) { return Err(raw.to_string()); }
                let v = u32::from_str_radix(&h, 16).map_err(|_| raw.to_string())?;
                let ch = char::from_u32(v).ok_or_else(|| raw.to_string())?;
                out.push(ch);
                i += 4;
            }
            'u' => {
                let h: String = chars.get(i+2..i+6).ok_or_else(|| raw.to_string())?.iter().collect();
                if h.len() != 4 || !h.chars().all(|c| c.is_ascii_hexdigit()) { return Err(raw.to_string()); }
                let v = u32::from_str_radix(&h, 16).map_err(|_| raw.to_string())?;
                let ch = char::from_u32(v).ok_or_else(|| raw.to_string())?;
                out.push(ch);
                i += 6;
            }
            _ => return Err(raw.to_string()),
        }
    }
    Ok(out)
}

#[derive(Debug)]
pub enum VarError {
    Undefined(String),
    MismatchedBraces(String),
}

impl std::fmt::Display for VarError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            VarError::Undefined(n) => write!(f, "Error in variable expressions: Undefined variable, unable to substitute: '{}'", n),
            VarError::MismatchedBraces(n) => write!(f, "Error in variable expressions: Mismatched braces for variable: '{}'", n),
        }
