        out.push('$');
        i += 1;
    }
    Ok(out)
}

fn var_display_name(name: &str) -> String {
    if !name.is_empty() && name.chars().all(|c| c.is_ascii_digit()) {
        // strip leading zeros, but keep at least one digit; $0 stays 0, $01 -> 1, $00 -> ? test avoided
        let t = name.trim_start_matches('0');
        if t.is_empty() { "0".to_string() } else { t.to_string() }
    } else {
        name.to_string()
    }
}

fn lookup_var<'a>(caps: &'a Caps, name: &str) -> Option<&'a str> {
    if !name.is_empty() && name.chars().all(|c| c.is_ascii_digit()) {
        let v: u32 = var_display_name(name).parse().ok()?;
        lookup_cap(caps, &CapKey::Numbered(v))
    } else {
        lookup_cap(caps, &CapKey::Named(name.to_string()))
    }
}

pub fn upper(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if c == 'ß' {
            out.push('ẞ');
        } else {
            out.extend(c.to_uppercase());
        }
    }
    // Rust's to_uppercase handles contextual cases per char adequately for upper;
    // but Greek etc. need no special handling in uppercase.
    out
}

pub fn lower(s: &str) -> String {
    s.to_lowercase()
}

pub fn normalize(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        // Hangul syllable decomposition (algorithmic NFD, jamo are not marks)
        if ('\u{ac00}'..='\u{d7a3}').contains(&c) {
            let code = c as u32 - 0xac00;
            let l = 0x1100 + code / 588;
            let v = 0x1161 + (code % 588) / 28;
            let t = code % 28;
            if let Some(ch) = char::from_u32(l) { out.push(ch); }
            if let Some(ch) = char::from_u32(v) { out.push(ch); }
            if t > 0 {
                if let Some(ch) = char::from_u32(0x11a7 + t) { out.push(ch); }
            }
            continue;
        }
        match NORMALIZE_TABLE.binary_search_by_key(&c, |(k, _)| *k) {
            Ok(idx) => out.push_str(NORMALIZE_TABLE[idx].1),
            Err(_) => out.push(c),
        }
    }
    out
}

// Symbols

pub static SYMBOLS_FORWARD: &[(&str, &str)] = &[
    ("<--", "⟵"),
    ("-->", "⟶"),
    ("<->", "↔"),
    ("---", "—"),
    ("--", "–"),
    ("!=", "≠"),
    ("->", "→"),
    ("<-", "←"),
    ("=>", "⇒"),
    ("<=", "≤"),
    (">=", "≥"),
];

pub static SYMBOLS_INVERSE: &[(&str, &str)] = &[
    ("⟵", "<--"),
    ("⟶", "-->"),
    ("↔", "<->"),
    ("—", "---"),
    ("–", "--"),
    ("≠", "!="),
    ("→", "->"),
    ("←", "<-"),
    ("⇒", "=>"),
    ("≤", "<="),
    ("≥", ">="),
];

pub fn symbols(s: &str, invert: bool) -> String {
    let table: &[(&str, &str)] = if invert { SYMBOLS_INVERSE } else { SYMBOLS_FORWARD };
    // Left-to-right, longest match at each position.
    let mut out = String::with_capacity(s.len());
    let bytes = s.as_bytes();
    let mut i = 0;
    // Build char index positions for safety: operate on char boundaries.
    let mut idxs: Vec<usize> = s.char_indices().map(|(i, _)| i).collect();
    idxs.push(s.len());
    let mut pos_in_idxs = 0usize;
    // Simpler: iterate over byte index moving by char len, matching string slices.
    let mut b = 0usize;
    while b < s.len() {
        let mut best: Option<(&str, &str)> = None;
        for (pat, repl) in table {
            if s[b..].starts_with(pat) {
                if best.map_or(true, |(bp, _)| pat.len() > bp.len()) {
                    best = Some((pat, repl));
                }
            }
        }
        if let Some((pat, repl)) = best {
            out.push_str(repl);
            b += pat.len();
        } else {
            let ch = s[b..].chars().next().unwrap();
            out.push(ch);
            b += ch.len_utf8();
        }
        let _ = bytes; let _ = idxs; let _ = pos_in_idxs;
    }
    out
}

pub fn titlecase(s: &str) -> String {
    crate::titlecase::titlecase(s)
}

pub fn german_action(s: &str, naive: bool, prefer_original: bool, _invert: bool) -> String {
    // invert is ignored for german (applied normally)
    german::apply_german(s, naive, prefer_original)
}
