// Title casing following the John Gruber-style algorithm used by the
// `titlecase` crate: small words stay lowercase, words with internal
// capitals / dots are preserved, all-uppercase input is converted.

const SMALL_WORDS: &[&str] = &[
    "a", "an", "and", "as", "at", "but", "by", "en", "for", "if", "in", "of", "on", "or",
    "the", "to", "v", "via", "vs",
];

fn is_small(word: &str) -> bool {
    SMALL_WORDS.contains(&word.to_lowercase().as_str())
}

// A "word" for titlecasing: maximal run separated by whitespace or '-' or '/'.
// We process the string tokenised by separators we keep.

#[derive(Debug, Clone)]
struct WordInfo {
    text: String,
    // indices within original token stream are handled by caller
}

pub fn titlecase(input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }
    // If the entire input is uppercase (has cased chars and all cased are upper),
    // it is treated as a title shouted in caps: convert each word normally.
    // Otherwise, words that are all-uppercase are preserved (acronyms).
    let has_cased = input.chars().any(|c| c.is_lowercase() || c.is_uppercase());
    let all_upper = has_cased
        && !input.chars().any(|c| c.is_lowercase());

    // Tokenise keeping separators. Words are separated by whitespace, '-', '/'.
    // Note: '_' '.' '\'' are NOT separators (per probes).
    #[derive(Clone)]
    enum Tok { Word(String), Sep(String) }
    let mut toks: Vec<Tok> = Vec::new();
    let mut cur = String::new();
    let mut cur_is_sep: Option<bool> = None;
    let is_sep = |c: char| c.is_whitespace() || c == '-' || c == '/';
    for c in input.chars() {
        let s = is_sep(c);
        match cur_is_sep {
            None => { cur.push(c); cur_is_sep = Some(s); }
            Some(prev) if prev == s => cur.push(c),
            Some(prev) => {
                toks.push(if prev { Tok::Sep(std::mem::take(&mut cur)) } else { Tok::Word(std::mem::take(&mut cur)) });
                cur.push(c); cur_is_sep = Some(s);
            }
        }
    }
    if !cur.is_empty() {
        toks.push(if cur_is_sep.unwrap() { Tok::Sep(cur) } else { Tok::Word(cur) });
    }

    let word_indices: Vec<usize> = toks.iter().enumerate().filter_map(|(i, t)| if matches!(t, Tok::Word(_)) { Some(i) } else { None }).collect();
    let first_word = word_indices.first().copied();
    let last_word = word_indices.last().copied();

    let mut out = String::new();
    // Track previous word token index for colon rules etc.
    for (idx, tok) in toks.iter().enumerate() {
        match tok {
            Tok::Sep(s) => out.push_str(s),
            Tok::Word(w) => {
                let is_first = Some(idx) == first_word;
                let is_last = Some(idx) == last_word;
                // Word following a separator that ends with ':' or '.' (sentence end)
                // should be capitalised even if small -- handled by checking if this is first
                // after such punctuation? Our separators only include whitespace/-/ so colon
                // stays attached to previous word. See handling below via prev word suffix.
                let prev_ends_sentence = if idx >= 2 {
                    if let Tok::Word(pw) = &toks[idx - 2] {
                        pw.ends_with(':') || pw.ends_with('.') || pw.ends_with('!') || pw.ends_with('?')
                    } else { false }
                } else { false };

                let transformed = title_word(w, is_first || is_last || prev_ends_sentence, all_upper);
                out.push_str(&transformed);
            }
        }
    }
    out
}

fn title_word(word: &str, force_cap: bool, all_upper_input: bool) -> String {
    // Strip leading/trailing non-alphanumeric punctuation for analysis, preserving it.
    // We'll find first and last "word char" boundaries. For simplicity, operate on
    // the core consisting of alphanumeric (incl. apostrophes inside) characters.
    let chars: Vec<char> = word.chars().collect();
    // Find core start/end (first/last alphanumeric or underscore etc.)
    // If word contains '.' inside (like hello.world), leave unchanged (unless all-upper).
    // But a trailing '.' is punctuation, internal dot only when letters on both sides.
    let has_internal_dot = (1..chars.len().saturating_sub(0)).any(|i| {
        chars[i] == '.' && i + 1 < chars.len() && chars[i - 1].is_alphanumeric() && chars[i + 1].is_alphanumeric()
    });
    if has_internal_dot && !all_upper_input {
        return word.to_string();
    }

    // Preserve words with internal capitals (e.g. iPhone, McDONALD) or mixed case
    // that is not simply Title/lower, unless input is all-upper.
    if !all_upper_input {
        // Check the alphabetic core
        let core: String = word.trim_matches(|c: char| !c.is_alphanumeric()).to_string();
        // mixed case: has both upper and lower and not (first upper + rest lower) and not all upper?
        let has_upper = core.chars().any(|c| c.is_uppercase());
        let has_lower = core.chars().any(|c| c.is_lowercase());
        if has_upper && has_lower {
            // Determine if it's plain Titlecase or lowercase-start
            let mut cs = core.chars();
            if let Some(first) = cs.next() {
                let rest: String = cs.collect();
                let rest_all_lower = rest.chars().all(|c| !c.is_uppercase());
                let rest_all_upper_or_non = rest.chars().all(|c| !c.is_lowercase());
                if first.is_lowercase() {
                    // e.g. hELLO, iPhone, McDONALD: preserve as-is when rest contains upper.
                    if rest.chars().any(|c| c.is_uppercase()) {
                        return word.to_string();
                    }
                    // all-lower word falls through to capitalisation.
                } else if first.is_uppercase() && !rest_all_lower && !rest_all_upper_or_non {
                    // HeLLo etc: preserve
                    return word.to_string();
                }
                let _ = rest_all_lower;
            }
        } else if has_upper && !has_lower {
            // All-uppercase word in a mixed input: preserve (acronym)
            // Unless it's being forced? Observed: x AA y -> AA preserved even though not first/last.
            // First/last all-upper words in mixed input are also preserved (HELLO x -> HELLO)
            return word.to_string();
        }
    }

    // Small-word check: core stripped of surrounding punctuation, lowercased.
    let leading_len = word.len() - word.trim_start_matches(|c: char| !c.is_alphanumeric()).len();
    let core_end_trimmed = word.trim_end_matches(|c: char| !c.is_alphanumeric());
    // Actually compute prefix/suffix by char indices:
    let mut start = 0usize; // byte index of first alphanumeric
    let mut end = word.len(); // byte index after last alphanumeric
    for (i, c) in word.char_indices() {
        if c.is_alphanumeric() { start = i; break; }
    }
    for (i, c) in word.char_indices().rev() {
        if c.is_alphanumeric() { end = i + c.len_utf8(); break; }
    }
    if start >= end {
        return word.to_string();
    }
    let prefix = &word[..start];
    let core = &word[start..end];
    let suffix = &word[end..];
    let _ = leading_len; let _ = core_end_trimmed;

    // Apostrophe handling: core may be like "hello's" or "don't". Titlecase only first segment?
    // Observed: hello's -> Hello's, HELLO'S -> Hello's (all-upper input)
    // "don't" -> "Don't". So we capitalise first letter and lowercase the rest of core,
    // except that apostrophe segment stays lowercase (which lowercasing all gives).

    if !force_cap && is_small(core) {
        // small words: lowercase entirely
        return format!("{}{}{}", prefix, core.to_lowercase(), suffix);
    }

    // Also small words with trailing punctuation like "and," -> still small unless suffix contains ':' '.' etc.
    if !force_cap {
        // core already stripped of trailing punct, so "and," core == "and"
        // But if suffix includes ':' or '.' the word is sentence-final; observed "and:" capitalised.
        let suffix_is_sentence_end = suffix.contains(':') || suffix.contains('.') || suffix.contains('!') || suffix.contains('?');
        if is_small(core) && !suffix_is_sentence_end {
            return format!("{}{}{}", prefix, core.to_lowercase(), suffix);
        }
        if is_small(core) && suffix_is_sentence_end {
            // falls through to capitalise
        }
    }

    // Capitalise: first character uppercase (full uppercase mapping), rest lowercase.
    // But if core contains apostrophe, rest lowercase is fine.
    // If core is like "hello's", capitalising first char and lowercasing rest works.
    let mut cchars = core.chars();
    let first = cchars.next().unwrap();
    let rest: String = cchars.collect();
    let first_up: String = first.to_uppercase().collect();
    // For characters whose titlecase differs, to_uppercase matches observed (e.g. ß -> SS in title context)
    let rest_low = rest.to_lowercase();
    format!("{}{}{}{}", prefix, first_up, rest_low, suffix)
}
RS"}

