            "csharp" => Some(Self::CSharp),
            "go" => Some(Self::Go),
            "hcl" => Some(Self::Hcl),
            "python" => Some(Self::Python),
            "rust" => Some(Self::Rust),
            "typescript" => Some(Self::TypeScript),
            _ => None,
        }
    }
    pub fn root_node_type(&self) -> &'static str {
        match self {
            LangKind::Python => "module",
            LangKind::Rust => "source_file",
            LangKind::Go => "source_file",
            LangKind::C => "translation_unit",
            LangKind::CSharp => "compilation_unit",
            LangKind::TypeScript => "program",
            LangKind::Hcl => "config_file",
        }
    }
}

#[derive(Clone, Debug)]
pub enum ScopeKind {
    Prepared(String), // e.g. "comments", "struct~Test"
    CustomQuery(String),
}

impl ScopeKind {
    pub fn split_dyn(value: &str) -> (String, Option<String>) {
        if let Some(pos) = value.find('~') {
            (value[..pos].to_string(), Some(value[pos + 1..].to_string()))
        } else {
            (value.to_string(), None)
        }
    }
}

/// Ranges for a single language scope applied to `text`.
/// Errors are user-facing messages (without the leading "Error:").
pub fn scope_ranges(
    lang: LangKind,
    scope: &ScopeKind,
    text: &str,
) -> Result<Vec<(usize, usize)>, String> {
    match scope {
        ScopeKind::Prepared(value) => Ok(match lang {
            LangKind::Python => python::prepared(value, text),
            LangKind::Hcl => hcl::prepared(value, text),
            _ => c_like::prepared(lang, value, text),
        }),
        ScopeKind::CustomQuery(q) => {
            let tree = build_tree(lang, text);
            query::run_query(&tree, text, q)
        }
    }
}

pub fn build_tree(lang: LangKind, text: &str) -> Node {
    match lang {
        LangKind::Python => python::build_tree(text),
        LangKind::Hcl => hcl::build_tree(text),
        _ => c_like::build_tree(lang, text),
    }
}

/// Merge overlapping / contained ranges, sorting by start.
/// Ranges that merely touch (end == start) are also merged, matching
/// the original's range merging used before rendering.
pub fn merge_ranges(mut ranges: Vec<(usize, usize)>) -> Vec<(usize, usize)> {
    ranges.retain(|(s, e)| e > s);
    ranges.sort();
    let mut out: Vec<(usize, usize)> = Vec::new();
    for (s, e) in ranges {
        if let Some(last) = out.last_mut() {
            if s <= last.1 {
                if e > last.1 {
                    last.1 = e;
                }
                continue;
            }
        }
        out.push((s, e));
    }
    out
}

/// Intersect two sets of ranges (both may be unmerged).
pub fn intersect_ranges(a: &[(usize, usize)], b: &[(usize, usize)]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    for &(s1, e1) in a {
        for &(s2, e2) in b {
            let s = s1.max(s2);
            let e = e1.min(e2);
            if e > s {
                out.push((s, e));
            }
        }
    }
    merge_ranges(out)
}

pub fn name_matches(pattern: &str, name: &str) -> bool {
    match regex::Regex::new(pattern) {
        Ok(re) => re.is_match(name),
        Err(_) => false,
    }
}
