// A small tree-sitter-query-like engine.
// Trees are generic nodes with a type, byte range, optional field name
// (on the edge from the parent), token text for leaves, and children.

#[derive(Clone, Debug)]
pub struct Node {
    pub typ: String,
    pub start: usize,
    pub end: usize,
    pub field: Option<String>,
    pub text: String, // for leaf/token nodes, the raw text; empty for internal nodes
    pub children: Vec<Node>,
    pub is_token: bool, // anonymous token like `if`, `{`, `identifier` tokens-as-leaves
}

impl Node {
    pub fn new(typ: &str, start: usize, end: usize) -> Self {
        Node { typ: typ.to_string(), start, end, field: None, text: String::new(), children: Vec::new(), is_token: false }
    }
    pub fn token(text: &str, start: usize, end: usize) -> Self {
        Node { typ: text.to_string(), start, end, field: None, text: text.to_string(), children: Vec::new(), is_token: true }
    }
    pub fn leaf(typ: &str, text: &str, start: usize, end: usize) -> Self {
        Node { typ: typ.to_string(), start, end, field: None, text: text.to_string(), children: Vec::new(), is_token: false }
    }
    pub fn with_children(mut self, children: Vec<Node>) -> Self {
        self.children = children;
        self
    }
    pub fn text_of<'a>(&self, source: &'a str) -> &'a str {
        if self.end <= source.len() && self.start <= self.end {
            &source[self.start..self.end]
        } else {
            ""
        }
    }
}

// ---------- S-expression parsing ----------

#[derive(Clone, Debug, PartialEq)]
enum SExp {
    Atom(String),
    List(Vec<SExp>),
    Str(String),
}

struct SParser<'a> {
    chars: Vec<char>,
    pos: usize,
    src: &'a str,
}

impl<'a> SParser<'a> {
    fn error_at(&self) -> String {
        // Roughly reproduce tree-sitter query error formatting for the most
        // common case (invalid syntax at 1:1). Callers add context.
        let _ = self.src;
        format!("Query error at 1:1. Invalid syntax:")
    }
    fn skip_ws_comments(&mut self) {
        loop {
            while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
                self.pos += 1;
            }
            if self.pos < self.chars.len() && self.chars[self.pos] == ';' {
                while self.pos < self.chars.len() && self.chars[self.pos] != '\n' {
                    self.pos += 1;
                }
            } else {
                break;
            }
        }
    }
    fn parse(&mut self) -> Result<SExp, String> {
        self.skip_ws_comments();
        if self.pos >= self.chars.len() {
            return Err(self.error_at());
        }
        let c = self.chars[self.pos];
        match c {
            '(' | '[' => {
                let close = if c == '(' { ')' } else { ']' };
                self.pos += 1;
                let mut items = Vec::new();
                // Mark alternation lists specially by wrapping with atom marker later;
                // we encode `[` lists as List with first atom "__alt__" when parsed via parse_top.
                loop {
                    self.skip_ws_comments();
                    if self.pos >= self.chars.len() {
                        return Err(self.error_at());
                    }
                    if self.chars[self.pos] == close {
                        self.pos += 1;
                        break;
                    }
                    items.push(self.parse()?);
                }
                if c == '[' {
                    let mut v = vec![SExp::Atom("__alt__".to_string())];
                    v.extend(items);
                    Ok(SExp::List(v))
                } else {
                    Ok(SExp::List(items))
                }
            }
            '"' => {
                self.pos += 1;
                let mut s = String::new();
                while self.pos < self.chars.len() {
                    let ch = self.chars[self.pos];
                    if ch == '\\' && self.pos + 1 < self.chars.len() {
                        // keep the escaped char literally (queries escape quotes etc.)
                        let n = self.chars[self.pos + 1];
                        s.push(n);
                        self.pos += 2;
                    } else if ch == '"' {
                        self.pos += 1;
                        break;
                    } else {
                        s.push(ch);
                        self.pos += 1;
                    }
                }
                Ok(SExp::Str(s))
            }
            _ => {
                let mut s = String::new();
                while self.pos < self.chars.len() {
                    let ch = self.chars[self.pos];
                    if ch.is_whitespace() || ch == '(' || ch == ')' || ch == '[' || ch == ']' || ch == ';' {
                        break;
                    }
                    s.push(ch);
                    self.pos += 1;
                }
                if s.is_empty() {
                    return Err(self.error_at());
                }
                Ok(SExp::Atom(s))
            }
        }
    }
}

// ---------- Pattern representation ----------

#[derive(Clone, Debug)]
enum Pattern {
    Node {
        typ: String, // "_" or type name, "__any__" for (_)
        children: Vec<ChildPattern>,
        captures: Vec<String>,
    },
    Alt {
        alts: Vec<Pattern>,
        captures: Vec<String>,
    },
    Token {
        text: String,
        captures: Vec<String>,
    },
    Any {
        captures: Vec<String>,
    },
}

#[derive(Clone, Debug)]
struct ChildPattern {
    field: Option<String>,
    pattern: Pattern,
    quant: Quant,
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum Quant { One, Optional, Star, Plus }

#[derive(Clone, Debug)]
struct Predicate {
    name: String, // eq?, not-eq?, match?, not-match?, any-of?, etc.
    cap: String,
    value: String,
    // for any-of: multiple values
    values: Vec<String>,
}

#[derive(Clone, Debug)]
struct TopPattern {
    pattern: Pattern,
    predicates: Vec<Predicate>,
}

fn atom_str(e: &SExp) -> Option<&str> {
    if let SExp::Atom(s) = e { Some(s) } else { None }
}

// Strip capture atoms (@name) from a pattern sexp list, returning captures and remaining.
fn extract_captures(items: &[SExp]) -> (Vec<String>, Vec<SExp>) {
    let mut caps = Vec::new();
    let mut rest = Vec::new();
    for it in items {
        if let SExp::Atom(a) = it {
            if let Some(c) = a.strip_prefix('@') {
                caps.push(c.to_string());
                continue;
            }
        }
        rest.push(it.clone());
    }
    (caps, rest)
}

fn parse_pattern(e: &SExp) -> Result<Pattern, String> {
    match e {
        SExp::Str(s) => Ok(Pattern::Token { text: s.clone(), captures: Vec::new() }),
        SExp::Atom(a) => {
            if a == "_" {
                Ok(Pattern::Any { captures: Vec::new() })
            } else {
                Err(format!("unexpected atom {a}"))
            }
        }
        SExp::List(items) => {
            if items.is_empty() {
                return Err("empty pattern".into());
            }
            if let Some(h) = atom_str(&items[0]) {
                if h == "__alt__" {
                    let (caps, _rest) = (Vec::new(), ());
                    let mut alts = Vec::new();
                    // last atoms may be captures; handle: items after alts that are @caps
                    let mut tail_caps = Vec::new();
                    let mut body: Vec<SExp> = Vec::new();
                    for it in &items[1..] {
                        if let SExp::Atom(a) = it {
                            if let Some(c) = a.strip_prefix('@') {
                                tail_caps.push(c.to_string());
                                continue;
                            }
                        }
                        body.push(it.clone());
                    }
                    for b in &body {
                        alts.push(parse_pattern(b)?);
                    }
                    let _ = caps;
                    return Ok(Pattern::Alt { alts, captures: tail_caps });
                }
                if h.starts_with('#') {
                    return Err("predicate as pattern".into());
                }
            }
            // Node pattern: first atom is type, or List is grouped pattern
            // Grouped pattern like ((comment) @x (#eq? ...)): first item is a List and no type atom.
            if matches!(items[0], SExp::List(_)) {
                // If exactly one inner list plus captures/predicates handled at top-level.
                // Inside children, a list means a nested node pattern.
                // Multiple list items: treat as anonymous group -- match first as pattern.
                // We parse as the first item pattern, merging captures from the rest atoms.
                let (caps, _r) = extract_captures(&items[1..]);
                let mut p = parse_pattern(&items[0])?;
                add_captures(&mut p, caps);
                return Ok(p);
            }
            let typ = match atom_str(&items[0]) {
                Some(t) => t.to_string(),
                None => return Err("bad node pattern".into()),
            };
            // children: parse rest, handling field: prefix atoms ending with ':',
            // quantifier atoms ? * + following a child, anchors '.', predicates.
            let mut children: Vec<ChildPattern> = Vec::new();
            let mut captures: Vec<String> = Vec::new();
            let mut i = 1usize;
            let mut pending_field: Option<String> = None;
            while i < items.len() {
                let it = &items[i];
                match it {
                    SExp::Atom(a) => {
                        if let Some(c) = a.strip_prefix('@') {
                            captures.push(c.to_string());
                        } else if a.ends_with(':') && a.len() > 1 {
                            pending_field = Some(a.trim_end_matches(':').to_string());
                        } else if a == "." {
                            // anchor: ignore
                        } else if a == "?" || a == "*" || a == "+" {
                            if let Some(last) = children.last_mut() {
                                last.quant = match a.as_str() { "?" => Quant::Optional, "*" => Quant::Star, _ => Quant::Plus };
                            }
                        } else if a.starts_with('#') {
                            // predicate inside pattern: ignore here (handled top-level)
                        }
                        i += 1;
                    }
                    SExp::List(_) | SExp::Str(_) => {
                        // A list beginning with # is a predicate: skip
                        if let SExp::List(l) = it {
                            if l.first().and_then(atom_str).map_or(false, |h| h.starts_with('#')) {
                                i += 1;
                                continue;
                            }
                        }
                        let p = parse_pattern(it)?;
                        children.push(ChildPattern { field: pending_field.take(), pattern: p, quant: Quant::One });
                        i += 1;
                        // optional quantifier following as separate atom handled in next iteration
                        // also patterns like (child)? are represented in query syntax as list then ? atom, ok
                    }
                }
            }
            Ok(Pattern::Node { typ, children, captures })
        }
    }
}

fn add_captures(p: &mut Pattern, caps: Vec<String>) {
    match p {
        Pattern::Node { captures, .. } => captures.extend(caps),
        Pattern::Alt { captures, .. } => captures.extend(caps),
        Pattern::Token { captures, .. } => captures.extend(caps),
        Pattern::Any { captures } => captures.extend(caps),
    }
}

fn parse_top(e: &SExp) -> Result<TopPattern, String> {
    // Top may be: a node pattern, alternation, or a parenthesised group:
    // ( PATTERN (#pred? @cap "val") ... ) or ( PATTERN @cap )
    // Detect group: List whose first element is a List/Str and which is not a node-type list.
    if let SExp::List(items) = e {
        if !items.is_empty() {
            let first_is_type = atom_str(&items[0]).map_or(false, |a| !a.starts_with('#') && !a.starts_with('@'));
            let first_is_list = matches!(items[0], SExp::List(_));
            if first_is_list && !is_node_type_list(&items[0]) {
                // grouped
                let mut predicates = Vec::new();
                let mut main: Option<Pattern> = None;
                let mut extra_caps: Vec<String> = Vec::new();
                for it in items {
                    match it {
                        SExp::List(l) => {
                            if l.first().and_then(atom_str).map_or(false, |h| h.starts_with('#')) {
                                predicates.push(parse_predicate(l)?);
                            } else if main.is_none() {
                                main = Some(parse_pattern(it)?);
                            } else {
                                // additional pattern? ignore
                            }
                        }
                        SExp::Atom(a) => {
                            if let Some(c) = a.strip_prefix('@') {
                                extra_caps.push(c.to_string());
                            }
                        }
                        SExp::Str(_) => {
                            if main.is_none() { main = Some(parse_pattern(it)?); }
                        }
                    }
                }
                let mut p = main.ok_or("empty group")?;
                add_captures(&mut p, extra_caps);
                return Ok(TopPattern { pattern: p, predicates });
            }
            let _ = first_is_type;
        }
    }
    // Direct pattern; extract any predicates embedded as subsequent? Only single pattern here.
    let p = parse_pattern(e)?;
    Ok(TopPattern { pattern: p, predicates: Vec::new() })
}

fn is_node_type_list(e: &SExp) -> bool {
    if let SExp::List(items) = e {
        if let Some(a) = items.first().and_then(atom_str) {
            return !a.starts_with('#');
        }
    }
    false
}

fn parse_predicate(items: &[SExp]) -> Result<Predicate, String> {
    // (#eq? @cap "value") / (#match? @cap "regex") / (#any-of? @cap "a" "b")
    let name = items.first().and_then(atom_str).unwrap_or("").trim_start_matches('#').to_string();
    let mut cap = String::new();
    let mut values = Vec::new();
    for it in &items[1..] {
        match it {
            SExp::Atom(a) => {
                if let Some(c) = a.strip_prefix('@') { cap = c.to_string(); }
            }
            SExp::Str(s) => values.push(s.clone()),
            _ => {}
        }
    }
    let value = values.first().cloned().unwrap_or_default();
    Ok(Predicate { name, cap, value, values })
}

// ---------- Matching ----------

type CapMap = Vec<(String, (usize, usize, String))>; // name -> (start,end,text)

fn match_pattern(pat: &Pattern, node: &Node, source: &str, caps: &mut CapMap) -> bool {
    match pat {
        Pattern::Any { captures } => {
            for c in captures { caps.push((c.clone(), (node.start, node.end, node.text_of(source).to_string()))); }
            true
        }
        Pattern::Token { text, captures } => {
            if node.is_token && node.text == *text {
                for c in captures { caps.push((c.clone(), (node.start, node.end, node.text_of(source).to_string()))); }
                true
            } else {
                false
            }
        }
        Pattern::Alt { alts, captures } => {
            for alt in alts {
                let mut trial = caps.clone();
                if match_pattern(alt, node, source, &mut trial) {
                    *caps = trial;
                    for c in captures { caps.push((c.clone(), (node.start, node.end, node.text_of(source).to_string()))); }
                    return true;
                }
            }
            false
        }
        Pattern::Node { typ, children, captures } => {
            if typ != "_" && typ != &node.typ {
                // wildcard parenthesised (_) is Any handled elsewhere; (type) also allow token nodes whose typ==text?
                return false;
            }
            // match children as ordered subsequence over node.children
            let mut child_caps: CapMap = Vec::new();
            if !match_children(children, &node.children, source, &mut child_caps) {
                return false;
            }
            caps.extend(child_caps);
            for c in captures { caps.push((c.clone(), (node.start, node.end, node.text_of(source).to_string()))); }
            true
        }
    }
}

fn match_children(patterns: &[ChildPattern], children: &[Node], source: &str, caps: &mut CapMap) -> bool {
    // Recursive subsequence matching with quantifiers.
    fn rec(pi: usize, ci: usize, patterns: &[ChildPattern], children: &[Node], source: &str, caps: &mut CapMap) -> bool {
        if pi >= patterns.len() {
            return true;
        }
        let cp = &patterns[pi];
        match cp.quant {
            Quant::One => {
                for j in ci..children.len() {
                    if let Some(c) = try_child(cp, &children[j], source, caps) {
                        let saved = caps.clone();
                        caps.extend(c);
                        if rec(pi + 1, j + 1, patterns, children, source, caps) {
                            return true;
                        }
                        *caps = saved;
                    }
                }
                false
            }
            Quant::Optional => {
                // try consume one, else skip
                for j in ci..children.len() {
                    if let Some(c) = try_child(cp, &children[j], source, caps) {
                        let saved = caps.clone();
                        caps.extend(c);
                        if rec(pi + 1, j + 1, patterns, children, source, caps) {
                            return true;
                        }
                        *caps = saved;
                        break;
                    }
                }
                rec(pi + 1, ci, patterns, children, source, caps)
            }
            Quant::Star | Quant::Plus => {
                // consume greedily one-or-many, backtracking
                let mut positions: Vec<(usize, CapMap)> = Vec::new();
                let mut j = ci;
                let mut acc: CapMap = Vec::new();
                loop {
                    let mut found: Option<usize> = None;
                    for k in j..children.len() {
                        if let Some(c) = try_child(cp, &children[k], source, &mut Vec::new()) {
                            // recompute captures properly
                            let mut tmp: CapMap = Vec::new();
                            let _ = try_child(cp, &children[k], source, &mut tmp);
                            acc.extend(tmp);
                            let _ = c;
                            found = Some(k);
                            break;
                        }
                    }
                    match found {
                        Some(k) => {
                            positions.push((k, acc.clone()));
                            j = k + 1;
                        }
                        None => break,
                    }
                }
                let min = if cp.quant == Quant::Plus { 1 } else { 0 };
                // try from most consumed down to min
                for count in (min..=positions.len()).rev() {
                    let mut trial = caps.clone();
                    if count > 0 {
                        trial.extend(positions[count - 1].1.clone());
                        let next_ci = positions[count - 1].0 + 1;
                        if rec(pi + 1, next_ci, patterns, children, source, &mut trial) {
                            *caps = trial;
                            return true;
                        }
                    } else if rec(pi + 1, ci, patterns, children, source, &mut trial) {
                        *caps = trial;
                        return true;
                    }
                }
                false
            }
        }
    }
    rec(0, 0, patterns, children, source, caps)
}

fn try_child(cp: &ChildPattern, node: &Node, source: &str, caps: &mut CapMap) -> Option<CapMap> {
    if let Some(f) = &cp.field {
        if node.field.as_deref() != Some(f.as_str()) {
            return None;
        }
    }
    let mut local: CapMap = Vec::new();
    if match_pattern(&cp.pattern, node, source, &mut local) {
        caps.extend(local.clone());
        Some(local)
    } else {
        None
    }
}

fn predicate_ok(pred: &Predicate, caps: &CapMap) -> bool {
    let target = caps.iter().rev().find(|(n, _)| n == &pred.cap).map(|(_, (_, _, t))| t.clone());
    let text = match target { Some(t) => t, None => return true }; // if capture missing, don't filter out
    match pred.name.as_str() {
        "eq?" => text == pred.value,
        "not-eq?" => text != pred.value,
        "match?" => regex::Regex::new(&pred.value).map_or(false, |re| re.is_match(&text)),
        "not-match?" => regex::Regex::new(&pred.value).map_or(true, |re| !re.is_match(&text)),
        "any-of?" => pred.values.iter().any(|v| v == &text),
        "is?" | "is-not?" | "set!" => true,
        _ => true,
    }
}

fn walk(node: &Node, out: &mut Vec<Node>) {
    out.push(node.clone());
    for c in &node.children {
        walk(c, out);
    }
}

pub fn run_query(root: &Node, source: &str, query_text: &str) -> Result<Vec<(usize, usize)>, String> {
    // Quick syntax validation mirroring tree-sitter errors for obviously invalid queries.
    // A query that does not parse into s-expressions:
    let mut parser = SParser { chars: query_text.chars().collect(), pos: 0, src: query_text };
    let mut tops: Vec<TopPattern> = Vec::new();
    loop {
        parser.skip_ws_comments();
        if parser.pos >= parser.chars.len() { break; }
        // tree-sitter expects patterns to start with '(' or '['; a bare atom like @scope is invalid.
        let c = parser.chars[parser.pos];
        if c != '(' && c != '[' {
            // Build error message in original format
            let snippet: String = query_text.chars().take(60).collect();
            let first_line = snippet.lines().next().unwrap_or("");
            return Err(format!(
                "Error occurred while creating a tree-sitter query: Query error at 1:1. Invalid syntax:\n{}\n^",
                first_line
            ));
        }
        match parser.parse() {
            Ok(exp) => {
                match parse_top(&exp) {
                    Ok(tp) => tops.push(tp),
                    Err(_) => {
                        return Err(format!(
                            "Error occurred while creating a tree-sitter query: Query error at 1:1. Invalid syntax:\n{}\n^",
                            query_text.lines().next().unwrap_or("")
                        ));
                    }
                }
            }
            Err(_) => {
                return Err(format!(
                    "Error occurred while creating a tree-sitter query: Query error at 1:1. Invalid syntax:\n{}\n^",
                    query_text.lines().next().unwrap_or("")
                ));
            }
        }
    }
    if tops.is_empty() {
        return Err("Error occurred while creating a tree-sitter query: Query error at 1:1. Invalid syntax:\n\n^".into());
    }
    // Check for unknown node types? tree-sitter errors on invalid node type.
    // We approximate: collect all types present in tree; if a pattern names a type
    // that exists nowhere and is not a plausible grammar type, tree-sitter would error
    // at query creation. Since we cannot know the grammar, we do not error.

    let mut all_nodes: Vec<Node> = Vec::new();
    walk(root, &mut all_nodes);
    let mut ranges: Vec<(usize, usize)> = Vec::new();
    for node in &all_nodes {
        for top in &tops {
            let mut caps: CapMap = Vec::new();
            if match_pattern(&top.pattern, node, source, &mut caps) {
                if top.predicates.iter().all(|p| predicate_ok(p, &caps)) {
                    for (_, (s, e, _)) in &caps {
                        if e > s {
                            ranges.push((*s, *e));
                        }
                    }
                }
            }
        }
    }
    Ok(crate::langs::merge_ranges(ranges))
}
