// Tokeniser + structural scopes for C, C#, Go, Rust and TypeScript.
use super::query::Node;
use super::{merge_ranges, name_matches, LangKind, ScopeKind};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TK {
    Ident,
    Number,
    Str,
    Char,
    Comment,
    Punct,
    RegexLit,
}

#[derive(Clone, Debug)]
pub struct Token {
    pub kind: TK,
    pub start: usize,
    pub end: usize,
    pub str_segments: Vec<(usize, usize)>, // for Str tokens
}

impl Token {
    pub fn text<'a>(&self, src: &'a str) -> &'a str {
        &src[self.start..self.end]
    }
}

fn is_ident_start(c: char) -> bool {
    c.is_alphabetic() || c == '_' || c == '$'
}
fn is_ident_cont(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '$'
}

// ---------- lexing ----------

pub fn lex(lang: LangKind, src: &str) -> Vec<Token> {
    let chars: Vec<(usize, char)> = src.char_indices().collect();
    let mut toks = Vec::new();
    let mut i = 0usize; // index into chars
    let byte_at = |i: usize, chars: &Vec<(usize, char)>| -> usize {
        if i < chars.len() { chars[i].0 } else { src.len() }
    };
    let peek = |i: usize, chars: &Vec<(usize, char)>| -> Option<char> { chars.get(i).map(|&(_, c)| c) };
    let starts = |i: usize, pat: &str, chars: &Vec<(usize, char)>| -> bool {
        let b = byte_at(i, chars);
        src[b..].starts_with(pat)
    };
    let mut prev_expr_end = false; // for TS regex heuristic
    while i < chars.len() {
        let (b, c) = chars[i];
        if c.is_whitespace() { i += 1; continue; }
        // preprocessor line (C/C#): handle #include <...> as string
        if c == '#' {
            let line_start = src[..b].rfind('\n').map_or(0, |p| p + 1);
            if src[line_start..b].trim().is_empty() && matches!(lang, LangKind::C | LangKind::CSharp) {
                // scan directive word
                let mut j = i + 1;
                while peek(j, &chars).map_or(false, |ch| ch.is_alphabetic()) { j += 1; }
                let directive: String = chars[i+1..j].iter().map(|&(_, ch)| ch).collect();
                if directive == "include" {
                    // find <...> or "..." on same line
                    let mut k = j;
                    while peek(k, &chars).map_or(false, |ch| ch == ' ' || ch == '\t') { k += 1; }
                    if peek(k, &chars) == Some('<') {
                        let start_b = byte_at(k, &chars);
                        let mut m = k;
                        while m < chars.len() && chars[m].1 != '>' && chars[m].1 != '\n' { m += 1; }
                        if m < chars.len() && chars[m].1 == '>' {
                            let end_b = byte_at(m + 1, &chars);
                            // emit punct # , ident include, string
                            toks.push(Token{kind:TK::Punct,start:b,end:byte_at(i+1,&chars),str_segments:vec![]});
                            toks.push(Token{kind:TK::Ident,start:byte_at(i+1,&chars),end:byte_at(j,&chars),str_segments:vec![]});
                            toks.push(Token{kind:TK::Str,start:start_b,end:end_b,str_segments:vec![(start_b,end_b)]});
                            i = m + 1;
                            prev_expr_end = true;
                            continue;
                        }
                    }
                }
            }
            toks.push(Token{kind:TK::Punct,start:b,end:byte_at(i+1,&chars),str_segments:vec![]});
            i += 1; prev_expr_end = false; continue;
        }
        // comments
        if starts(i, "//", &chars) {
            let mut j = i;
            while j < chars.len() && chars[j].1 != '\n' { j += 1; }
            toks.push(Token{kind:TK::Comment,start:b,end:byte_at(j,&chars),str_segments:vec![]});
            i = j; continue;
        }
        if starts(i, "/*", &chars) {
            let mut depth = 1i32;
            let mut j = i + 2;
            let nested = lang == LangKind::Rust;
            while j < chars.len() && depth > 0 {
                if starts(j, "/*", &chars) { if nested { depth += 1; } j += 2; }
                else if starts(j, "*/", &chars) { depth -= 1; j += 2; if !nested { break; } }
                else { j += 1; }
            }
            toks.push(Token{kind:TK::Comment,start:b,end:byte_at(j,&chars),str_segments:vec![]});
            i = j; continue;
        }
        // string starts: language specific prefixes
        if let Some((end_b, segs, consumed)) = try_string(lang, src, &chars, i) {
            toks.push(Token{kind:TK::Str,start:b,end:end_b,str_segments:segs});
            i = consumed;
            prev_expr_end = true;
            continue;
        }
        // char literal attempt
        if c == '\'' {
            if let Some((end_b, consumed)) = try_char(src, &chars, i) {
                toks.push(Token{kind:TK::Char,start:b,end:end_b,str_segments:vec![]});
                i = consumed; prev_expr_end = true; continue;
            }
            toks.push(Token{kind:TK::Punct,start:b,end:byte_at(i+1,&chars),str_segments:vec![]});
            i += 1; prev_expr_end = false; continue;
        }
        // TS regex literal
        if lang == LangKind::TypeScript && c == '/' && !prev_expr_end {
            if let Some((end_b, consumed)) = try_regex_lit(src, &chars, i) {
                toks.push(Token{kind:TK::RegexLit,start:b,end:end_b,str_segments:vec![]});
                i = consumed; prev_expr_end = true; continue;
            }
        }
        // raw identifier rust r#name
        if lang == LangKind::Rust && c == 'r' && peek(i+1,&chars) == Some('#') && peek(i+2,&chars).map_or(false, is_ident_start) {
            let mut j = i + 2;
            while j < chars.len() && is_ident_cont(chars[j].1) { j += 1; }
            toks.push(Token{kind:TK::Ident,start:b,end:byte_at(j,&chars),str_segments:vec![]});
            i = j; prev_expr_end = true; continue;
        }
        // identifiers (incl C# @ident)
        if is_ident_start(c) || (lang == LangKind::CSharp && c == '@' && peek(i+1,&chars).map_or(false, is_ident_start)) {
            let mut j = i;
            if chars[j].1 == '@' { j += 1; }
            while j < chars.len() && is_ident_cont(chars[j].1) { j += 1; }
            // Go/C etc: identifier may be string prefix handled before, so fine
            toks.push(Token{kind:TK::Ident,start:b,end:byte_at(j,&chars),str_segments:vec![]});
            i = j; prev_expr_end = true; continue;
        }
        if c.is_ascii_digit() {
            let mut j = i;
            while j < chars.len() {
                let ch = chars[j].1;
                if ch.is_alphanumeric() || ch == '_' || (ch == '.' && peek(j+1,&chars).map_or(false, |n| n.is_ascii_digit())) { j += 1; } else { break; }
            }
            toks.push(Token{kind:TK::Number,start:b,end:byte_at(j,&chars),str_segments:vec![]});
            i = j; prev_expr_end = true; continue;
        }
        // punctuation longest
        let rest = &src[b..];
        let puncts = ["<<=", ">>=", "...", "..=", "->", "=>", "==", "!=", "<=", ">=", "&&", "||", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "::", ":=", "..", "?.", "??", "**", "<-", "&&"];
        let mut matched: Option<&str> = None;
        for p in puncts {
            if rest.starts_with(p) { matched = Some(p); break; }
        }
        if let Some(p) = matched {
            let end_b = b + p.len();
            toks.push(Token{kind:TK::Punct,start:b,end:end_b,str_segments:vec![]});
            i += p.chars().count();
            prev_expr_end = matches!(p, ")" | "]" | "}" | "++" | "--");
            // incorrect kinds for ')': tokens are Punct with text ')', prev_expr_end set by text check below instead
            if p == ")" || p == "]" || p == "}" { prev_expr_end = true; }
            continue;
        }
        // single char punct
        toks.push(Token{kind:TK::Punct,start:b,end:byte_at(i+1,&chars),str_segments:vec![]});
        prev_expr_end = matches!(c, ')' | ']' | '}');
        i += 1;
    }
    toks
}

fn byte_at_idx(chars: &[(usize, char)], i: usize, src: &str) -> usize {
    if i < chars.len() { chars[i].0 } else { src.len() }
}

// Returns (end_byte, segments, consumed_char_index)
fn try_string(lang: LangKind, src: &str, chars: &[(usize, char)], i: usize) -> Option<(usize, Vec<(usize, usize)>, usize)> {
    let b = byte_at_idx(chars, i, src);
    let rest = &src[b..];
    match lang {
        LangKind::Rust => {
            // r"...", r#"..."#, br"...", b"..."
            let mut prefix_len = 0usize;
            let mut raw_hashes: Option<usize> = None;
            if rest.starts_with("br") || rest.starts_with('r') {
                let mut idx = if rest.starts_with("br") { 2 } else { 1 };
                let mut hashes = 0usize;
                while rest[idx..].starts_with('#') { hashes += 1; idx += 1; }
                if rest[idx..].starts_with('"') {
                    raw_hashes = Some(hashes);
                    prefix_len = idx; // chars before quote (ascii)
                }
            }
            if let Some(hashes) = raw_hashes {
                let content_start = b + prefix_len + 1;
                let closing = format!("\"{}", "#".repeat(hashes));
                if let Some(pos) = src[content_start..].find(&closing) {
                    let content_end = content_start + pos;
                    let end_b = content_end + closing.len();
                    let consumed = i + src[b..end_b].chars().count();
                    return Some((end_b, vec![(content_start, content_end)], consumed));
                } else {
                    let consumed = chars.len();
                    return Some((src.len(), vec![(content_start, src.len())], consumed));
                }
            }
            if rest.starts_with("b\"") || rest.starts_with('"') {
                let prefix = if rest.starts_with("b\"") { 1 } else { 0 };
                return scan_regular_string(src, chars, i + prefix, true);
            }
            None
        }
        LangKind::Go => {
            if rest.starts_with('`') {
                let content_start = b + 1;
                if let Some(pos) = src[content_start..].find('`') {
                    let end_b = content_start + pos + 1;
                    let consumed = i + src[b..end_b].chars().count();
                    return Some((end_b, vec![(b, end_b)], consumed));
                }
                return Some((src.len(), vec![(b, src.len())], chars.len()));
            }
            if rest.starts_with('"') {
                let (end_b, _segs, consumed) = scan_regular_string(src, chars, i, false)?;
                return Some((end_b, vec![(b, end_b)], consumed));
            }
            None
        }
        LangKind::C => {
            // optional prefix u8,u,U,L before quote
            let mut pre = 0usize;
            for p in ["u8", "u", "U", "L"] {
                if rest.starts_with(p) && rest[p.len()..].starts_with('"') { pre = p.len(); break; }
            }
            if rest[pre..].starts_with('"') {
                let (end_b, _s, consumed) = scan_regular_string(src, chars, i + pre, false)?;
                return Some((end_b, vec![(b, end_b)], consumed));
            }
            None
        }
        LangKind::CSharp => {
            // prefixes: $@" @ $" combos: $@"..." @$"..." $"..." @"..." "..."
            let mut pre: Option<usize> = None;
            let mut verbatim = false;
            let mut interp = false;
            for (p, v, it) in [("$@\"", true, true), ("@$\"", true, true), ("$\"", false, true), ("@\"", true, false), ("\"", false, false)] {
                if rest.starts_with(p) { pre = Some(p.len() - 1); verbatim = v; interp = it; break; }
            }
            let pre = pre?;
            if verbatim {
                // content starts after quote at b+pre
                let content_start = b + pre + 1;
                let mut j = content_start;
                let bytes = src.as_bytes();
                while j < src.len() {
                    if bytes[j] == b'"' {
                        if j + 1 < src.len() && bytes[j+1] == b'"' { j += 2; continue; }
                        break;
                    }
                    j += 1;
                }
                let content_end = j.min(src.len());
                let end_b = if j < src.len() { j + 1 } else { j };
                let consumed = i + src[b..end_b].chars().count();
                if interp {
                    let segs = interp_segments(src, b, end_b, content_start, content_end);
                    return Some((end_b, segs, consumed));
                }
                return Some((end_b, vec![(b, end_b)], consumed));
            } else {
                let (end_b, _s, consumed) = scan_regular_string(src, chars, i + pre, false)?;
                if interp {
                    let content_start = b + pre + 1;
                    let content_end = if end_b > content_start { end_b - 1 } else { end_b };
                    let segs = interp_segments(src, b, end_b, content_start, content_end);
                    return Some((end_b, segs, consumed));
                }
                return Some((end_b, vec![(b, end_b)], consumed));
            }
        }
        LangKind::TypeScript => {
            if rest.starts_with('`') {
                // template
                return scan_template_string(src, chars, i);
            }
            if rest.starts_with('"') || rest.starts_with('\'') {
                // content segments split by escapes, exclude quotes
                let (end_b, segs, consumed) = scan_regular_string(src, chars, i, true)?;
                // scan_regular_string with split=true returns content segments excluding escapes
                // but it includes? It returns segments between quotes excluding escape sequences
                return Some((end_b, segs, consumed));
            }
            None
        }
        _ => None,
    }
}

fn interp_segments(src: &str, tok_start: usize, tok_end: usize, content_start: usize, content_end: usize) -> Vec<(usize, usize)> {
    // C# interpolated segments: from token start to '{' of interpolation,
    // then after '}' to next '{' or to tok_end (incl closing quote)
    let mut segs = Vec::new();
    let mut seg_start = tok_start;
    let mut j = content_start;
    let bytes = src.as_bytes();
    while j < content_end {
        if bytes[j] == b'{' {
            if j + 1 < content_end && bytes[j+1] == b'{' { j += 2; continue; }
            // segment up to j
            if j > seg_start { segs.push((seg_start, j)); }
            // skip interpolation to matching }
            let mut depth = 1i32;
            j += 1;
            while j < content_end && depth > 0 {
                if bytes[j] == b'{' { depth += 1; }
                else if bytes[j] == b'}' { depth -= 1; }
                // strings inside interp ignored roughly (braces inside strings rare)
                j += 1;
            }
            seg_start = j;
        } else if bytes[j] == b'}' && j + 1 < src.len() && bytes[j+1] == b'}' {
            j += 2;
        } else {
            j += 1;
        }
    }
    if tok_end > seg_start { segs.push((seg_start, tok_end)); }
    segs
}

// scan a "..." or '...' starting at char index iq (index of opening quote char in chars offset adjusted)
// `i` param is char index of opening quote. If split_escape, segments exclude escape sequences.
fn scan_regular_string(src: &str, chars: &[(usize, char)], i: usize, split_escape: bool) -> Option<(usize, Vec<(usize, usize)>, usize)> {
    let b = byte_at_idx(chars, i, src);
    let quote = src[b..].chars().next()?;
    if quote != '"' && quote != '\'' { return None; }
    let content_start = b + 1;
    let mut j = i + 1;
    let mut segs: Vec<(usize, usize)> = Vec::new();
    let mut seg_start = content_start;
    while j < chars.len() {
        let (cb, c) = chars[j];
        if c == '\\' {
            if split_escape {
                if cb > seg_start { segs.push((seg_start, cb)); }
                // skip escape: \ + next char, plus possible following for \u{...} \x.. etc included in escape run
                j += 1;
                if j < chars.len() {
                    // handle \u{...}
                    if chars[j].1 == 'u' && j + 1 < chars.len() && chars[j+1].1 == '{' {
                        while j < chars.len() && chars[j].1 != '}' { j += 1; }
                        if j < chars.len() { j += 1; }
                    } else {
                        j += 1;
                    }
                }
                seg_start = byte_at_idx(chars, j, src);
                continue;
            } else {
                j += 2;
                continue;
            }
        }
        if c == quote {
            let end_b = cb + 1;
            if split_escape {
                if cb > seg_start { segs.push((seg_start, cb)); }
            } else {
                segs = vec![(content_start, cb)];
            }
            return Some((end_b, segs, j + 1));
        }
        if c == '\n' && quote != '`' {
            // unterminated
            let end_b = cb;
            if split_escape {
                if cb > seg_start { segs.push((seg_start, cb)); }
            } else {
                segs = vec![(content_start, cb)];
            }
            return Some((end_b, segs, j));
        }
        j += 1;
    }
    let end_b = src.len();
    if split_escape {
        if end_b > seg_start { segs.push((seg_start, end_b)); }
    } else {
        segs = vec![(content_start, end_b)];
    }
    Some((end_b, segs, j))
}

fn scan_template_string(src: &str, chars: &[(usize, char)], i: usize) -> Option<(usize, Vec<(usize, usize)>, usize)> {
    let b = byte_at_idx(chars, i, src);
    let mut segs = Vec::new();
    let mut seg_start = b + 1;
    let mut j = i + 1;
    while j < chars.len() {
        let (cb, c) = chars[j];
        if c == '\\' { j += 2; continue; }
        if c == '`' {
            if cb > seg_start { segs.push((seg_start, cb)); }
            return Some((cb + 1, segs, j + 1));
        }
        if c == '$' && j + 1 < chars.len() && chars[j+1].1 == '{' {
            if cb > seg_start { segs.push((seg_start, cb)); }
            // skip interpolation nested
            let mut depth = 1i32;
            j += 2;
            while j < chars.len() && depth > 0 {
                let ch = chars[j].1;
                if ch == '{' { depth += 1; }
                else if ch == '}' { depth -= 1; }
                else if ch == '"' || ch == '\'' || ch == '`' {
                    // skip nested string roughly
                    if let Some((_, _, consumed)) = if ch == '`' { scan_template_string(src, chars, j) } else { scan_regular_string(src, chars, j, true) } {
                        j = consumed;
                        continue;
                    }
                } else if ch == '\\' { j += 1; }
                j += 1;
            }
            seg_start = byte_at_idx(chars, j, src);
            continue;
        }
        j += 1;
    }
    if src.len() > seg_start { segs.push((seg_start, src.len())); }
    Some((src.len(), segs, j))
}

fn try_char(src: &str, chars: &[(usize, char)], i: usize) -> Option<(usize, usize)> {
    // 'x' or '\n' etc; must close within few chars and not be a lifetime
    let mut j = i + 1;
    if j >= chars.len() { return None; }
    if chars[j].1 == '\\' {
        // escape: skip to closing '
        j += 1;
        while j < chars.len() && chars[j].1 != '\'' && chars[j].1 != '\n' {
            // \u{...}
            if chars[j].1 == '{' {
                while j < chars.len() && chars[j].1 != '}' { j += 1; }
            }
            j += 1;
        }
        if j < chars.len() && chars[j].1 == '\'' {
            return Some((byte_at_idx(chars, j + 1, src), j + 1));
        }
        return None;
    }
    // single char then '
    if j + 1 < chars.len() && chars[j+1].1 == '\'' {
        // char cannot be newline etc
        if chars[j].1 == '\n' { return None; }
        return Some((byte_at_idx(chars, j + 2, src), j + 2));
    }
    None
}

fn try_regex_lit(src: &str, chars: &[(usize, char)], i: usize) -> Option<(usize, usize)> {
    let mut j = i + 1;
    let mut in_class = false;
    while j < chars.len() {
        let c = chars[j].1;
        if c == '\\' { j += 2; continue; }
        if c == '[' { in_class = true; }
        else if c == ']' { in_class = false; }
        else if c == '/' && !in_class {
            // flags
            let mut k = j + 1;
            while k < chars.len() && chars[k].1.is_alphabetic() { k += 1; }
            return Some((byte_at_idx(chars, k, src), k));
        }
        else if c == '\n' { return None; }
        j += 1;
    }
    None
}

// ---------- helpers over tokens ----------

pub fn sig_tokens<'a>(toks: &'a [Token]) -> Vec<&'a Token> {
    // comments are significant for some things but structural parsing usually skips them;
    // callers filter as needed. Here return all.
    toks.iter().collect()
}

pub fn matching(toks: &[Token], mut idx: usize, open: &str, close: &str, src: &str) -> Option<usize> {
    let mut depth = 0i32;
    while idx < toks.len() {
        let t = toks[idx].text(src);
        if t == open { depth += 1; }
        else if t == close { depth -= 1; if depth == 0 { return Some(idx); } }
        idx += 1;
    }
    None
}

pub fn is_kw(tok: &Token, src: &str, kw: &str) -> bool {
    tok.kind == TK::Ident && tok.text(src) == kw
}

pub fn find_block_end(toks: &[Token], open_idx: usize, src: &str) -> Option<usize> {
    matching(toks, open_idx, "{", "}", src)
}

// Build a map of enclosing brace-block classification: for each token index,
// the stack of (open brace token index) enclosing it.
pub fn brace_stacks(toks: &[Token], src: &str) -> Vec<Vec<usize>> {
    let mut stacks: Vec<Vec<usize>> = Vec::with_capacity(toks.len());
    let mut stack: Vec<usize> = Vec::new();
    for (i, t) in toks.iter().enumerate() {
        let txt = t.text(src);
        if txt == "}" {
            stacks.push(stack.clone());
            stack.pop();
        } else {
            stacks.push(stack.clone());
            if txt == "{" { stack.push(i); }
        }
    }
    stacks
}

// rust vis parsing helper
pub fn parse_visibility(toks: &[Token], src: &str, start_idx: usize) -> Option<(String, usize)> {
    // returns (kind, next_idx) if tokens[start] is pub...
    // kind: "pub", "pub(crate)", "pub(self)", "pub(super)", "pub(in ...)" etc
    if start_idx < toks.len() && is_kw(&toks[start_idx], src, "pub") {
        if start_idx + 1 < toks.len() && toks[start_idx+1].text(src) == "(" {
            if let Some(close) = matching(toks, start_idx+1, "(", ")", src) {
                let inner: String = toks[start_idx+2..close].iter().map(|t| t.text(src)).collect::<Vec<_>>().join("");
                return Some((format!("pub({})", inner), close + 1));
            }
        }
        return Some(("pub".to_string(), start_idx + 1));
    }
    None
}
