            }
            toks.push(Token{kind:TK::Number,start:b,end:byte_at(j,&chars),str_segments:vec![]});
            i = j; prev_expr_end = true; continue;
        }
        // punctuation longest
        let rest = &src[b..];
        let puncts = ["<<=", ">>=", "...", "..=", "->", "=>", "==", "!=", "<=", ">=", "&&", "||", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "::", ":=", "..", "?.", "??", "**", "<-", "&&"];
