fn line_bounds(src: &str, pos: usize) -> (usize, usize) {
    let start = src[..pos.min(src.len())].rfind('\n').map_or(0, |p| p + 1);
    let end = src[pos.min(src.len())..].find('\n').map_or(src.len(), |p| pos + p);
