// ---------- prepared scopes ----------

pub fn prepared(lang: LangKind, value: &str, src: &str) -> Vec<(usize, usize)> {
    let (base, pat) = ScopeKind::split_dyn(value);
    match lang {
        LangKind::Go => go_prepared(&base, pat.as_deref(), src),
        LangKind::Rust => rust_prepared(&base, pat.as_deref(), src),
        LangKind::C => c_prepared(&base, src),
        LangKind::CSharp => csharp_prepared(&base, src),
        LangKind::TypeScript => ts_prepared(&base, src),
        _ => vec![],
    }
}

fn code_tokens(lang: LangKind, src: &str) -> Vec<Token> {
    lex(lang, src).into_iter().filter(|t| t.kind != TK::Comment).collect()
}

fn comments_ranges(lang: LangKind, src: &str) -> Vec<(usize, usize)> {
    lex(lang, src).into_iter().filter(|t| t.kind == TK::Comment).map(|t| (t.start, t.end)).collect()
}

fn line_bounds(src: &str, pos: usize) -> (usize, usize) {
    let start = src[..pos.min(src.len())].rfind('\n').map_or(0, |p| p + 1);
    let end = src[pos.min(src.len())..].find('\n').map_or(src.len(), |p| pos + p);
    (start, end)
}

// Find end of a statement starting at token `start`: block if brace found before ';'
// at paren depth 0, else up to and including ';' or end of line segment.
fn statement_end(toks: &[Token], src: &str, start: usize) -> usize {
    let mut par = 0i32;
    let mut i = start;
    while i < toks.len() {
        let t = toks[i].text(src);
        match t {
            "(" | "[" => par += 1,
            ")" | "]" => par -= 1,
            "{" if par == 0 => {
                if let Some(close) = matching(toks, i, "{", "}", src) {
                    return close;
                }
                return i;
            }
            ";" if par == 0 => return i,
            _ => {}
        }
        i += 1;
    }
    toks.len().saturating_sub(1)
}

// ---------- Go ----------

fn go_prepared(base: &str, pat: Option<&str>, src: &str) -> Vec<(usize, usize)> {
    let all = lex(LangKind::Go, src);
    let code: Vec<Token> = all.iter().filter(|t| t.kind != TK::Comment).cloned().collect();
    match base {
        "comments" => return comments_ranges(LangKind::Go, src),
        "strings" | "imports" | "struct-tags" => {
            // determine import and struct-tag context for each string token
            // import context: inside import declaration
            let mut ranges = Vec::new();
            // Precompute tokens ranges of import specs and struct blocks
            let mut in_import = vec![false; all.len()];
            let mut i = 0;
            while i < all.len() {
                if is_kw(&all[i], src, "import") {
                    // import could be grouped '(' or single
                    let mut j = i + 1;
                    if j < all.len() && all[j].text(src) == "(" {
                        if let Some(close) = matching(&all, j, "(", ")", src) {
                            for k in j..=close { in_import[k] = true; }
                            i = close + 1;
                            continue;
                        }
                    } else {
                        // to end of line
                        let (_, lend) = line_bounds(src, all[i].start);
                        while j < all.len() && all[j].start < lend { in_import[j] = true; j += 1; }
                        i = j;
                        continue;
                    }
                }
                i += 1;
            }
            // struct blocks: token indices of '{' that follow `struct` (possibly with type params etc)
            let mut struct_braces: Vec<(usize, usize)> = Vec::new(); // (open token idx, close token idx) in `all`
            for (idx, t) in all.iter().enumerate() {
                if is_kw(t, src, "struct") {
                    // find next '{' before newline? Could be struct{...} inline
                    let mut j = idx + 1;
                    while j < all.len() && all[j].text(src) != "{" && all[j].text(src) != ";" {
                        // stop if we hit a token that suggests not a struct type (rare)
                        j += 1;
                        if j > idx + 6 { break; }
                    }
                    if j < all.len() && all[j].text(src) == "{" {
                        if let Some(close) = matching(&all, j, "{", "}", src) {
                            struct_braces.push((j, close));
                        }
                    }
                }
            }
            for (idx, t) in all.iter().enumerate() {
                if t.kind != TK::Str { continue; }
                let is_tag = t.text(src).starts_with('`') && struct_braces.iter().any(|(o, c)| idx > *o && idx < *c);
                match base {
                    "strings" => {
                        if !in_import[idx] && !is_tag {
                            ranges.push((t.start, t.end));
                        }
                    }
                    "imports" => {
                        if in_import[idx] { ranges.push((t.start, t.end)); }
                    }
                    "struct-tags" => {
                        if is_tag { ranges.push((t.start, t.end)); }
                    }
                    _ => {}
                }
            }
            return ranges;
        }
        _ => {}
    }
    // structural go scopes based on code tokens
    let mut out = Vec::new();
    match base {
        "type-def" | "type-alias" | "struct" | "interface" => {
            // find type declarations
            let mut i = 0;
            while i < code.len() {
                if is_kw(&code[i], src, "type") {
                    let decl_start = code[i].start;
                    // grouped?
                    if i + 1 < code.len() && code[i+1].text(src) == "(" {
                        if let Some(close) = matching(&code, i+1, "(", ")", src) {
                            let decl_end = code[close].end;
                            // specs inside: lines identify spec starts
                            let specs = go_type_specs(&code, src, i+2, close);
                            let has_struct = specs.iter().any(|s| s.kind == "struct");
                            let has_iface = specs.iter().any(|s| s.kind == "iface");
                            match base {
                                "type-def" => out.push((decl_start, decl_end)),
                                "type-alias" => {
                                    for s in &specs { if s.alias { out.push((s.name_start, s.end)); } }
                                }
                                "struct" => {
                                    if has_struct { out.push((decl_start, decl_end)); }
                                    else { let _ = has_struct; }
                                }
                                "interface" => {
                                    if has_iface { out.push((decl_start, decl_end)); }
                                }
                                _ => {}
                            }
                            i = close + 1;
                            continue;
                        }
                    } else if i + 1 < code.len() {
                        // single spec from i+1
                        let specs = go_type_specs(&code, src, i+1, code.len());
                        if let Some(s) = specs.first() {
                            let single_end = s.end;
                            let name_ok = pat.map_or(true, |p| name_matches(p, &s.name));
                            match base {
                                "type-def" => out.push((decl_start, single_end)),
                                "type-alias" => if s.alias { out.push((s.name_start, s.end)); },
                                "struct" => if s.kind == "struct" && name_ok { out.push((decl_start, single_end)); },
                                "interface" => if s.kind == "iface" && name_ok { out.push((decl_start, single_end)); },
                                _ => {}
                            }
                            // advance beyond spec: find token whose end >= single_end
                            let mut j = i + 1;
                            while j < code.len() && code[j].start < single_end { j += 1; }
                            i = j;
                            continue;
                        }
                    }
                }
                i += 1;
            }
            return merge_ranges(out);
        }
        "type-params" => {
            // after type names in type decls and func names
            let mut ranges = Vec::new();
            let mut i = 0;
            while i < code.len() {
                // func Name[ or type Name[
                if (is_kw(&code[i], src, "func") || is_kw(&code[i], src, "type")) && i + 2 < code.len() {
                    // name is next ident (for func, may be '(' for method: receiver then name)
                    let mut name_idx: Option<usize> = None;
                    if code[i+1].kind == TK::Ident { name_idx = Some(i+1); }
                    else if code[i+1].text(src) == "(" {
                        if let Some(close) = matching(&code, i+1, "(", ")", src) {
                            if close + 1 < code.len() && code[close+1].kind == TK::Ident { name_idx = Some(close+1); }
                        }
                    }
                    if let Some(ni) = name_idx {
                        if ni + 1 < code.len() && code[ni+1].text(src) == "[" {
                            if let Some(close) = matching(&code, ni+1, "[", "]", src) {
                                ranges.push((code[ni+1].start, code[close].end));
                            }
                        }
                    }
                }
                // also type spec inside group: lines starting with Name[
                i += 1;
            }
            // grouped type specs
            // (handled crudely: Name[ at start of a line inside type (...) )
            return ranges;
        }
        "const" | "var" => {
            let kw = base;
            let mut i = 0;
            while i < code.len() {
                if is_kw(&code[i], src, kw) {
                    if i + 1 < code.len() && code[i+1].text(src) == "(" {
                        if let Some(close) = matching(&code, i+1, "(", ")", src) {
                            // specs are lines inside
                            let mut line_start_tok = i + 2;
                            // iterate by lines
                            let mut cur_line: Option<usize> = None;
                            let mut first_tok: Option<usize> = None;
                            let mut last_tok: Option<usize> = None;
                            let push_spec = |out: &mut Vec<(usize,usize)>, first: Option<usize>, last: Option<usize>| {
                                if let (Some(f), Some(l)) = (first, last) { out.push((code[f].start, code[l].end)); }
                            };
                            for j in i+2..close {
                                let ln = src[..code[j].start].matches('\n').count();
                                match cur_line {
                                    None => { cur_line = Some(ln); first_tok = Some(j); last_tok = Some(j); }
                                    Some(cl) if cl == ln => { last_tok = Some(j); }
                                    Some(_) => {
                                        push_spec(&mut out, first_tok, last_tok);
                                        cur_line = Some(ln); first_tok = Some(j); last_tok = Some(j);
                                    }
                                }
                                let _ = line_start_tok; line_start_tok = j;
                            }
                            push_spec(&mut out, first_tok, last_tok);
                            i = close + 1;
                            continue;
                        }
                    } else if i + 1 < code.len() {
                        // single spec: from name token to end of line
                        let (_, lend) = line_bounds(src, code[i].end);
                        let mut last = i + 1;
                        let mut j = i + 1;
                        while j < code.len() && code[j].start < lend { last = j; j += 1; }
                        out.push((code[i+1].start, code[last].end));
                        i = j;
                        continue;
                    }
                }
                i += 1;
            }
            return merge_ranges(out);
        }
        "func" | "method" | "free-func" | "init-func" => {
            for f in go_funcs(&code, src) {
                let name_ok = pat.map_or(true, |p| name_matches(p, &f.name));
                match base {
                    "func" => out.push((f.start, f.end)),
                    "method" => if f.is_method { out.push((f.start, f.end)); },
                    "free-func" => if !f.is_method && !f.is_literal { out.push((f.start, f.end)); },
                    "init-func" => if f.name == "init" && !f.is_method { out.push((f.start, f.end)); },
                    _ => {}
                }
                let _ = name_ok;
            }
            // func~PATTERN handled via base string containing '~' ? Caller split: base for func pattern case is "func"
            // go_funcs called again with pattern filtering below if pat present and base=="func"
            if let (Some(p), "func") = (pat, base) {
                // redo filtered
                out.clear();
                for f in go_funcs(&code, src) {
                    if name_matches(p, &f.name) { out.push((f.start, f.end)); }
                }
            }
            return merge_ranges(out);
        }
        "defer" | "go" | "select" | "switch" | "goto" | "labeled" => {
            return go_statements(base, &code, src);
        }
        "expression" => {
            // Approximate: whole expression-ish spans: string/number/ident tokens,
            // call expressions, selector chains, and initialiser values.
            // We collect: call expressions (ident.selector(...) etc), literals,
            // identifiers, and binary-like spans will be merged via contained pieces.
            let mut ranges = Vec::new();
            // call expressions and composite literals roughly:
            let mut i = 0;
            while i < code.len() {
                let t = &code[i];
                if t.kind == TK::Str || t.kind == TK::Number {
                    ranges.push((t.start, t.end));
                } else if t.kind == TK::Ident {
                    // selector chain / call
                    let mut j = i;
                    // consume ident (.ident)* 
                    while j + 2 < code.len() && code[j+1].text(src) == "." && code[j+2].kind == TK::Ident {
                        j += 2;
                    }
                    if j + 1 < code.len() && code[j+1].text(src) == "(" {
                        if let Some(close) = matching(&code, j+1, "(", ")", src) {
                            ranges.push((code[i].start, code[close].end));
                            i = close + 1;
                            continue;
                        }
                    }
                    // bare identifier expression (but skip keywords/declaration names roughly)
                    let word = t.text(src);
                    if !matches!(word, "func"|"type"|"var"|"const"|"package"|"import"|"return"|"if"|"for"|"switch"|"select"|"case"|"defer"|"go"|"goto"|"struct"|"interface"|"map"|"chan") {
                        ranges.push((t.start, t.end));
                    }
                    i = j + 1;
                    continue;
                }
                i += 1;
            }
            return merge_ranges(ranges);
        }
        _ => {}
    }
    out
}

struct GoFunc { start: usize, end: usize, name: String, is_method: bool, is_literal: bool }

fn go_funcs(code: &[Token], src: &str) -> Vec<GoFunc> {
    let mut funcs = Vec::new();
    let mut i = 0;
    while i < code.len() {
        if is_kw(&code[i], src, "func") {
            let start = code[i].start;
            let mut name = String::new();
            let mut is_method = false;
            let mut is_literal = false;
            let mut body_open: Option<usize> = None;
            let mut sig_end_tok: Option<usize> = None;
            if i + 1 < code.len() && code[i+1].kind == TK::Ident {
                name = code[i+1].text(src).to_string();
                // find '{' at paren/bracket depth 0 or ';'/newline signature end
                let mut j = i + 1;
                let mut par = 0i32; let mut br = 0i32;
                while j < code.len() {
                    let t = code[j].text(src);
                    match t { "(" | "[" => { if t=="(" {par+=1} else {br+=1} }, ")" | "]" => { if t=="(" {par-=1} else {br-=1} },
                        "{" if par==0 && br==0 => { body_open = Some(j); break; }
                        ";" if par==0 && br==0 => { sig_end_tok = Some(j); break; }
                        _ => {}
                    }
                    j += 1;
                }
            } else if i + 1 < code.len() && code[i+1].text(src) == "(" {
                if let Some(close) = matching(&code, i+1, "(", ")", src) {
                    if close + 1 < code.len() && code[close+1].kind == TK::Ident {
                        is_method = true;
                        name = code[close+1].text(src).to_string();
                        let mut j = close + 1;
                        let mut par = 0i32; let mut br = 0i32;
                        while j < code.len() {
                            let t = code[j].text(src);
                            match t { "(" => par+=1, "[" => br+=1, ")" => par-=1, "]" => br-=1,
                                "{" if par==0 && br==0 => { body_open = Some(j); break; }
                                ";" if par==0 && br==0 => { sig_end_tok = Some(j); break; }
                                _ => {}
                            }
                            j += 1;
                        }
                    } else {
                        is_literal = true;
                        // func literal: params close, then optional results then '{'
                        let mut j = close + 1;
                        let mut par = 0i32;
                        while j < code.len() {
                            let t = code[j].text(src);
                            match t { "(" => par+=1, ")" => par-=1,
                                "{" if par==0 => { body_open = Some(j); break; }
                                ";" if par==0 => { sig_end_tok = Some(j); break; }
                                _ => {}
                            }
                            j += 1;
                        }
                    }
                }
            } else {
                i += 1;
                continue;
            }
            if let Some(open) = body_open {
                if let Some(close) = matching(&code, open, "{", "}", src) {
                    funcs.push(GoFunc{start, end: code[close].end, name, is_method, is_literal});
                    // do not skip body: nested func literals should be found
                    i += 1;
                    continue;
                }
            } else if let Some(endt) = sig_end_tok {
                // declarations without body are not func scope (interface methods etc use different nodes)
                let _ = endt;
            }
            i += 1;
            continue;
        }
        i += 1;
    }
    funcs
}

struct GoTypeSpec { name: String, name_start: usize, end: usize, alias: bool, kind: String }

fn go_type_specs(code: &[Token], src: &str, from: usize, upto: usize) -> Vec<GoTypeSpec> {
    // Each spec starts at a line start within [from,upto) (or `from` itself).
    // Determine spec starts: token whose previous token is '(' or newline-separated start and kind Ident.
    let mut specs = Vec::new();
    let mut starts: Vec<usize> = Vec::new();
    for idx in from..upto.min(code.len()) {
        if code[idx].kind != TK::Ident { continue; }
        let line_start = if idx == from { true } else {
            let prev_end_line = src[..code[idx].start].matches('\n').count();
            let prev_tok_line = if idx > 0 { src[..code[idx-1].start].matches('\n').count() } else { prev_end_line };
            prev_tok_line < prev_end_line
        };
        // Also spec start could follow '(' directly on same token already covered by idx==from in group case? in group from points after '('
        if line_start {
            // avoid identifiers that are struct field names etc: only if at brace depth 0 relative to spec start
            starts.push(idx);
        }
    }
    // Filter starts to those at top nesting (relative depth of ()/{} ==0)
    let mut filtered: Vec<usize> = Vec::new();
    for &s in &starts {
        let mut depth = 0i32;
        for t in &code[from..s] {
            match t.text(src) { "{" | "(" | "[" => depth += 1, "}" | ")" | "]" => depth -= 1, _ => {} }
        }
        if depth == 0 { filtered.push(s); }
    }
    for (si, &sidx) in filtered.iter().enumerate() {
        let send_tok = if si + 1 < filtered.len() { filtered[si+1] } else { upto };
        // end = last token before next spec or upto; but exclude trailing tokens like ')' (upto is close index)
        let mut end_idx = if send_tok > sidx { send_tok - 1 } else { sidx };
        if upto <= code.len() && upto > 0 && si + 1 == filtered.len() {
            end_idx = upto.saturating_sub(1);
            // If upto==code.len() (single spec), end is the spec statement end: to closing brace of struct/interf or end of line
        }
        // For single spec case where upto==len, compute end by struct/interface block or line
        let end = if upto >= code.len() {
            // find block
            let mut e = code[end_idx.min(code.len()-1)].end;
            for j in sidx..code.len() {
                if code[j].text(src) == "{" {
                    if let Some(close) = matching(code, j, "{", "}", src) { e = code[close].end; break; }
                }
                if src[code[j].start..].starts_with('\n') { }
            }
            // if no block, end of line of name
            // refine: if no brace found, use line end tokens
            let has_brace = (sidx..code.len()).any(|j| code[j].text(src) == "{");
            if !has_brace {
                let (_, lend) = line_bounds(src, code[sidx].start);
                let mut last = sidx;
                for j in sidx..code.len() { if code[j].start < lend { last = j; } else { break; } }
                e = code[last].end;
            }
            e
        } else {
            code[end_idx].end
        };
        let name = code[sidx].text(src).to_string();
        // alias if '=' appears before any '{' or newline type start
        let mut alias = false;
        let mut kind = String::new();
        for j in sidx..=end_idx.min(code.len().saturating_sub(1)) {
            let t = code[j].text(src);
            if t == "=" { alias = true; }
            if t == "struct" { kind = "struct".into(); }
            if t == "interface" { kind = "iface".into(); }
        }
        // Also check block tokens up to actual end for struct detection in single case
        if kind.is_empty() {
            for j in sidx..code.len() {
                if code[j].start >= end { break; }
                if code[j].text(src) == "struct" { kind = "struct".into(); }
                if code[j].text(src) == "interface" { kind = "iface".into(); }
            }
        }
        specs.push(GoTypeSpec { name, name_start: code[sidx].start, end, alias, kind });
    }
    specs
}

fn go_statements(base: &str, code: &[Token], src: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    match base {
        "defer" | "go" => {
            let kw = base;
            for i in 0..code.len() {
                if is_kw(&code[i], src, kw) {
                    // statement ends at block close if it contains a func literal/call block
                    // find first '{' ... if statement is `go func(){...}()` then end after () following close
                    // otherwise end of line.
                    let mut end: Option<usize> = None;
                    let mut j = i + 1;
                    let mut par = 0i32;
                    while j < code.len() {
                        let t = code[j].text(src);
                        match t {
                            "(" => par += 1,
                            ")" => par -= 1,
                            "{" if par == 0 => {
                                if let Some(close) = matching(code, j, "{", "}", src) {
                                    // include trailing () if present
                                    let mut e = code[close].end;
                                    if close + 2 < code.len() && code[close+1].text(src) == "(" && code[close+2].text(src) == ")" {
                                        e = code[close+2].end;
                                    }
                                    end = Some(e);
                                }
                                break;
                            }
                            _ => {}
                        }
                        // end of line check if no block
                        if code[j].text(src) == ";" { end = Some(code[j].end); break; }
                        j += 1;
                    }
                    if let Some(e) = end {
                        out.push((code[i].start, e));
                    } else {
                        let (_, lend) = line_bounds(src, code[i].start);
                        let mut last = i;
                        for j in i..code.len() { if code[j].start < lend { last = j; } else { break; } }
                        out.push((code[i].start, code[last].end));
                    }
                }
            }
        }
        "select" | "switch" => {
            let kw = base;
            for i in 0..code.len() {
                if is_kw(&code[i], src, kw) {
                    // ensure not `case` label usage; switch/select as statement: find '{' at depth 0
                    let mut j = i + 1;
                    let mut par = 0i32;
                    while j < code.len() {
                        let t = code[j].text(src);
                        match t { "(" => par += 1, ")" => par -= 1, "{" if par == 0 => {
                            if let Some(close) = matching(code, j, "{", "}", src) {
                                out.push((code[i].start, code[close].end));
                            }
                            break;
                        }, ";" if par == 0 => break, _ => {} }
                        j += 1;
                    }
                }
            }
        }
        "goto" => {
            for i in 0..code.len() {
                if is_kw(&code[i], src, "goto") && i + 1 < code.len() {
                    out.push((code[i].start, code[i+1].end));
                }
            }
        }
        "labeled" => {
            // label: identifier followed by ':' at statement start, then following statement
            for i in 0..code.len() {
                if code[i].kind == TK::Ident && i + 1 < code.len() && code[i+1].text(src) == ":" {
                    // label if previous token is '{' or '}' or ';' or start, or newline-start
                    let is_stmt_start = i == 0 || matches!(code[i-1].text(src), "{" | "}" | ";");
                    let line_startish = {
                        let ls = src[..code[i].start].rfind('\n').map_or(0, |p| p+1);
                        src[ls..code[i].start].trim().is_empty()
                    };
                    if is_stmt_start || line_startish {
                        // following statement: from label to its end (block or line)
                        let stmt_start = i + 2;
                        if stmt_start < code.len() {
                            // if next statement has a block, end at block close; else end of line of next statement
                            let mut end: Option<usize> = None;
                            let mut j = stmt_start;
                            let mut par = 0i32;
                            while j < code.len() {
                                let t = code[j].text(src);
                                match t { "(" => par += 1, ")" => par -= 1, "{" if par == 0 => {
                                    if let Some(close) = matching(code, j, "{", "}", src) { end = Some(code[close].end); }
                                    break;
                                }, _ => {} }
                                j += 1;
                            }
                            if let Some(e) = end {
                                out.push((code[i].start, e));
                            } else {
                                let (_, lend) = line_bounds(src, code[stmt_start.min(code.len()-1)].start);
                                let mut last = stmt_start;
                                for j in stmt_start..code.len() { if code[j].start < lend { last = j; } else { break; } }
                                out.push((code[i].start, code[last].end));
                            }
                        }
                    }
                }
            }
        }
        _ => {}
    }
    merge_ranges(out)
}
