        // In `Self { ... }`, Self handled.
        // Generic argument types e.g. Vec<String>: String prev == '<' or ',' within generics approximated.
        if want_type {
            if type_pos { out.push((t.start, t.end)); }
        } else {
            // identifiers exclude type positions and type names and fn names? fn names ARE identifiers
            if is_type_name { continue; }
            if type_pos && !fn_name_ranges.contains(&(t.start, t.end)) { continue; }
            out.push((t.start, t.end));
        }
    }
    if want_type {
        // Also field types etc where ident after ':' but capitalized already covered.
        // Add type names in impl headers: tokens after impl/for that are capitalized covered by prev impl?
    }
    out.sort();
    out.dedup();
    out
}

fn rust_closures(code: &[Token], src: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < code.len() {
        // closure starts with '|' (param list) possibly preceded by `move`
        // Find '|' tokens that begin a closure: a matching '|' exists, and before it is '=', '(', ',', 'return', etc or move
        if code[i].text(src) == "|" {
            // find closing '|'
            let mut j = i + 1;
            let mut found: Option<usize> = None;
            while j < code.len() {
                if code[j].text(src) == "|" { found = Some(j); break; }
                if matches!(code[j].text(src), ";" | "{" ) { break; }
                j += 1;
            }
            if let Some(close_params) = found {
                // body: if '{' block, else expression to , ; ) ] } at depth0 relative
                let body_start = close_params + 1;
                if body_start < code.len() {
                    if code[body_start].text(src) == "{" {
                        if let Some(close) = matching(code, body_start, "{", "}", src) {
                            out.push((code[i].start, code[close].end));
                            i = close + 1;
                            continue;
                        }
                    } else {
                        // expression end
                        let mut k = body_start;
                        let mut par = 0i32; let mut br = 0i32; let mut brk = 0i32;
                        let mut last = body_start;
                        while k < code.len() {
                            let t = code[k].text(src);
                            match t {
                                "(" => par += 1, ")" => { if par == 0 && br == 0 && brk == 0 { break; } par -= 1; },
                                "{" => br += 1, "}" => { if par == 0 && br == 0 && brk == 0 { break; } br -= 1; },
                                "[" => brk += 1, "]" => { if par == 0 && br == 0 && brk == 0 { break; } brk -= 1; },
                                "," | ";" if par == 0 && br == 0 && brk == 0 => break,
                                _ => {}
                            }
                            last = k;
                            k += 1;
                        }
                        out.push((code[i].start, code[last].end));
                        i = k.max(i+1);
                        continue;
                    }
                }
            }
        }
        i += 1;
    }
    out
}
