// ---------- Rust ----------

struct RustFnInfo {
    start: usize,
    end: usize,
    name: String,
    name_range: (usize, usize),
    vis: String, // "", "pub", "pub(crate)", ...
    is_const: bool,
    is_async: bool,
    is_unsafe: bool,
    is_extern: bool,
    in_impl: bool,
    has_test_attr: bool,
    open_brace: usize, // token index in code
}

fn rust_item_start_back(code: &[Token], src: &str, kw_idx: usize) -> usize {
    // scan backwards over modifier tokens / visibility / extern string
    let mut start = kw_idx;
    let mut j = kw_idx;
    while j > 0 {
        let prev = &code[j-1];
        let t = prev.text(src);
        // stop at statement boundaries
        if matches!(t, "{" | "}" | ";") { break; }
        if prev.kind == TK::Ident && matches!(t, "pub"|"const"|"async"|"unsafe"|"extern"|"default"|"final") {
            start = j - 1; j -= 1; continue;
        }
        if prev.kind == TK::Str && j >= 2 && code[j-2].text(src) == "extern" {
            // extern "C": include handled when we step on extern; just mark start at str? start should be extern token
            start = j - 1; j -= 1; continue;
        }
        if t == ")" {
            // visibility pub(...)
            // find matching '(' backwards
            let mut depth = 0i32;
            let mut k = j - 1;
            let mut found: Option<usize> = None;
            loop {
                let tt = code[k].text(src);
                if tt == ")" { depth += 1; }
                else if tt == "(" { depth -= 1; if depth == 0 { found = Some(k); break; } }
                if k == 0 { break; } k -= 1;
            }
            if let Some(open) = found {
                if open > 0 && code[open-1].text(src) == "pub" {
                    start = open - 1; j = open - 1; continue;
                }
            }
            break;
        }
        break;
    }
    code[start].start
}

fn rust_vis_of(code: &[Token], src: &str, kw_idx: usize) -> String {
    // find pub in the modifier run before kw
    let mut j = kw_idx;
    while j > 0 {
        let prev = &code[j-1];
        let t = prev.text(src);
        if matches!(t, "{" | "}" | ";") { break; }
        if t == ")" {
            // skip to matching (
            let mut depth = 0i32; let mut k = j - 1; let mut open: Option<usize> = None;
            loop {
                let tt = code[k].text(src);
                if tt == ")" { depth += 1; } else if tt == "(" { depth -= 1; if depth == 0 { open = Some(k); break; } }
                if k == 0 { break; } k -= 1;
            }
            if let Some(o) = open { j = o; continue; } else { break; }
        }
        if is_kw(prev, src, "pub") {
            // check if followed by '('
            if j < code.len() && code[j].text(src) == "(" {
                if let Some(close) = matching(code, j, "(", ")", src) {
                    let inner: String = code[j+1..close].iter().map(|t| t.text(src)).collect::<Vec<_>>().join("");
                    return format!("pub({})", inner);
                }
            }
            return "pub".to_string();
        }
        if prev.kind == TK::Ident || prev.kind == TK::Str { j -= 1; continue; }
        break;
    }
    String::new()
}

fn rust_has_modifier(code: &[Token], src: &str, kw_idx: usize, modifier: &str) -> bool {
    let mut j = kw_idx;
    while j > 0 {
        let prev = &code[j-1];
        let t = prev.text(src);
        if matches!(t, "{" | "}" | ";") { break; }
        if t == modifier { return true; }
        if t == ")" {
            let mut depth = 0i32; let mut k = j - 1;
            loop {
                let tt = code[k].text(src);
                if tt == ")" { depth += 1; } else if tt == "(" { depth -= 1; if depth == 0 { j = k; break; } }
                if k == 0 { return false; } k -= 1;
            }
            continue;
        }
        if prev.kind == TK::Ident || prev.kind == TK::Str { j -= 1; continue; }
        break;
    }
    false
}

fn rust_preceding_attributes(code: &[Token], src: &str, item_start_byte: usize) -> Vec<(usize, usize, String)> {
    // attribute tokens in `code` do not include '#'? '#' is Punct token, '[' follows.
    // Find attribute segments ending before item_start, walking backwards is complex;
    // instead scan all attributes and return those whose end <= item_start and which are
    // immediately preceding (only whitespace/comments/newlines between attr end and item start
    // or another attribute).
    let attrs = rust_attributes(code, src);
    let mut result = Vec::new();
    for (s, e, inner) in &attrs {
        if *e <= item_start_byte {
            let between = &src[*e..item_start_byte];
            if between.trim().is_empty() || between.trim().starts_with("#[") {
                // ensure no other items in between: crude - no ';' or '{' '}' 'fn' etc handled by trim check plus attribute chaining
                result.push((*s, *e, inner.clone()));
            }
        }
    }
    // keep only the contiguous trailing group: attrs sorted; take those where gap to next/item is only ws
    let mut filtered: Vec<(usize, usize, String)> = Vec::new();
    let mut expected_end = item_start_byte;
    for (s, e, inner) in result.iter().rev() {
        let between = &src[*e..expected_end];
        if between.trim().is_empty() {
            filtered.push((*s, *e, inner.clone()));
            expected_end = *s;
        } else {
            break;
        }
    }
    filtered.reverse();
    filtered
}

fn rust_attributes(code: &[Token], src: &str) -> Vec<(usize, usize, String)> {
    // returns (attr_full_start_including_#?, full_end, inner_range_text) - we return inner range as (start,end) via separate fn
    let mut out = Vec::new();
    let mut i = 0;
    while i + 1 < code.len() {
        if code[i].text(src) == "#" && code[i+1].text(src) == "[" {
            if let Some(close) = matching(code, i+1, "[", "]", src) {
                let inner = src[code[i+1].end..code[close].start].to_string();
                out.push((code[i].start, code[close].end, inner));
                i = close + 1;
                continue;
            }
        }
        i += 1;
    }
    out
}

fn rust_attribute_ranges(code: &[Token], src: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut i = 0;
    while i + 1 < code.len() {
        if code[i].text(src) == "#" && code[i+1].text(src) == "[" {
            if let Some(close) = matching(code, i+1, "[", "]", src) {
                out.push((code[i+1].end, code[close].start));
                i = close + 1;
                continue;
            }
        }
        i += 1;
    }
    out
}

fn rust_fns(code: &[Token], src: &str) -> Vec<RustFnInfo> {
    let stacks = brace_stacks(code, src);
    // classify impl blocks: open brace idx -> is_impl
    let mut impl_braces: Vec<usize> = Vec::new();
    for (i, t) in code.iter().enumerate() {
        if t.text(src) == "{" {
            // look backwards for `impl` before this brace at same header (no other '{')
            let mut j = i;
            while j > 0 {
                let pj = j - 1;
                let tt = code[pj].text(src);
                if matches!(tt, "{" | "}" | ";") { break; }
                if is_kw(&code[pj], src, "impl") { impl_braces.push(i); break; }
                j = pj;
            }
        }
    }
    let mut fns = Vec::new();
    for i in 0..code.len() {
        if !is_kw(&code[i], src, "fn") { continue; }
        if i + 1 >= code.len() || code[i+1].kind != TK::Ident { continue; }
        let name_tok = &code[i+1];
        // signature: find '{' or ';' at depth 0
        let mut j = i + 1;
        let mut par = 0i32; let mut brk = 0i32;
        let mut body_open: Option<usize> = None;
        let mut semi: Option<usize> = None;
        while j < code.len() {
            let t = code[j].text(src);
            match t {
                "(" | "[" => { if t=="(" {par+=1} else {brk+=1} },
                ")" | "]" => { if t=="(" {par-=1} else {brk-=1} },
                "{" if par == 0 && brk == 0 => { body_open = Some(j); break; }
                ";" if par == 0 && brk == 0 => { semi = Some(j); break; }
                _ => {}
            }
            j += 1;
        }
        let _ = semi;
        let Some(open) = body_open else { continue; };
        let Some(close) = matching(code, open, "{", "}", src) else { continue; };
        let start = rust_item_start_back(code, src, i);
        let in_impl = stacks.get(i).map_or(false, |st| st.iter().any(|b| impl_braces.contains(b)));
        let has_test_attr = rust_preceding_attributes(code, src, start).iter().any(|(_, _, inner)| inner.contains("test"));
        fns.push(RustFnInfo {
            start,
            end: code[close].end,
            name: name_tok.text(src).to_string(),
            name_range: (name_tok.start, name_tok.end),
            vis: rust_vis_of(code, src, i),
            is_const: rust_has_modifier(code, src, i, "const"),
            is_async: rust_has_modifier(code, src, i, "async"),
            is_unsafe: rust_has_modifier(code, src, i, "unsafe"),
            is_extern: rust_has_modifier(code, src, i, "extern"),
            in_impl,
            has_test_attr,
            open_brace: open,
        });
    }
    fns
}

// Generic rust item finder for struct/enum/trait/union/mod/type/impl
struct RustItem {
    kind: String, // struct/enum/trait/union/mod/impl/type
    start: usize,
    end: usize,
    name: String,
    vis: String,
    kw_idx: usize,
    body_open: Option<usize>,
    body_close: Option<usize>,
    has_unsafe: bool,
}

fn rust_items(code: &[Token], src: &str) -> Vec<RustItem> {
    let mut items = Vec::new();
    for i in 0..code.len() {
        let t = &code[i];
        if t.kind != TK::Ident { continue; }
        let word = t.text(src);
        if !matches!(word, "struct" | "enum" | "trait" | "union" | "mod" | "impl" | "type") { continue; }
        // 'type' inside fn etc is type alias statement: handled only at the item level (still type alias node).
        // Determine name: for impl, name is first type token after impl/generics; we store empty name
        let mut name = String::new();
        if word != "impl" {
            if i + 1 < code.len() && code[i+1].kind == TK::Ident {
                name = code[i+1].text(src).to_string();
            } else {
                continue;
            }
        }
        // find body '{' or ';' at depth0
        let mut j = i + 1;
        let mut par = 0i32; let mut brk = 0i32; let mut ang = 0i32;
        let mut body_open: Option<usize> = None;
        let mut semi: Option<usize> = None;
        while j < code.len() {
            let tt = code[j].text(src);
            match tt {
                "(" => par += 1, ")" => par -= 1,
                "[" => brk += 1, "]" => brk -= 1,
                "{" if par == 0 && brk == 0 && ang == 0 => { body_open = Some(j); break; }
                ";" if par == 0 && brk == 0 => { semi = Some(j); break; }
                _ => {}
            }
            j += 1;
        }
        let start = rust_item_start_back(code, src, i);
        let (end, body_close) = if let Some(open) = body_open {
            if let Some(close) = matching(code, open, "{", "}", src) {
                let mut e = code[close].end;
                // struct-like declarations may have trailing ';' (tuple/unit already semi path; braced in C-like syntax no)
                if word == "struct" || word == "union" {
                    // In Rust, braced struct has no semicolon, but if present? keep not including.
                }
                // type alias with block? not.
                let _ = &mut e;
                (e, Some(close))
            } else { continue; }
        } else if let Some(s) = semi {
            (code[s].end, None)
        } else {
            // no body or semi: for trait/struct declarations could end at line end (unlikely)
            continue;
        };
        items.push(RustItem {
            kind: word.to_string(),
            start,
            end,
            name,
            vis: rust_vis_of(code, src, i),
            kw_idx: i,
            body_open,
            body_close,
            has_unsafe: rust_has_modifier(code, src, i, "unsafe"),
        });
    }
    items
}

fn rust_prepared(base: &str, pat: Option<&str>, src: &str) -> Vec<(usize, usize)> {
    let all = lex(LangKind::Rust, src);
    let code: Vec<Token> = all.iter().filter(|t| t.kind != TK::Comment).cloned().collect();
    match base {
        "comments" => {
            return all.iter().filter(|t| t.kind == TK::Comment && !t.text(src).starts_with("///")).map(|t| (t.start, t.end)).collect();
        }
        "doc-comments" => {
            return all.iter().filter(|t| t.kind == TK::Comment && (t.text(src).starts_with("///") || t.text(src).starts_with("//!"))).map(|t| (t.start, t.end)).collect();
        }
        "strings" => {
            let mut ranges = Vec::new();
            for t in &all {
                if t.kind == TK::Str {
                    ranges.extend(t.str_segments.iter().copied());
                }
            }
            return ranges;
        }
        "uses" => {
            let mut out = Vec::new();
            for i in 0..code.len() {
                if is_kw(&code[i], src, "use") {
                    // scope from token after use to before ';'
                    let mut j = i + 1;
                    let mut last = j;
                    while j < code.len() && code[j].text(src) != ";" {
                        last = j; j += 1;
                    }
                    if j < code.len() && j > i + 1 {
                        out.push((code[i+1].start, code[last].end));
                    }
                }
            }
            return out;
        }
        "attribute" => {
            return rust_attribute_ranges(&code, src);
        }
        _ => {}
    }
    let items = rust_items(&code, src);
    let fns = rust_fns(&code, src);
    let mut out = Vec::new();
    match base {
        "struct" | "priv-struct" | "pub-struct" | "pub-crate-struct" | "pub-self-struct" | "pub-super-struct" => {
            for it in items.iter().filter(|it| it.kind == "struct") {
                let name_ok = pat.map_or(true, |p| name_matches(p, &it.name));
                if !name_ok { continue; }
                let vis_ok = match base {
                    "struct" => true,
                    "priv-struct" => it.vis.is_empty(),
                    "pub-struct" => it.vis == "pub",
                    "pub-crate-struct" => it.vis == "pub(crate)",
                    "pub-self-struct" => it.vis == "pub(self)",
                    "pub-super-struct" => it.vis == "pub(super)",
                    _ => false,
                };
                if vis_ok { out.push((it.start, it.end)); }
            }
        }
        "enum" | "priv-enum" | "pub-enum" | "pub-crate-enum" | "pub-self-enum" | "pub-super-enum" => {
            for it in items.iter().filter(|it| it.kind == "enum") {
                let name_ok = pat.map_or(true, |p| name_matches(p, &it.name));
                if !name_ok { continue; }
                let vis_ok = match base {
                    "enum" => true,
                    "priv-enum" => it.vis.is_empty(),
                    "pub-enum" => it.vis == "pub",
                    "pub-crate-enum" => it.vis == "pub(crate)",
                    "pub-self-enum" => it.vis == "pub(self)",
                    "pub-super-enum" => it.vis == "pub(super)",
                    _ => false,
                };
                if vis_ok { out.push((it.start, it.end)); }
            }
        }
        "enum-variant" => {
            for it in items.iter().filter(|it| it.kind == "enum") {
                if let (Some(open), Some(close)) = (it.body_open, it.body_close) {
                    // variants are top-level entries in enum block split by commas at depth0
                    let mut entry_start: Option<usize> = None;
                    let mut par = 0i32; let mut br = 0i32; let mut brk = 0i32;
                    let mut j = open + 1;
                    while j < close {
                        let t = code[j].text(src);
                        if entry_start.is_none() && !(t == "," ) {
                            // skip attributes tokens for variant? variant starts at ident
                            if code[j].kind == TK::Ident {
                                entry_start = Some(j);
                            }
                        }
                        match t { "(" => par+=1, ")" => par-=1, "{" => br+=1, "}" => br-=1, "[" => brk+=1, "]" => brk-=1, _ => {} }
                        if t == "," && par==0 && br==0 && brk==0 {
                            if let Some(s) = entry_start {
                                out.push((code[s].start, code[j-1].end));
                                entry_start = None;
                            }
                        }
                        j += 1;
                    }
                    if let Some(s) = entry_start {
                        if close > open + 1 {
                            out.push((code[s].start, code[close-1].end));
                        }
                    }
                }
            }
        }
        "trait" => {
            for it in items.iter().filter(|it| it.kind == "trait") {
                if pat.map_or(true, |p| name_matches(p, &it.name)) { out.push((it.start, it.end)); }
            }
        }
        "mod" => {
            for it in items.iter().filter(|it| it.kind == "mod") {
                if pat.map_or(true, |p| name_matches(p, &it.name)) { out.push((it.start, it.end)); }
            }
        }
        "mod-tests" => {
            for it in items.iter().filter(|it| it.kind == "mod" && it.name == "tests") {
                out.push((it.start, it.end));
            }
        }
        "type-def" => {
            for it in items.iter().filter(|it| matches!(it.kind.as_str(), "struct" | "enum" | "union")) {
                out.push((it.start, it.end));
            }
        }
        "impl" | "impl-type" | "impl-trait" => {
            for it in items.iter().filter(|it| it.kind == "impl") {
                // header tokens between impl kw and body open
                let open = it.body_open.unwrap_or(it.kw_idx);
                let header: Vec<&str> = code[it.kw_idx+1..open].iter().map(|t| t.text(src)).collect();
                let has_for = header.iter().any(|t| *t == "for");
                let ok = match base { "impl" => true, "impl-type" => !has_for, "impl-trait" => has_for, _ => false };
                if ok { out.push((it.start, it.end)); }
            }
        }
        "fn" | "impl-fn" | "priv-fn" | "pub-fn" | "pub-crate-fn" | "pub-self-fn" | "pub-super-fn" | "const-fn" | "async-fn" | "unsafe-fn" | "extern-fn" | "test-fn" => {
            for f in &fns {
                let ok = match base {
                    "fn" => pat.map_or(true, |p| name_matches(p, &f.name)),
                    "impl-fn" => f.in_impl,
                    "priv-fn" => f.vis.is_empty(),
                    "pub-fn" => f.vis == "pub",
                    "pub-crate-fn" => f.vis == "pub(crate)",
                    "pub-self-fn" => f.vis == "pub(self)",
                    "pub-super-fn" => f.vis == "pub(super)",
