// ---------- C ----------

fn c_prepared(base: &str, src: &str) -> Vec<(usize, usize)> {
    let all = lex(LangKind::C, src);
    let code: Vec<Token> = all.iter().filter(|t| t.kind != TK::Comment).cloned().collect();
    match base {
        "comments" => return comments_ranges(LangKind::C, src),
        "strings" => {
            return all.iter().filter(|t| t.kind == TK::Str).map(|t| (t.start, t.end)).collect();
        }
        "includes" => {
            let mut out = Vec::new();
            for (i, t) in all.iter().enumerate() {
                if t.kind == TK::Punct && t.text(src) == "#" {
                    // next ident include?
                    // tokens in `all` include preprocessor tokens as lexed: '#' punct, 'include' ident, string etc on same line
                    if i + 1 < all.len() && is_kw(&all[i+1], src, "include") {
                        let (ls, le) = line_bounds(src, t.start);
                        let _ = ls;
                        // trim trailing whitespace
                        let mut e = le;
                        while e > t.start && src[..e].chars().last().map_or(false, |c| c == ' ' || c == '\t') { e -= 1; }
                        out.push((t.start, e));
                    }
                }
            }
            return out;
        }
        _ => {}
    }
    match base {
        "type-def" => {
            let mut out = Vec::new();
            // statements starting with typedef ending ;
            for seg in c_segments(&code, src) {
                if !seg.is_empty() && is_kw(&code[seg[0]], src, "typedef") {
                    let last = seg[seg.len()-1];
                    // seg includes ';'? our segments split logic below decides; push to semi token if present next
                    out.push((code[seg[0]].start, code[last].end));
                }
            }
            // The above segment function returns segments ending at ';' inclusive
            return out;
        }
        "enum" | "struct" | "union" => {
            let kw = base;
            let mut out = Vec::new();
            for i in 0..code.len() {
                if is_kw(&code[i], src, kw) {
                    // optional name
                    let mut j = i + 1;
                    let mut end = code[i].end;
                    if j < code.len() && code[j].kind == TK::Ident { end = code[j].end; j += 1; }
                    if j < code.len() && code[j].text(src) == "{" {
                        if let Some(close) = matching(&code, j, "{", "}", src) {
                            end = code[close].end;
                        }
                    }
                    out.push((code[i].start, end));
                }
            }
            return merge_ranges(out);
        }
        "variable" | "declaration" => {
            return c_declarations(&code, src);
        }
        "function" | "function-def" | "function-decl" | "call-expression" => {
            let mut out = Vec::new();
            let decls = c_function_declarators(&code, src); // (range, is_def, def_range)
            let calls = c_calls(&code, src);
            match base {
                "function-def" => {
                    for d in &decls { if d.is_def { out.push(d.def_range); } }
                }
                "function-decl" => {
                    for d in &decls { out.push(d.range); }
                }
                "function" => {
                    for d in &decls { out.push(d.range); }
                    out.extend(calls.iter().copied());
                }
                "call-expression" => out.extend(calls.iter().copied()),
                _ => {}
            }
            return merge_ranges(out);
        }
        "if" | "for" | "while" | "switch" | "do" => {
            return c_control(base, &code, src);
        }
        "identifier" => {
            return c_identifiers(&code, src);
        }
        _ => {}
    }
    vec![]
}

// Segments of tokens split by ';' at brace depth 0 and by blocks.
// Returns token index ranges (each Vec is list of token indices?) Simpler: return Vec of Vec<usize>
fn c_segments(code: &[Token], src: &str) -> Vec<Vec<usize>> {
    // We segment statements: sequence ending with ';' (including it) at any brace depth,
    // but respecting paren depth (for loops handled separately). Also function definitions are segments ending at '}' matching a function brace.
    let mut segs = Vec::new();
    let mut cur: Vec<usize> = Vec::new();
    let mut par = 0i32;
    let mut i = 0;
    while i < code.len() {
        let t = code[i].text(src);
        cur.push(i);
        match t {
            "(" => par += 1,
            ")" => par -= 1,
            ";" if par == 0 => { segs.push(std::mem::take(&mut cur)); }
            _ => {}
        }
        i += 1;
    }
    if !cur.is_empty() { segs.push(cur); }
    segs
}

fn c_declarations(code: &[Token], src: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    // Top and block-level declarations: we scan for ';' terminated segments at paren depth 0
    // plus for-loop initialisers.
    // For-loop initialisers
    for i in 0..code.len() {
        if is_kw(&code[i], src, "for") && i + 1 < code.len() && code[i+1].text(src) == "(" {
            // decl from i+2 to first ';' inside
            let mut j = i + 2;
            let start_tok = j;
            while j < code.len() && code[j].text(src) != ";" && code[j].text(src) != ")" { j += 1; }
            if j < code.len() && code[j].text(src) == ";" && j > start_tok {
                if c_is_declaration(code, src, start_tok, j) {
                    out.push((code[start_tok].start, code[j-1].end));
                }
            }
        }
    }
    // Statements segmentation: boundaries are ';' at paren0/brace? , '{', '}'
    let mut stmt_start = 0usize;
    let mut par = 0i32;
    let mut brace_depth_at_start = 0i32;
    let mut depth = 0i32;
    let mut i = 0;
    let mut starts: Vec<(usize, i32)> = vec![(0, 0)];
    // Simpler: iterate and cut
    let mut boundaries: Vec<usize> = vec![0];
    let mut d = 0i32; let mut p = 0i32;
    for (idx, t) in code.iter().enumerate() {
        let txt = t.text(src);
        match txt {
            "(" => p += 1, ")" => p -= 1,
            "{" => { d += 1; boundaries.push(idx + 1); },
            "}" => { d -= 1; boundaries.push(idx + 1); },
            ";" if p == 0 => { boundaries.push(idx + 1); },
            _ => {}
        }
        let _ = brace_depth_at_start; let _ = depth; let _ = par; let _ = stmt_start; let _ = &mut starts;
    }
    boundaries.sort(); boundaries.dedup();
    for w in boundaries.windows(2) {
        let (s, e_exclusive_semi) = (w[0], w[1]);
        if s >= e_exclusive_semi { continue; }
        // segment tokens s..e_exclusive_semi, where last may be ';' (if segment ends because of ;)
        let mut end_tok = e_exclusive_semi - 1;
        let has_semi = code[end_tok].text(src) == ";";
        if has_semi {
            if end_tok == s { continue; }
            // declaration check over s..end_tok (exclude semi)
            if c_is_declaration(code, src, s, end_tok) {
                out.push((code[s].start, code[end_tok].end));
            }
        } else {
            // segment terminated by brace boundary: could be a function definition header etc - not declaration
            let _ = end_tok;
        }
    }
    // dedup/sort
    merge_ranges(out)
}

fn c_is_declaration(code: &[Token], src: &str, s: usize, e: usize) -> bool {
    // tokens [s,e) exclude ';'
    if s >= e { return false; }
    let first = code[s].text(src);
    if matches!(first, "typedef" | "return" | "case" | "goto" | "break" | "continue" | "if" | "else" | "while" | "for" | "switch" | "do") { return false; }
    // struct/enum/union forward or definition without declarator variable
    if matches!(first, "struct" | "enum" | "union") {
        // if there's a declarator after closing brace or before '=' etc
        // find closing brace if any
        let mut has_brace = false;
        let mut after_brace_has_ident = false;
        let mut j = s;
        while j < e {
            if code[j].text(src) == "{" { has_brace = true; }
            if code[j].text(src) == "}" && j + 1 < e && code[j+1].kind == TK::Ident { after_brace_has_ident = true; }
            j += 1;
        }
        if has_brace {
            return after_brace_has_ident;
        } else {
            // struct S; -> false; struct S x; -> declarator after name
            // tokens: struct Name ; (e = 2 tokens) vs struct Name var
            return e - s >= 3;
        }
    }
    // Must contain a declarator identifier: an identifier that is not a type keyword and
    // is followed by '=', ';'-end, '[', '(', ',', or end
    // Heuristic: second token (or after qualifiers) is identifier/pointer to identifier
    // Skip storage/qualifier/type tokens
    let skip_words = ["const","volatile","static","extern","register","auto","signed","unsigned","long","short","int","char","float","double","void","_Bool","_Complex","inline","restrict","struct","enum","union"];
    let mut j = s;
    while j < e && code[j].kind == TK::Ident && skip_words.contains(&code[j].text(src)) { j += 1; }
    // pointer stars
    while j < e && code[j].text(src) == "*" { j += 1; }
    // function pointer '('
    if j < e && code[j].text(src) == "(" {
        // function pointer declaration is a declaration
        return true;
    }
    if j >= e { return false; }
    // j should be an identifier (declarator name) or a type name followed by identifier
    if code[j].kind != TK::Ident { return false; }
    // If j is at s and the next token is an operator like '=' with no type (assignment statement `x = 5`) then not declaration.
    // Declaration requires at least two "name/type" tokens before assignment OR pointer etc, or j>s (we skipped types)
    if j == s {
        // need another ident/star before declarator: e.g. `int x`, `MyType x`, `unsigned x`
        // Here j==s means first token wasn't skipped. If next token is ident or '*', it's a type name.
        if j + 1 < e && (code[j+1].kind == TK::Ident || code[j+1].text(src) == "*") {
            return true;
        }
        return false;
    }
    true
}

struct CFuncDecl { range: (usize, usize), is_def: bool, def_range: (usize, usize) }

fn c_function_declarators(code: &[Token], src: &str) -> Vec<FuncDeclWrap> {
    type FuncDeclWrap = CFuncDecl;
    let mut out = Vec::new();
    for i in 0..code.len() {
        if code[i].kind != TK::Ident { continue; }
        // identifier followed by '('
        if i + 1 >= code.len() || code[i+1].text(src) != "(" { continue; }
        // exclude keywords / calls context? declarators are in declaration segments:
        // previous token suggests declaration: type ident, '*', storage, or start of statement
        let prev_ok = i == 0 || {
            let p = &code[i-1];
            p.kind == TK::Ident || matches!(p.text(src), "*" | ";" | "{" | "}" | ",")
        };
        if !prev_ok { continue; }
        // exclude if this is a call (preceded by '=' or '(' or operator etc is handled above)
        // Determine if following close paren is followed by '{' (def), ';', ',', or declarator continuation in a declaration statement
        if let Some(close) = matching(code, i+1, "(", ")", src) {
            let after = if close + 1 < code.len() { code[close+1].text(src) } else { "" };
            let is_def = after == "{";
            let is_decl_stmt = is_def || matches!(after, ";" | ",");
            // Also function pointer case handled separately below
            if is_decl_stmt {
                // ensure the statement context is a declaration (p prev is not e.g. return / = )
                // Find statement start
                let mut s = i;
                while s > 0 && !matches!(code[s-1].text(src), ";" | "{" | "}") { s -= 1; }
                if c_is_declaration_or_type_header(code, src, s, i) {
                    let def_range = if is_def {
                        if let Some(bclose) = matching(code, close+1, "{", "}", src) {
                            (code[s].start, code[bclose].end)
                        } else { (code[s].start, code[close].end) }
                    } else { (code[i].start, code[close].end) };
                    out.push(CFuncDecl{range: (code[i].start, code[close].end), is_def, def_range});
                }
            }
        }
    }
    // function pointer declarators: (*name)(...)
    for i in 0..code.len() {
        if code[i].text(src) == "(" && i + 2 < code.len() && code[i+1].text(src) == "*" && code[i+2].kind == TK::Ident {
            if let Some(close1) = matching(code, i, "(", ")", src) {
                if close1 + 1 < code.len() && code[close1+1].text(src) == "(" {
                    if let Some(close2) = matching(code, close1+1, "(", ")", src) {
                        out.push(CFuncDecl{range: (code[i].start, code[close2].end), is_def: false, def_range: (code[i].start, code[close2].end)});
                    }
                }
            }
        }
    }
    out
}

fn c_is_declaration_or_type_header(code: &[Token], src: &str, s: usize, upto_name: usize) -> bool {
    // header from statement start to function name (exclusive) should contain a type token/ident
    // e.g. `int`, `static int`, `MyType`, `void`
    if upto_name <= s { return false; }
    // if header has only the name itself? not possible upto_name>s
    // require at least one token before name that is ident or '*'
    code[s..upto_name].iter().any(|t| t.kind == TK::Ident || t.text(src) == "*")
}

fn c_calls(code: &[Token], src: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let decl_ranges: Vec<(usize, usize)> = c_function_declarators_inner(code, src);
    for i in 0..code.len() {
        if code[i].kind != TK::Ident { continue; }
        let word = code[i].text(src);
        if matches!(word, "if"|"while"|"for"|"switch"|"sizeof"|"return") { continue; }
        if i + 1 < code.len() && code[i+1].text(src) == "(" {
            // not a declarator (skip if inside decl_ranges with same start)
            if decl_ranges.iter().any(|r| r.0 == code[i].start) { continue; }
            // exclude function definitions header? already decl
            if let Some(close) = matching(code, i+1, "(", ")", src) {
                out.push((code[i].start, code[close].end));
            }
        }
    }
    out
}

fn c_function_declarators_inner(code: &[Token], src: &str) -> Vec<(usize, usize)> {
    // helper to avoid recursion between c_calls and c_function_declarators
    let mut out = Vec::new();
    for i in 0..code.len() {
        if code[i].kind != TK::Ident { continue; }
        if i + 1 >= code.len() || code[i+1].text(src) != "(" { continue; }
        if let Some(close) = matching(code, i+1, "(", ")", src) {
            let after = if close + 1 < code.len() { code[close+1].text(src) } else { "" };
            if after == "{" || after == ";" {
                let mut s = i;
                while s > 0 && !matches!(code[s-1].text(src), ";" | "{" | "}") { s -= 1; }
                if s < i && c_is_declaration_or_type_header(code, src, s, i) {
                    out.push((code[i].start, code[close].end));
                }
            }
        }
    }
    out
}

fn c_control(base: &str, code: &[Token], src: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    for i in 0..code.len() {
        if !is_kw(&code[i], src, base) { continue; }
        if base == "do" {
            // substatement then while (...);
            let stmt = c_substatement(code, src, i + 1);
            if let Some((_, end_tok)) = stmt {
                // expect while
                let mut j = end_tok + 1;
                if j < code.len() && is_kw(&code[j], src, "while") {
                    if j + 1 < code.len() && code[j+1].text(src) == "(" {
                        if let Some(close) = matching(code, j+1, "(", ")", src) {
                            out.push((code[i].start, code[close].end));
                            continue;
                        }
                    }
                }
                out.push((code[i].start, code[end_tok].end));
            }
            continue;
        }
        // if/for/while/switch: '(' ... ')' then substatement
        if i + 1 >= code.len() || code[i+1].text(src) != "(" { continue; }
        let Some(cond_close) = matching(code, i+1, "(", ")", src) else { continue; };
        if let Some((_, end_tok)) = c_substatement(code, src, cond_close + 1) {
            out.push((code[i].start, code[end_tok].end));
        }
    }
    merge_ranges(out)
}

// returns (start_tok, end_tok inclusive)
fn c_substatement(code: &[Token], src: &str, start: usize) -> Option<(usize, usize)> {
    if start >= code.len() { return None; }
    if code[start].text(src) == "{" {
        let close = matching(code, start, "{", "}", src)?;
        return Some((start, close));
    }
    // nested control statement?
    if code[start].kind == TK::Ident && matches!(code[start].text(src), "if"|"for"|"while"|"switch"|"do") {
        // delegate to find its end by c_control scanning: find semi/block at depth0
    }
    // single statement to ';'
    let mut par = 0i32;
    let mut j = start;
    while j < code.len() {
        let t = code[j].text(src);
        match t {
            "(" => par += 1, ")" => par -= 1,
            "{" if par == 0 => {
                if let Some(close) = matching(code, j, "{", "}", src) {
                    return Some((start, close));
                }
            }
            ";" if par == 0 => return Some((start, j - 1)),
            _ => {}
        }
        j += 1;
    }
    Some((start, code.len() - 1))
}

fn c_identifiers(code: &[Token], src: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    // struct/enum/union name ranges
    let mut type_names: Vec<(usize, usize)> = Vec::new();
    for i in 0..code.len() {
        if matches!(code[i].text(src), "struct"|"enum"|"union") && code[i].kind == TK::Ident {
            if i + 1 < code.len() && code[i+1].kind == TK::Ident {
                type_names.push((code[i+1].start, code[i+1].end));
            }
        }
    }
    // struct block token ranges for field detection
    let stacks = brace_stacks(code, src);
    let mut struct_braces: Vec<usize> = Vec::new();
    for i in 0..code.len() {
        if code[i].text(src) == "{" {
            // preceded by struct/enum/union ... { within few tokens
            let mut j = i;
            while j > 0 && j > i.saturating_sub(4) {
                j -= 1;
                if matches!(code[j].text(src), "struct"|"enum"|"union") { struct_braces.push(i); break; }
            }
        }
    }
    for (idx, t) in code.iter().enumerate() {
        if t.kind != TK::Ident { continue; }
        let word = t.text(src);
        if matches!(word, "int"|"char"|"float"|"double"|"void"|"long"|"short"|"unsigned"|"signed"|"const"|"static"|"extern"|"typedef"|"struct"|"enum"|"union"|"if"|"else"|"for"|"while"|"do"|"switch"|"case"|"default"|"return"|"break"|"continue"|"goto"|"sizeof"|"volatile"|"register"|"auto"|"inline"|"restrict") { continue; }
        if type_names.contains(&(t.start, t.end)) { continue; }
        // field member after . or ->
        if idx > 0 && matches!(code[idx-1].text(src), "." | "->") { continue; }
        // field declaration inside struct: token is declarator name in a field declaration
        let in_struct = stacks.get(idx).map_or(false, |st| st.iter().any(|b| struct_braces.contains(b)));
        if in_struct {
            // field names are identifiers followed by ';' ',' '[' ':' etc and preceded by a type ident
            let next = if idx + 1 < code.len() { code[idx+1].text(src) } else { "" };
            if idx > 0 && code[idx-1].kind == TK::Ident && matches!(next, ";" | "," | "[" | ":") {
                continue;
            }
        }
        // typedef name: last ident before ';' in typedef statement
        // find statement start
        let mut s = idx;
        while s > 0 && !matches!(code[s-1].text(src), ";" | "{" | "}") { s -= 1; }
        if s < code.len() && is_kw(&code[s], src, "typedef") {
            // if this ident is the final declarator (next is ';' or ',')
            let next = if idx + 1 < code.len() { code[idx+1].text(src) } else { "" };
            if matches!(next, ";" | ",") { continue; }
        }
        out.push((t.start, t.end));
    }
    out
}

// ---------- C# ----------

fn csharp_prepared(base: &str, src: &str) -> Vec<(usize, usize)> {
    let all = lex(LangKind::CSharp, src);
    let code: Vec<Token> = all.iter().filter(|t| t.kind != TK::Comment).cloned().collect();
    match base {
        "comments" => return comments_ranges(LangKind::CSharp, src),
        "strings" => {
            let mut ranges = Vec::new();
            for t in &all { if t.kind == TK::Str { ranges.extend(t.str_segments.iter().copied()); } }
            return ranges;
        }
        "usings" => {
            let mut out = Vec::new();
            for i in 0..code.len() {
                if is_kw(&code[i], src, "using") {
                    // using directive if followed by ident chain and ';' and no '(' or '=' before ';'? Alias contains '='
                    let mut j = i + 1;
                    // skip possible 'static'
                    if j < code.len() && is_kw(&code[j], src, "static") { j += 1; }
                    if j < code.len() && code[j].kind == TK::Ident {
                        // alias check: ident followed by '='
                        if j + 1 < code.len() && code[j+1].text(src) == "=" {
                            // alias name is left ident: original captures? capture that ident
                            out.push((code[j].start, code[j].end));
                            continue;
                        }
                        let mut last = j;
                        let mut k = j;
                        while k < code.len() && (code[k].kind == TK::Ident || code[k].text(src) == ".") {
                            if code[k].kind == TK::Ident { last = k; }
                            k += 1;
                        }
                        if k < code.len() && code[k].text(src) == ";" {
                            out.push((code[j].start, code[last].end));
                        }
                    }
                }
            }
            return out;
        }
        "attribute" => {
            // '[' ... ']' at member/type context: inner range
            // Use rust_attribute-like helper for '[' after start or following tokens
            let mut out = Vec::new();
            for i in 0..code.len() {
                if code[i].text(src) == "[" {
                    // attribute lists are at statement/member starts; '[' also used for arrays/indexers.
                    // Heuristic: previous token is start, '{', '}', ';', or a modifier, or newline-start and contents are ident(...)
                    let prev_ok = i == 0 || matches!(code[i-1].text(src), "{" | "}" | ";");
                    let line_startish = {
                        let ls = src[..code[i].start].rfind('\n').map_or(0, |p| p+1);
                        src[ls..code[i].start].trim().is_empty() || prev_ok
                    };
                    if line_startish {
                        if let Some(close) = matching(code, i, "[", "]", src) {
                            // ensure content starts with ident
                            if i + 1 < close && code[i+1].kind == TK::Ident {
                                out.push((code[i].end, code[close].start));
                            }
                        }
                    }
                }
            }
            return out;
        }
        _ => {}
    }
    // type blocks and members
    let type_items = cs_types(&code, src);
    let mut out = Vec::new();
    match base {
        "class" | "struct" | "interface" | "enum" => {
            for it in &type_items {
                if it.kind == base { out.push((it.start, it.end)); }
            }
            return merge_ranges(out);
        }
        "method" | "constructor" | "destructor" | "property" | "field" | "variable-declaration" => {
            let members = cs_members(&code, src, &type_items);
            for m in &members {
                match base {
                    "method" => if m.kind == "method" { out.push((m.start, m.end)); },
                    "constructor" => if m.kind == "constructor" { out.push((m.start, m.end)); },
                    "destructor" => if m.kind == "destructor" { out.push((m.start, m.end)); },
                    "property" => if m.kind == "property" { out.push((m.start, m.end)); },
                    "field" => if m.kind == "field" { out.push((m.start, m.end)); },
                    "variable-declaration" => {
                        if let Some(v) = m.var_decl { out.push(v); }
                    }
                    _ => {}
                }
            }
            // local variable declarations inside method bodies
            if base == "variable-declaration" {
                for v in cs_local_var_decls(&code, src) {
                    out.push(v);
                }
            }
            return merge_ranges(out);
        }
        "identifier" => {
            return cs_identifiers(&code, src);
        }
        _ => {}
    }
    out
}

struct CsType { kind: String, name: String, start: usize, end: usize, body_open: Option<usize>, body_close: Option<usize>, kw_idx: usize }

fn cs_types(code: &[Token], src: &str) -> Vec<CsType> {
    let mut out = Vec::new();
    for i in 0..code.len() {
        if code[i].kind != TK::Ident { continue; }
        let w = code[i].text(src);
        if !matches!(w, "class"|"struct"|"interface"|"enum") { continue; }
        if i + 1 >= code.len() || code[i+1].kind != TK::Ident { continue; }
        let name = code[i+1].text(src).to_string();
        // find '{' or ';'
        let mut j = i + 1;
        let mut par = 0i32; let mut brk = 0i32;
        let mut body_open: Option<usize> = None; let mut semi: Option<usize> = None;
        while j < code.len() {
            let t = code[j].text(src);
            match t { "(" => par+=1, ")" => par-=1, "[" => brk+=1, "]" => brk-=1,
                "{" if par==0 && brk==0 => { body_open = Some(j); break; }
                ";" if par==0 && brk==0 => { semi = Some(j); break; }
                _ => {} }
            j += 1;
        }
        // start: scan back over modifiers and attribute lists
        let mut start_idx = i;
        let mut k = i;
        while k > 0 {
            let p = &code[k-1];
            let t = p.text(src);
            if matches!(t, "{"|"}"|";") { break; }
            if p.kind == TK::Ident && matches!(t, "public"|"private"|"protected"|"internal"|"static"|"abstract"|"sealed"|"partial"|"readonly"|"ref"|"unsafe"|"new") {
                start_idx = k - 1; k -= 1; continue;
            }
            if t == "]" {
                // attribute: find '[' backwards
                let mut depth = 0i32; let mut m = k - 1; let mut open: Option<usize> = None;
                loop {
                    let tt = code[m].text(src);
                    if tt == "]" { depth += 1; } else if tt == "[" { depth -= 1; if depth == 0 { open = Some(m); break; } }
                    if m == 0 { break; } m -= 1;
                }
                if let Some(o) = open { start_idx = o; k = o; continue; }
                break;
            }
            break;
        }
        let (end, body_close) = if let Some(open) = body_open {
            if let Some(close) = matching(code, open, "{", "}", src) { (code[close].end, Some(close)) } else { continue; }
        } else if let Some(s) = semi { (code[s].end, None) } else { continue; };
        out.push(CsType{kind: w.to_string(), name, start: code[start_idx].start, end, body_open, body_close, kw_idx: i});
    }
    out
}

struct CsMember { kind: String, start: usize, end: usize, var_decl: Option<(usize, usize)> }

fn cs_members(code: &[Token], src: &str, types: &[CsType]) -> Vec<CsMember> {
    let mut members = Vec::new();
    for ty in types {
        let (Some(open), Some(close)) = (ty.body_open, ty.body_close) else { continue; };
        if ty.kind == "enum" { continue; }
        // split direct children into member segments by blocks / semicolons at depth0 relative
        let mut i = open + 1;
        while i < close {
            // skip stray semicolons
            if code[i].text(src) == ";" { i += 1; continue; }
            let seg_start = i;
            // find member end: '{' block or ';' or '=>' at depth0
            let mut j = i;
            let mut par = 0i32; let mut brk = 0i32;
            let mut member_end: Option<usize> = None;
            let mut end_is_block = false;
            let mut arrow = false;
            while j < close {
                let t = code[j].text(src);
                match t {
                    "(" => par += 1, ")" => par -= 1, "[" => brk += 1, "]" => brk -= 1,
                    "{" if par == 0 && brk == 0 => {
                        if let Some(bclose) = matching(code, j, "{", "}", src) {
                            member_end = Some(bclose);
                            end_is_block = true;
                        }
                        break;
                    }
                    "=>" if par == 0 && brk == 0 => { arrow = true; break; }
                    ";" if par == 0 && brk == 0 => { member_end = Some(j); break; }
                    _ => {}
                }
                j += 1;
            }
            if arrow {
                // expression-bodied member: end at ';'
                let mut k = j;
                while k < close && code[k].text(src) != ";" { k += 1; }
                member_end = Some(k.min(close-1));
                end_is_block = false;
                j = k;
            }
            let Some(end_tok) = member_end else { break; };
            // analyse segment code[seg_start..=end_tok] (header up to '{' if block)
            let header_end = if end_is_block {
                // find the '{' that started block
                let mut h = seg_start;
                while h < end_tok && code[h].text(src) != "{" { h += 1; }
                h
            } else if arrow {
                j // not used
            } else { end_tok };
            let _ = header_end;
            // Find '(' in header segment (before block/semi)
            let limit = if end_is_block {
                let mut h = seg_start; while h < end_tok && code[h].text(src) != "{" { h += 1; } h
            } else { end_tok };
            let mut paren_idx: Option<usize> = None;
            for k in seg_start..limit {
                if code[k].text(src) == "(" { paren_idx = Some(k); break; }
            }
            // attribute skipping: member analysis start after attribute lists
            let mut an_start = seg_start;
            while an_start + 1 < limit && code[an_start].text(src) == "[" {
                if let Some(c) = matching(code, an_start, "[", "]", src) { an_start = c + 1; } else { break; }
            }
            // start for ranges: original shows fields/methods start at modifiers (not attributes? class includes attributes, member likely includes them; keep seg_start)
            let start_byte = code[seg_start].start;
            let end_byte = code[end_tok].end;
            if let Some(pi) = paren_idx {
                // name is ident before '(' (skipping ~ for destructor)
                if pi > an_start && code[pi-1].kind == TK::Ident {
                    let name = code[pi-1].text(src).to_string();
                    let is_destructor = pi >= an_start + 2 && code[pi-2].text(src) == "~";
                    let kind = if is_destructor { "destructor" } else if name == ty.name { "constructor" } else { "method" };
                    members.push(CsMember{kind: kind.to_string(), start: start_byte, end: end_byte, var_decl: None});
                }
            } else {
                // no parens: field or property
                // property if block-bodied and header has at least type+name
                // var_decl: from first type token after modifiers to before ';' (or before block for property, not counted)
                // modifiers list
                let mods = ["public","private","protected","internal","static","readonly","const","volatile","abstract","virtual","override","sealed","new","unsafe","extern","partial","required","event"];
                let mut k = an_start;
                while k < limit && code[k].kind == TK::Ident && mods.contains(&code[k].text(src)) { k += 1; }
                // event fields behave like fields
                let is_event = (an_start..limit).any(|x| is_kw(&code[x], src, "event"));
                if end_is_block {
                    // property (unless it's a nested type - nested types are CsType, skip if segment contains class/struct etc keywords at an_start area)
                    let contains_type_kw = (an_start..limit).any(|x| matches!(code[x].text(src), "class"|"struct"|"interface"|"enum"));
                    if !contains_type_kw {
                        members.push(CsMember{kind: "property".to_string(), start: start_byte, end: end_byte, var_decl: None});
                    }
                } else {
                    // field if header contains at least type+name; var_decl from k
                    // ensure there is an identifier name
                    let has_name = (k..limit).any(|x| code[x].kind == TK::Ident);
                    if has_name {
                        let var_decl = if k < end_tok { Some((code[k].start, code[end_tok- (if code[end_tok].text(src)==";" {1} else {0})].end)) } else { None };
                        // correct var_decl end: token before ';'
                        let var_decl = if code[end_tok].text(src) == ";" && end_tok > k {
                            Some((code[k].start, code[end_tok-1].end))
                        } else { var_decl };
                        let _ = is_event;
                        members.push(CsMember{kind: "field".to_string(), start: start_byte, end: end_byte, var_decl});
                    }
                }
            }
            i = end_tok + 1;
        }
    }
    members
}

fn cs_local_var_decls(code: &[Token], src: &str) -> Vec<(usize, usize)> {
    // statements inside method bodies ending ';' whose start is a type + name pattern
    let mut out = Vec::new();
    // segment by ';'
    let mut bounds: Vec<usize> = vec![0];
    let mut par = 0i32;
    for (idx, t) in code.iter().enumerate() {
        let txt = t.text(src);
        match txt { "(" => par+=1, ")" => par-=1, "{" => bounds.push(idx+1), "}" => bounds.push(idx+1), ";" if par==0 => bounds.push(idx+1), _ => {} }
    }
    bounds.sort(); bounds.dedup();
    for w in bounds.windows(2) {
        let (s, e) = (w[0], w[1]);
        if s >= e { continue; }
        let last = e - 1;
        if code[last].text(src) != ";" { continue; }
        if last == s { continue; }
        // locals: segment starts with type (ident/var/string/...) and has a name ident second-ish
        // Reuse logic: skip if starts with return/if/etc.
        let first = code[s].text(src);
        if matches!(first, "return"|"if"|"else"|"for"|"foreach"|"while"|"switch"|"case"|"break"|"continue"|"using"|"lock"|"throw"|"public"|"private"|"protected"|"internal"|"class"|"struct"|"interface"|"enum") { continue; }
        // require pattern: token0 type, then ident name (allow [] etc)
        // find '=' optional
        // name detection: last ident before '=' or ';' if no '=', at position >= s+1
        // simple: second meaningful token is ident and first is ident/keyword type
        let mut j = s;
        // type may be qualified a.b.C, arrays
        // collect type tokens until name ident that is followed by '=', ';', ',', '['
        // We determine if there's an identifier at position >s such that preceding tokens look type-ish and following is = or ;
        let mut found: Option<(usize, usize)> = None;
        let mut k = s + 1;
        while k < last {
            if code[k].kind == TK::Ident {
                let next = code[k+1].text(src);
                if matches!(next, "=" | ";" | ",") || (next == "[" ) {
                    // ensure tokens between s..k are ident/dot/[]/<> etc
                    found = Some((s, last));
                    break;
                }
            }
            k += 1;
        }
        if let Some((vs, ve)) = found {
            // exclude assignments to existing variable: `x = 5;` where s ident and k==s? loop starts k=s+1, name would be ??? x is at s, next '=' not ident so not found.
            // exclude method calls: if segment contains '(' before '=', likely call - check first '(' position relative to name
            let has_paren_before_eq = (s..last).any(|x| code[x].text(src) == "(");
            if !has_paren_before_eq {
                out.push((code[vs].start, code[ve-1].end));
            }
            let _ = j; j = s;
        }
    }
    out
}

fn cs_identifiers(code: &[Token], src: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let keywords = ["using","namespace","class","struct","interface","enum","public","private","protected","internal","static","void","int","string","bool","var","double","float","long","short","byte","char","decimal","object","dynamic","new","return","if","else","for","foreach","while","do","switch","case","default","break","continue","get","set","add","remove","value","this","base","null","true","false","in","out","ref","params","event","operator","explicit","implicit","virtual","override","abstract","sealed","async","await","typeof","nameof","is","as","lock","try","catch","finally","throw","throws","checked","unchecked","unsafe","fixed","sizeof","stackalloc","record","init","required","partial","readonly","const","volatile","extern","alias","global","nint","nuint","unmanaged","notnull","where","select","from","group","by","orderby","join","let","on","equals","ascending","descending","descendant","sbyte","ushort","uint","ulong","delegate","enum"];
    for t in code {
