fn assign_fields(node: &mut Node, _src: &str) {
    // Heuristic field assignment: `name:` is the first identifier/type_identifier
    // child following a declaration keyword token inside common declaration nodes.
    let is_decl = node.typ.contains("function") || node.typ.contains("struct") || node.typ.contains("enum")
