fn construct_nodes(lang: LangKind, code: &[Token], src: &str) -> Vec<Node> {
    let mut out = Vec::new();
    let mut add = |typ: &str, s: usize, e: usize, out: &mut Vec<Node>| {
        out.push(Node::new(typ, s, e));
    };
    match lang {
        LangKind::Rust => {
            for it in rust_items(code, src) {
                let typ = match it.kind.as_str() {
                    "struct" => "struct_item", "enum" => "enum_item", "trait" => "trait_item",
                    "union" => "union_item", "mod" => "mod_item", "impl" => "impl_item", "type" => "type_item",
                    _ => "item",
                };
                add(typ, it.start, it.end, &mut out);
            }
            for f in rust_fns(code, src) {
                out.push(Node::new("function_item", f.start, f.end));
            }
            for (s, e) in rust_attribute_ranges(code, src) {
                out.push(Node::new("attribute", s, e));
            }
            // use declarations
            for (s, e) in prepared(LangKind::Rust, "uses", src) {
                // whole use_declaration includes use...; approximate node from s-4
                let start = src[..s].rfind("use").map(|p| p).unwrap_or(s);
                let end = if e < src.len() { (e + 1).min(src.len()) } else { e };
                out.push(Node::new("use_declaration", start, end));
            }
            for (s, e) in rust_closures(code, src) { out.push(Node::new("closure_expression", s, e)); }
        }
        LangKind::Go => {
            for f in go_funcs(code, src) {
                let typ = if f.is_method { "method_declaration" } else if f.is_literal { "func_literal" } else { "function_declaration" };
                out.push(Node::new(typ, f.start, f.end));
            }
            // type declarations rough
            // comments already added
        }
        LangKind::C => {
            for d in c_function_declarators(code, src) {
                if d.is_def { out.push(Node::new("function_definition", d.def_range.0, d.def_range.1)); }
            }
        }
        LangKind::CSharp => {
            for it in cs_types(code, src) {
                let typ = match it.kind.as_str() { "class" => "class_declaration", "struct" => "struct_declaration", "interface" => "interface_declaration", "enum" => "enum_declaration", _ => "type_declaration" };
                out.push(Node::new(typ, it.start, it.end));
            }
        }
        LangKind::TypeScript => {
            for f in ts_functions(code, src) { out.push(Node::new("function_declaration", f.start, f.end)); }
            for it in ts_type_items(code, src) {
                let typ = match it.kind.as_str() { "class" => "class_declaration", "enum" => "enum_declaration", "interface" => "interface_declaration", "namespace" => "internal_module", "type-alias" => "type_alias_declaration", _ => "declaration" };
                out.push(Node::new(typ, it.start, it.end));
            }
            for m in ts_methods(code, src) { out.push(Node::new("method_definition", m.start, m.end)); }
        }
        _ => {}
    }
    out
}

fn assemble_tree(lang: LangKind, src: &str, mut nodes: Vec<Node>) -> Node {
    let mut root = Node::new(lang_root_type(lang), 0, src.len());
    nodes.sort_by(|a, b| a.start.cmp(&b.start).then(b.end.cmp(&a.end)));
    // remove exact duplicates
    nodes.dedup_by(|a, b| a.start == b.start && a.end == b.end && a.typ == b.typ);
    // stack based nesting
    fn insert(parent: &mut Node, node: Node) {
        // find child of parent that contains node and insert there, else append
        for child in parent.children.iter_mut() {
            if child.start <= node.start && node.end <= child.end && (child.start, child.end) != (node.start, node.end) {
                insert(child, node);
                return;
            }
            if child.start == node.start && child.end == node.end {
                // same range: nest into existing
                insert(child, node);
                return;
            }
        }
        parent.children.push(node);
    }
    for n in nodes {
        insert(&mut root, n);
    }
    // sort children recursively by start
    fn sort_rec(n: &mut Node) {
        n.children.sort_by(|a, b| a.start.cmp(&b.start).then(b.end.cmp(&a.end)));
        for c in n.children.iter_mut() { sort_rec(c); }
    }
    sort_rec(&mut root);
    assign_fields(&mut root, src);
    root
}

fn lang_root_type(lang: LangKind) -> &'static str {
    match lang {
        LangKind::Python => "module",
        LangKind::Rust => "source_file",
        LangKind::Go => "source_file",
        LangKind::C => "translation_unit",
        LangKind::CSharp => "compilation_unit",
        LangKind::TypeScript => "program",
        LangKind::Hcl => "config_file",
    }
}

fn assign_fields(node: &mut Node, _src: &str) {
    // Heuristic field assignment: `name:` is the first identifier/type_identifier
    // child following a declaration keyword token inside common declaration nodes.
    let is_decl = node.typ.contains("function") || node.typ.contains("struct") || node.typ.contains("enum")
        || node.typ.contains("class") || node.typ.contains("trait") || node.typ.contains("interface")
        || node.typ.contains("mod") || node.typ.contains("type") || node.typ.contains("method") || node.typ.contains("namespace") || node.typ.contains("module");
    if is_decl {
        let mut seen_keyword = false;
        for child in node.children.iter_mut() {
            if child.is_token {
                if matches!(child.typ.as_str(), "fn"|"function"|"struct"|"enum"|"class"|"trait"|"interface"|"mod"|"type"|"def") {
                    seen_keyword = true;
                }
                continue;
            }
            if seen_keyword && child.field.is_none() && matches!(child.typ.as_str(), "identifier" | "type_identifier") {
                child.field = Some("name".to_string());
                break;
            }
        }
    }
    // body: block child
    for child in node.children.iter_mut() {
        assign_fields(child, _src);
    }
}
