// Python scoping via a line/token/indentation parser.
use super::query::Node;
use super::merge_ranges;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TK { Ident, Number, Str, Comment, Punct, Newline }

#[derive(Clone, Debug)]
struct Token {
    kind: TK,
    start: usize,
    end: usize,
    str_segments: Vec<(usize, usize)>,
    is_fstring: bool,
}

fn is_ident_start(c: char) -> bool { c.is_alphabetic() || c == '_' }
fn is_ident_cont(c: char) -> bool { c.is_alphanumeric() || c == '_' }

const KEYWORDS: &[&str] = &[
    "False","None","True","and","as","assert","async","await","break","class","continue","def","del","elif","else","except","finally","for","from","global","if","import","in","is","lambda","nonlocal","not","or","pass","raise","return","try","while","with","yield","match","case",
];

fn lex(src: &str) -> Vec<Token> {
    let chars: Vec<(usize, char)> = src.char_indices().collect();
    let mut toks = Vec::new();
    let mut i = 0usize;
    let byte_at = |i: usize, chars: &Vec<(usize, char)>| if i < chars.len() { chars[i].0 } else { src.len() };
    while i < chars.len() {
        let (b, c) = chars[i];
        if c == ' ' || c == '\t' || c == '\r' { i += 1; continue; }
        if c == '\\' && i + 1 < chars.len() && chars[i+1].1 == '\n' { i += 2; continue; }
        if c == '\n' { toks.push(Token{kind:TK::Newline,start:b,end:b+1,str_segments:vec![],is_fstring:false}); i += 1; continue; }
        if c == '#' {
            let mut j = i;
            while j < chars.len() && chars[j].1 != '\n' { j += 1; }
            toks.push(Token{kind:TK::Comment,start:b,end:byte_at(j,&chars),str_segments:vec![],is_fstring:false});
            i = j; continue;
        }
        // string with optional prefixes
        {
            // gather prefix letters
            let mut j = i;
            let mut prefix = String::new();
            while j < chars.len() && matches!(chars[j].1, 'r'|'R'|'b'|'B'|'u'|'U'|'f'|'F') && prefix.len() < 3 {
                prefix.push(chars[j].1); j += 1;
            }
            if j < chars.len() && (chars[j].1 == '"' || chars[j].1 == '\'') && !prefix.is_empty()
                && prefix.chars().all(|ch| "rRbBuUfF".contains(ch)) {
                // ensure prefix isn't an identifier like `for` etc: prefix must be valid string prefix combos
                let lp = prefix.to_lowercase();
                let valid = ["r","b","u","f","rb","br","fr","rf","ur","ru","bf","fb","ub","bu"].contains(&lp.as_str()) || lp.len() == 1;
                if valid {
                    if let Some((end_b, segs, consumed, isf)) = scan_py_string(src, &chars, j, prefix.to_lowercase().contains('f'), prefix.to_lowercase().contains('r')) {
                        toks.push(Token{kind:TK::Str,start:b,end:end_b,str_segments:segs,is_fstring:isf});
                        i = consumed;
                        continue;
                    }
                }
            }
            if c == '"' || c == '\'' {
                if let Some((end_b, segs, consumed, isf)) = scan_py_string(src, &chars, i, false, false) {
                    toks.push(Token{kind:TK::Str,start:b,end:end_b,str_segments:segs,is_fstring:isf});
                    i = consumed;
                    continue;
                }
            }
        }
        if is_ident_start(c) {
            let mut j = i;
            while j < chars.len() && is_ident_cont(chars[j].1) { j += 1; }
            toks.push(Token{kind:TK::Ident,start:b,end:byte_at(j,&chars),str_segments:vec![],is_fstring:false});
            i = j; continue;
        }
        if c.is_ascii_digit() {
            let mut j = i;
            while j < chars.len() && (chars[j].1.is_alphanumeric() || chars[j].1 == '_' || chars[j].1 == '.') { j += 1; }
            toks.push(Token{kind:TK::Number,start:b,end:byte_at(j,&chars),str_segments:vec![],is_fstring:false});
            i = j; continue;
        }
        // punct longest
        let rest = &src[b..];
        let mut matched: Option<&str> = None;
        for p in ["**=", "//=", ">>=", "<<=", "...", "->", ":=", "==", "!=", "<=", ">=", "**", "//", ">>", "<<", "+=", "-=", "*=", "/=", "%=", "@=", "&=", "|=", "^="] {
            if rest.starts_with(p) { matched = Some(p); break; }
        }
        if let Some(p) = matched {
            toks.push(Token{kind:TK::Punct,start:b,end:b+p.len(),str_segments:vec![],is_fstring:false});
            i += p.chars().count();
            continue;
        }
        toks.push(Token{kind:TK::Punct,start:b,end:byte_at(i+1,&chars),str_segments:vec![],is_fstring:false});
        i += 1;
    }
    toks
}

fn byte_at_idx(chars: &[(usize, char)], i: usize, src: &str) -> usize { if i < chars.len() { chars[i].0 } else { src.len() } }

// scan starting at quote char index qi. Returns end byte, content segments, consumed char index, is_fstring
fn scan_py_string(src: &str, chars: &[(usize, char)], qi: usize, is_f: bool, is_raw: bool) -> Option<(usize, Vec<(usize, usize)>, usize, bool)> {
    let qb = byte_at_idx(chars, qi, src);
    let q = chars[qi].1;
    let triple = qi + 2 < chars.len() && chars[qi+1].1 == q && chars[qi+2].1 == q;
    let delim_len = if triple { 3 } else { 1 };
    let content_start = qb + delim_len;
    let mut j = qi + delim_len;
    let mut segs: Vec<(usize, usize)> = Vec::new();
    let mut seg_start = content_start;
    while j < chars.len() {
        let (cb, c) = chars[j];
        if !is_raw && c == '\\' {
            // escape stays part of string_content; skip next char (don't terminate)
            j += 2;
            continue;
        }
        if is_f && c == '{' {
            // {{ is literal
            if j + 1 < chars.len() && chars[j+1].1 == '{' { j += 2; continue; }
            if cb > seg_start { segs.push((seg_start, cb)); }
            // skip interpolation with brace nesting (strings nested handled loosely)
            let mut depth = 1i32;
            j += 1;
            while j < chars.len() && depth > 0 {
                let ch = chars[j].1;
                if ch == '{' { depth += 1; }
                else if ch == '}' { depth -= 1; }
                else if ch == '"' || ch == '\'' {
                    // skip nested string
                    if let Some((_, _, consumed, _)) = scan_py_string(src, chars, j, false, is_raw) {
                        j = consumed;
                        continue;
                    }
                } else if ch == '\\' { j += 1; }
                j += 1;
            }
            seg_start = byte_at_idx(chars, j, src);
            continue;
        }
        if is_f && c == '}' && j + 1 < chars.len() && chars[j+1].1 == '}' { j += 2; continue; }
        if c == q {
            if triple {
                if j + 2 < chars.len() && chars[j+1].1 == q && chars[j+2].1 == q {
                    if cb > seg_start { segs.push((seg_start, cb)); }
                    let end_b = byte_at_idx(chars, j+3, src);
                    return Some((end_b, segs, j + 3, is_f));
                } else {
                    j += 1; continue;
                }
            } else {
                if cb > seg_start { segs.push((seg_start, cb)); }
                return Some((cb + 1, segs, j + 1, is_f));
            }
        }
        if c == '\n' && !triple {
            // unterminated: end before newline
            if cb > seg_start { segs.push((seg_start, cb)); }
            return Some((cb, segs, j, is_f));
        }
        j += 1;
    }
    if src.len() > seg_start { segs.push((seg_start, src.len())); }
    Some((src.len(), segs, j, is_f))
}

// ---------- line model ----------

struct Line {
    idx: usize, // 0-based line number
    start: usize,
    content_end: usize, // excluding \n (and \r?)
    indent: usize, // byte length of leading whitespace
    toks: Vec<usize>, // indices into tokens (excluding newline)
    is_blank: bool,
    is_comment_only: bool,
}

fn lines_model(src: &str, toks: &[Token]) -> Vec<Line> {
    let mut lines = Vec::new();
    let mut start = 0usize;
    let mut idx = 0usize;
    loop {
        let end = src[start..].find('\n').map_or(src.len(), |p| start + p);
        let mut content_end = end;
        if content_end > start && src.as_bytes()[content_end-1] == b'\r' { content_end -= 1; }
        let line_text = &src[start..content_end];
        let indent = line_text.len() - line_text.trim_start_matches(|c| c == ' ' || c == '\t').len();
        let mut ltoks = Vec::new();
        for (ti, t) in toks.iter().enumerate() {
            if t.kind == TK::Newline { continue; }
            if t.start >= start && t.start < end.max(start+1) || (start == end && t.start == start) {
                if t.start >= start && (t.start < end || end == src.len() && t.start <= end) {
                    ltoks.push(ti);
                }
            }
        }
        // multiline strings: token may start on earlier line but still belongs; for line toks we only include start-line tokens
        let is_blank = line_text.trim().is_empty();
        let is_comment_only = !ltoks.is_empty() && ltoks.iter().all(|&ti| toks[ti].kind == TK::Comment);
        lines.push(Line{idx, start, content_end, indent, toks: ltoks, is_blank, is_comment_only});
        if end >= src.len() { break; }
        start = end + 1;
        idx += 1;
    }
    lines
}

fn tok_text<'a>(toks: &'a [Token], src: &'a str, ti: usize) -> &'a str {
    &src[toks[ti].start..toks[ti].end]
}

fn is_kw(toks: &[Token], src: &str, ti: usize, kw: &str) -> bool {
    toks[ti].kind == TK::Ident && tok_text(toks, src, ti) == kw
}

// indent of lines in spaces-ish bytes (tab counts as 1; mixed indent in tests uses spaces)
fn effective_first_code_line(lines: &[Line], from: usize, header_indent: usize) -> Option<usize> {
    let mut i = from;
    while i < lines.len() {
        let l = &lines[i];
        if l.is_blank || l.is_comment_only { i += 1; continue; }
        if l.indent > header_indent { return Some(i); }
        return None;
    }
    None
}

fn suite_end(lines: &[Line], toks: &[Token], src: &str, header_line: usize, header_indent: usize, header_colon_tok: Option<usize>) -> (usize, usize) {
    // returns (end_byte, end_line_idx)
    // same line suite: tokens after colon on same line
    if let Some(ct) = header_colon_tok {
        // tokens on header line after colon token
        let line_toks = &lines[header_line].toks;
        if let Some(pos) = line_toks.iter().position(|&ti| ti == ct) {
            if pos + 1 < line_toks.len() {
                // there is inline suite; end is last non-comment token on that line
                let last = line_toks.iter().rev().find(|&&ti| toks[ti].kind != TK::Comment).copied().unwrap_or(ct);
                return (toks[last].end, header_line);
            }
        }
    }
    // indented block
    let mut last_line: Option<usize> = None;
    let mut i = header_line + 1;
    while i < lines.len() {
        let l = &lines[i];
        if l.is_blank || l.is_comment_only { i += 1; continue; }
        if l.indent > header_indent {
            last_line = Some(i);
            i += 1;
            continue;
        }
        break;
    }
    if let Some(ll) = last_line {
        // end byte = end of last non-comment token on that line
        let line = &lines[ll];
        let mut end = line.content_end;
        for &ti in line.toks.iter().rev() {
            if toks[ti].kind != TK::Comment { end = toks[ti].end; break; }
        }
        (end, ll)
    } else {
        // empty suite: end at header line content end
        (lines[header_line].content_end, header_line)
    }
}

// find suite colon token index for a header starting at token index start_ti within a line (token pos index into line.toks)
fn find_header_colon(lines: &[Line], toks: &[Token], src: &str, line_idx: usize, start_pos: usize) -> Option<usize> {
    // scan tokens from line start_pos across logical continuation (bracket depth)
    let mut depth = 0i32;
    let mut li = line_idx;
    let mut pos = start_pos;
    loop {
        let line = &lines[li];
        while pos < line.toks.len() {
            let ti = line.toks[pos];
            let t = tok_text(toks, src, ti);
            match t {
                "(" | "[" | "{" => depth += 1,
                ")" | "]" | "}" => depth -= 1,
                ":" if depth == 0 => return Some(ti),
                _ => {}
            }
            pos += 1;
        }
        // multiline header if brackets open or line ends with backslash (lexer removed) -> continue
        if depth > 0 && li + 1 < lines.len() {
            li += 1; pos = 0; continue;
        }
        return None;
    }
}

struct Construct {
    kind: String, // class, def, async-def, with, try, method etc derived later
    start: usize,
    end: usize,
    header_line: usize,
    end_line: usize,
    indent: usize,
    name: Option<String>,
    name_range: Option<(usize, usize)>,
    kw_tok: usize,
    decorators: Vec<(usize, usize)>, // ranges of decorator lines (@ to end)
    is_async: bool,
}

fn find_constructs(lines: &[Line], toks: &[Token], src: &str) -> Vec<Construct> {
    let mut out = Vec::new();
    let mut decorator_run: Vec<(usize, usize, usize)> = Vec::new(); // (start, end, line)
    for li in 0..lines.len() {
        let line = &lines[li];
        if line.is_blank || line.is_comment_only { continue; }
        if line.toks.is_empty() { continue; }
        let first_ti = line.toks[0];
        // decorator line
        if tok_text(toks, src, first_ti) == "@" && !decorator_handled_as_construct(&line, toks, src) {
            let last = line.toks.iter().rev().find(|&&ti| toks[ti].kind != TK::Comment).copied().unwrap_or(first_ti);
            decorator_run.push((toks[first_ti].start, toks[last].end, li));
            continue;
        }
        // candidate kinds at first token position in line, possibly after async
        let mut pos = 0usize;
        let mut is_async = false;
        if is_kw(toks, src, first_ti, "async") && line.toks.len() > 1 && is_kw(toks, src, line.toks[1], "def") {
            is_async = true;
            pos = 1;
        }
        let kw_ti = line.toks[pos];
        let word = tok_text(toks, src, kw_ti);
        if matches!(word, "class" | "def" | "with" | "try") {
            let colon = find_header_colon(lines, toks, src, li, pos);
            let (end, end_line) = if word == "try" {
                let (mut e, mut el) = suite_end(lines, toks, src, li, line.indent, colon);
                // attach except/finally/else clauses at same indent
                loop {
                    // next code line after el
                    let mut ni = el + 1;
                    let mut found: Option<(usize, usize, usize)> = None;
                    while ni < lines.len() {
                        let nl = &lines[ni];
                        if nl.is_blank || nl.is_comment_only { ni += 1; continue; }
                        if nl.indent == line.indent && !nl.toks.is_empty() {
                            let w = tok_text(toks, src, nl.toks[0]);
                            if matches!(w, "except" | "finally" | "else") {
                                let c2 = find_header_colon(lines, toks, src, ni, 0);
                                let (e2, el2) = suite_end(lines, toks, src, ni, nl.indent, c2);
                                found = Some((e2, el2, ni));
                            }
                        }
                        break;
                    }
                    if let Some((e2, el2, _)) = found { e = e2; el = el2; } else { break; }
                }
                (e, el)
            } else {
                suite_end(lines, toks, src, li, line.indent, colon)
            };
            // name
            let (name, name_range) = if matches!(word, "class" | "def") && pos + 1 < line.toks.len() {
                let nt = line.toks[pos+1];
                if toks[nt].kind == TK::Ident {
                    (Some(tok_text(toks, src, nt).to_string()), Some((toks[nt].start, toks[nt].end)))
                } else { (None, None) }
            } else { (None, None) };
            let start = toks[kw_ti].start;
            out.push(Construct {
                kind: if is_async { "async-def".to_string() } else { word.to_string() },
                start,
                end,
                header_line: li,
                end_line,
                indent: line.indent,
                name,
                name_range,
                kw_tok: kw_ti,
                decorators: decorator_run.iter().map(|(s, e, _)| (*s, *e)).collect(),
                is_async,
            });
            decorator_run.clear();
            continue;
        }
        // any other line clears decorator run (decorators only apply to following construct)
        // But decorator_run may precede class/def only; if this line is something else, keep? clear.
        decorator_run.clear();
    }
    out
}

fn decorator_handled_as_construct(_line: &Line, _toks: &[Token], _src: &str) -> bool { false }

// ranges for methods etc
fn class_child_indent(lines: &[Line], c: &Construct) -> Option<usize> {
    effective_first_code_line(lines, c.header_line + 1, c.indent).map(|li| lines[li].indent)
}

pub fn prepared(value: &str, src: &str) -> Vec<(usize, usize)> {
    let (base, _pat) = super::ScopeKind::split_dyn(value);
    let toks = lex(src);
    match base.as_str() {
        "comments" => {
            return toks.iter().filter(|t| t.kind == TK::Comment).map(|t| (t.start, t.end)).collect();
        }
        "strings" => {
            let mut r = Vec::new();
            for t in &toks { if t.kind == TK::Str { r.extend(t.str_segments.iter().copied()); } }
            return r;
        }
        "doc-strings" => {
            return doc_strings(src, &toks);
        }
        "imports" => {
            return py_imports(src, &toks);
        }
        _ => {}
    }
    let lines = lines_model(src, &toks);
    let constructs = find_constructs(&lines, &toks, src);
    let mut out = Vec::new();
    match base.as_str() {
        "class" => {
            for c in constructs.iter().filter(|c| c.kind == "class") { out.push((c.start, c.end)); }
        }
        "def" => {
            for c in constructs.iter().filter(|c| c.kind == "def" || c.kind == "async-def") { out.push((c.start, c.end)); }
        }
        "async-def" => {
            for c in constructs.iter().filter(|c| c.kind == "async-def") { out.push((c.start, c.end)); }
        }
        "function-names" => {
            for c in constructs.iter().filter(|c| c.kind == "def" || c.kind == "async-def") {
                if let Some(nr) = c.name_range { out.push(nr); }
            }
        }
        "function-calls" => {
            out = py_calls(src, &toks);
        }
        "methods" | "class-methods" | "static-methods" => {
            // methods are defs whose direct parent is a class
            for cls in constructs.iter().filter(|c| c.kind == "class") {
                let Some(child_ind) = class_child_indent(&lines, cls) else { continue; };
                for m in constructs.iter().filter(|c| (c.kind == "def" || c.kind == "async-def")) {
                    // method header line is inside class range, indent == child_ind, and its header is not inside a nested def/class deeper
                    if m.header_line > cls.header_line && m.header_line <= cls.end_line && m.indent == child_ind {
                        // ensure the nearest enclosing construct at same (?) is this class: no other class/def construct between
                        let nested = constructs.iter().any(|other| {
                            (other.kind == "class" || other.kind == "def" || other.kind == "async-def")
                                && other.header_line > cls.header_line && other.header_line < m.header_line
                                && other.end_line >= m.header_line && other.indent < m.indent
                                && !(other.header_line == cls.header_line)
                                && other.start != cls.start
                        });
                        if nested { continue; }
                        match base.as_str() {
                            "methods" => {
                                // start at decorator if any else def
                                let start = m.decorators.first().map(|d| d.0).unwrap_or(m.start);
                                out.push((start, m.end));
                            }
                            "class-methods" => {
                                if has_decorator(&m, src, &toks, "classmethod") { out.push((m.start, m.end)); }
                            }
                            "static-methods" => {
                                if has_decorator(&m, src, &toks, "staticmethod") { out.push((m.start, m.end)); }
                            }
                            _ => {}
                        }
                    }
                }
            }
        }
        "with" => {
            for c in constructs.iter().filter(|c| c.kind == "with") { out.push((c.start, c.end)); }
        }
        "try" => {
            for c in constructs.iter().filter(|c| c.kind == "try") { out.push((c.start, c.end)); }
        }
        "lambda" => {
            out = py_lambdas(src, &toks);
        }
        "globals" => {
            out = py_global_vars(src, &toks, &lines);
        }
        "variable-identifiers" => {
            out = py_var_identifiers(src, &toks, &lines, &constructs);
        }
        "types" => {
            out = py_types(src, &toks, &lines, &constructs);
        }
        "identifiers" => {
            for t in &toks {
                if t.kind == TK::Ident && !KEYWORDS.contains(&tok_text(&toks, src, token_index(&toks, t))) {
                    out.push((t.start, t.end));
                }
            }
        }
        _ => {}
    }
    merge_ranges(out)
}

fn token_index(toks: &[Token], t: &Token) -> usize {
    toks.iter().position(|x| x.start == t.start && x.end == t.end).unwrap_or(0)
}

fn has_decorator(c: &Construct, src: &str, toks: &[Token], name: &str) -> bool {
    for (s, e) in &c.decorators {
        let text = &src[*s..*e];
        // decorator text after @ starts with name (possibly dotted)
        let trimmed = text.trim_start_matches('@').trim();
        if trimmed == name || trimmed.starts_with(&format!("{}.", name)) || trimmed.starts_with(&format!("{}(", name)) {
            return true;
        }
        let _ = toks;
    }
    false
}

fn doc_strings(src: &str, toks: &[Token]) -> Vec<(usize, usize)> {
    // string statements that are first statement in module/class/def
    // Approach: locate string tokens whose raw starts with exactly `"""` (possibly after indent)
    // and that are alone on their statement (preceded only by newline/indent or ':' suite start,
    // followed by newline) and which are the first statement of a block.
    // Determine block starts: set of char offsets where a block begins:
    // - 0 (module)
    // - position after class/def header colon: either inline suite start or first indented line start
    let lines_toks = toks;
    // Determine string token indices that are statement sole: line contains only that string token (plus comment)
    // We'll work with lines model
    let lines = lines_model(src, toks);
    let constructs = find_constructs(&lines, toks, src);
    // block first statement line indices:
    let mut first_stmt_lines: Vec<usize> = Vec::new();
    // module: first code line
    for (i, l) in lines.iter().enumerate() {
        if !l.is_blank && !l.is_comment_only { first_stmt_lines.push(i); break; }
    }
    for c in &constructs {
        if matches!(c.kind.as_str(), "class" | "def" | "async-def") {
            // if same-line suite: string token after colon on same line counts
            // else first code line after header
            if let Some(li) = effective_first_code_line(&lines, c.header_line + 1, c.indent) {
                first_stmt_lines.push(li);
            } else {
                // same line suite may exist
                first_stmt_lines.push(c.header_line);
            }
        }
    }
    let mut out = Vec::new();
    for (ti, t) in lines_toks.iter().enumerate() {
        if t.kind != TK::Str { continue; }
        // must start with """ exactly: raw text check; account prefixes none allowed
        if !src[t.start..].starts_with("\"\"\"") { continue; }
        // find line of token
        let Some(line_idx) = lines.iter().position(|l| t.start >= l.start && t.start <= l.content_end.max(l.start)) else { continue; };
        if !first_stmt_lines.contains(&line_idx) { continue; }
        // statement sole: tokens on the first line of the string statement: only this string token (and maybe comment)
        // For same-line suite case, tokens before token on line could be class/def header; accept if token is first after colon
        let line = &lines[line_idx];
        let mut ok = true;
        for &oti in &line.toks {
            let ot = &toks[oti];
            if ot.start < t.start && !(ot.kind == TK::Ident && matches!(tok_text(toks, src, oti), "class"|"def"|"async")) {
                // if token is on header line and before it are header tokens, only ok if string starts after ':'
                // Determine if there's a ':' before token on line.
                let has_colon = line.toks.iter().any(|&x| tok_text(toks, src, x) == ":" && toks[x].start < t.start);
                if !has_colon { ok = false; }
            }
            if ot.start > t.start && ot.kind != TK::Comment && ot.start < t.end {
                // token inside string doesn't exist (lexer treats whole string as one)
            }
        }
        // also the string statement must not be an assignment etc: previous token on same line if any should be ':' or nothing
        // Multi-line string: subsequent lines are part of string, ok.
        if !ok { continue; }
        // It must be first statement: if line is header line (same-line suite), it's first.
        // If its line is first code line of block, it's first.
        let _ = ti;
        out.extend(t.str_segments.iter().copied());
    }
    merge_ranges(out)
}

fn py_imports(src: &str, toks: &[Token]) -> Vec<(usize, usize)> {
    let lines = lines_model(src, toks);
    let mut out = Vec::new();
    for line in &lines {
        if line.toks.is_empty() { continue; }
        let first = line.toks[0];
        if is_kw(toks, src, first, "import") {
            // dotted names after import, split by commas; alias after `as` excluded
            let mut ti = 1usize;
            while ti < line.toks.len() {
                let tok_idx = line.toks[ti];
                if toks[tok_idx].kind == TK::Ident {
                    // dotted name chain
                    let start = toks[tok_idx].start;
                    let mut end = toks[tok_idx].end;
                    let mut k = ti + 1;
                    while k + 1 < line.toks.len() && tok_text(toks, src, line.toks[k]) == "." && toks[line.toks[k+1]].kind == TK::Ident {
                        end = toks[line.toks[k+1]].end;
                        k += 2;
                    }
                    out.push((start, end));
                    ti = k;
                    // skip alias
                    if ti < line.toks.len() && is_kw(toks, src, line.toks[ti], "as") { ti += 2; }
                    // skip comma
                    if ti < line.toks.len() && tok_text(toks, src, line.toks[ti]) == "," { ti += 1; }
                    continue;
                } else {
                    ti += 1;
                }
            }
        } else if is_kw(toks, src, first, "from") {
            // module is token(s) after from: dots and dotted name until `import`
            let mut ti = 1usize;
            // collect start/end of dotted/relative module
            let mut start: Option<usize> = None;
            let mut end: Option<usize> = None;
            while ti < line.toks.len() {
                let tok_idx = line.toks[ti];
                if is_kw(toks, src, tok_idx, "import") { break; }
                let txt = tok_text(toks, src, tok_idx);
                if toks[tok_idx].kind == TK::Ident || txt == "." {
                    if start.is_none() { start = Some(toks[tok_idx].start); }
                    end = Some(toks[tok_idx].end);
                }
                ti += 1;
            }
            if let (Some(s), Some(e)) = (start, end) { out.push((s, e)); }
        }
    }
    out
}

fn py_calls(src: &str, toks: &[Token]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    for (i, t) in toks.iter().enumerate() {
        if t.kind != TK::Ident { continue; }
        let word = tok_text(toks, src, i);
        if KEYWORDS.contains(&word) { continue; }
        if i + 1 >= toks.len() { continue; }
        if tok_text(toks, src, i+1) != "(" { continue; }
        // not preceded by '.' (attribute call) or 'def' or '@'? decorator calls count as calls in tree-sitter (call node)
        if i > 0 {
            let prev = tok_text(toks, src, i-1);
            if prev == "." { continue; }
            if prev == "def" { continue; }
        }
        // not a class/def header name (def handled), not function definition params: prev is def already
        out.push((t.start, t.end));
    }
    out
}

fn py_lambdas(src: &str, toks: &[Token]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < toks.len() {
        if is_kw(toks, src, i, "lambda") {
            // find ':' at depth0 after lambda (params)
            let mut depth = 0i32;
            let mut colon: Option<usize> = None;
            let mut j = i + 1;
            while j < toks.len() {
                let t = tok_text(toks, src, j);
                match t { "(" | "[" | "{" => depth += 1, ")" | "]" | "}" => depth -= 1, ":" if depth == 0 => { colon = Some(j); break; } "\n" => break, _ => {} }
                if toks[j].kind == TK::Newline { break; }
                j += 1;
            }
            if colon.is_some() {
                // body end: token sequence until comma at enclosing depth, closing bracket, ';', newline
                // Determine enclosing depth at lambda: count brackets before body start minus...
                let mut k = j + 1;
                let mut d = 0i32;
                let mut last = j;
                while k < toks.len() {
                    if toks[k].kind == TK::Newline && d == 0 { break; }
                    let t = tok_text(toks, src, k);
                    match t {
                        "(" | "[" | "{" => d += 1,
                        ")" | "]" | "}" => { if d == 0 { break; } d -= 1; },
                        "," if d == 0 => break,
                        ";" if d == 0 => break,
                        _ => {}
                    }
                    if toks[k].kind != TK::Newline { last = k; }
                    k += 1;
                }
                out.push((toks[i].start, toks[last].end));
                i = k.max(i+1);
                continue;
            }
        }
        i += 1;
    }
    out
}

// Assignment target identifier extraction for a token slice region
fn assignment_targets_in_line(lines: &[Line], toks: &[Token], src: &str, line: &Line, constructs: &[Construct]) -> Vec<(usize, usize)> {
    // Skip def/class header lines
    if constructs.iter().any(|c| c.header_line == line.idx && matches!(c.kind.as_str(), "def"|"async-def"|"class")) {
        return vec![];
    }
    let mut out = Vec::new();
    // Work on token indices of line, splitting by ';'
    let mut segments: Vec<Vec<usize>> = Vec::new();
    let mut cur: Vec<usize> = Vec::new();
    for &ti in &line.toks {
        if tok_text(toks, src, ti) == ";" {
            segments.push(std::mem::take(&mut cur));
        } else {
            cur.push(ti);
        }
    }
    if !cur.is_empty() { segments.push(cur); }
    for seg in segments {
        if seg.is_empty() { continue; }
        // skip statements starting with keywords that aren't assignments
        let first_word = tok_text(toks, src, seg[0]);
        if toks[seg[0]].kind == TK::Ident && matches!(first_word, "return"|"if"|"elif"|"else"|"while"|"for"|"with"|"try"|"except"|"finally"|"import"|"from"|"pass"|"break"|"continue"|"raise"|"assert"|"del"|"global"|"nonlocal"|"yield"|"await"|"print") {
            continue;
        }
        // Find depth0 assignment ops: '=', '+=', etc, ':=', and annotated assign pattern
        // Compute depth per token
        let mut depths: Vec<i32> = Vec::new();
        let mut d = 0i32;
        for &ti in &seg {
            depths.push(d);
            match tok_text(toks, src, ti) { "(" | "[" | "{" => d += 1, ")" | "]" | "}" => d -= 1, _ => {} }
        }
        // chained assignments: targets are groups separated by depth0 '=' (not '==' etc lexer distinct)
        let mut assign_positions: Vec<usize> = Vec::new();
        for (idx, &ti) in seg.iter().enumerate() {
            let t = tok_text(toks, src, ti);
            if depths[idx] == 0 && matches!(t, "=" | "+=" | "-=" | "*=" | "/=" | "%=" | "//=" | "**=" | ">>=" | "<<=" | "&=" | "|=" | "^=" | "@=" | ":=") {
                assign_positions.push(idx);
            }
        }
        if !assign_positions.is_empty() {
            // target groups: from segment start to first assign, and between assigns
            let mut group_starts = vec![0usize];
            for &p in &assign_positions { group_starts.push(p + 1); }
            for gs in group_starts.iter().take(assign_positions.len()) {
                let ge = assign_positions[group_starts.iter().position(|x| x == gs).unwrap()];
                if *gs >= ge { continue; }
                let group = &seg[*gs..ge];
                // If group is a single identifier: capture it
                // If tuple/list target: capture identifiers that are not attribute/subscript parts:
                // identifiers in group not preceded by '.' and where group isn't a subscript/call expression.
                // A subscript target like x[0] has '(' '[' after first ident; then it's not a plain variable target - skip first ident?
                // Determine if group contains '[' before any ',' and first token ident followed by '[' -> subscript target, skip.
                if group.len() >= 2 && toks[group[0]].kind == TK::Ident && tok_text(toks, src, group[1]) == "[" {
                    continue;
                }
                if group.len() >= 2 && toks[group[0]].kind == TK::Ident && tok_text(toks, src, group[1]) == "." {
                    continue;
                }
                for (idx, &ti) in group.iter().enumerate() {
                    if toks[ti].kind == TK::Ident && !KEYWORDS.contains(&tok_text(toks, src, ti)) {
                        if idx > 0 && tok_text(toks, src, group[idx-1]) == "." { continue; }
                        out.push((toks[ti].start, toks[ti].end));
                    }
                }
            }
            continue;
        }
        // annotated assignment without '=': IDENT ':' ...
        if seg.len() >= 3 && toks[seg[0]].kind == TK::Ident && !KEYWORDS.contains(&first_word) && tok_text(toks, src, seg[1]) == ":" {
            out.push((toks[seg[0]].start, toks[seg[0]].end));
        }
    }
    out
}

fn py_var_identifiers(src: &str, toks: &[Token], lines: &[Line], constructs: &[Construct]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    for line in lines {
        out.extend(assignment_targets_in_line(lines, toks, src, line, constructs));
    }
    merge_ranges(out)
}

fn py_global_vars(src: &str, toks: &[Token], lines: &[Line]) -> Vec<(usize, usize)> {
    let empty: Vec<Construct> = Vec::new();
    let mut out = Vec::new();
    for line in lines.iter().filter(|l| l.indent == 0) {
        out.extend(assignment_targets_in_line(lines, toks, src, line, &empty));
    }
    merge_ranges(out)
}

fn py_types(src: &str, toks: &[Token], lines: &[Line], constructs: &[Construct]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    // Variable annotations: lines with IDENT ':' type ('=' ...)
    for line in lines {
        if line.toks.is_empty() { continue; }
        // skip def headers handled below separately for params/returns
        let is_def_line = constructs.iter().any(|c| c.header_line == line.idx && matches!(c.kind.as_str(), "def"|"async-def"));
        if is_def_line { continue; }
        // annotated assignment: first ident, colon depth0
        let seg = &line.toks;
        if seg.len() >= 3 && toks[seg[0]].kind == TK::Ident && !KEYWORDS.contains(&tok_text(toks, src, seg[0])) && tok_text(toks, src, seg[1]) == ":" {
            // type tokens from seg[2] to depth0 '=' or end of segment or ';'
            let mut depth = 0i32;
            let mut end_tok: Option<usize> = None;
            for &ti in &seg[2..] {
                let t = tok_text(toks, src, ti);
                match t { "(" | "[" | "{" => depth += 1, ")" | "]" | "}" => depth -= 1, "=" if depth == 0 => break, ";" if depth == 0 => break, _ => {} }
                if depth == 0 && t == "=" { break; }
                end_tok = Some(ti);
            }
            if let Some(e) = end_tok {
                if toks[seg[2]].start < toks[e].end {
                    // strip trailing comment
                    let e2 = if toks[e].kind == TK::Comment { seg[seg.iter().position(|&x| x == e).unwrap()-1] } else { e };
                    out.push((toks[seg[2]].start, toks[e2].end));
                }
            }
        }
    }
    // Def params and returns
    for c in constructs.iter().filter(|c| matches!(c.kind.as_str(), "def"|"async-def")) {
        // locate 'def' name '(' ... ')'
        // Token indices globally: find kw token c.kw_tok
        let kw = c.kw_tok;
        // name is next token, then '('
        let mut i = kw + 1;
        // skip name
        if i < toks.len() && toks[i].kind == TK::Ident { i += 1; }
        if i >= toks.len() || tok_text(toks, src, i) != "(" { continue; }
        let open = i;
        // matching ')'
        let mut depth = 0i32; let mut close: Option<usize> = None;
        let mut j = open;
        while j < toks.len() {
            let t = tok_text(toks, src, j);
            match t { "(" => depth += 1, ")" => { depth -= 1; if depth == 0 { close = Some(j); break; } }, _ => {} }
            j += 1;
        }
        let Some(close) = close else { continue; };
        // params inside: split commas at depth1
        let mut seg_start = open + 1;
        let mut d = 1i32;
        let mut idx = open + 1;
        let mut segments: Vec<(usize, usize)> = Vec::new();
        while idx < close {
            let t = tok_text(toks, src, idx);
            match t { "(" | "[" | "{" => d += 1, ")" | "]" | "}" => d -= 1, "," if d == 1 => { segments.push((seg_start, idx)); seg_start = idx + 1; }, _ => {} }
            idx += 1;
        }
        segments.push((seg_start, close));
        for (s, e) in segments {
            // find ':' at depth1
            let mut dd = 1i32;
            let mut colon: Option<usize> = None;
            for k in s..e {
                let t = tok_text(toks, src, k);
                match t { "(" | "[" | "{" => dd += 1, ")" | "]" | "}" => dd -= 1, ":" if dd == 1 => { colon = Some(k); break; }, _ => {} }
            }
            if let Some(col) = colon {
                // type from col+1 to '=' at depth1 or e
                let mut dd = 1i32; let mut end = e;
                for k in col+1..e {
                    let t = tok_text(toks, src, k);
                    match t { "(" | "[" | "{" => dd += 1, ")" | "]" | "}" => dd -= 1, "=" if dd == 1 => { end = k; break; }, _ => {} }
                }
                if col + 1 < end {
                    out.push((toks[col+1].start, toks[end-1].end));
                }
            }
        }
        // return annotation: '->' after close until ':' at depth0
        if close + 2 < toks.len() && tok_text(toks, src, close+1) == "->" {
            let mut k = close + 2;
            let start = k;
            let mut d = 0i32;
            let mut end = k;
            while k < toks.len() {
                let t = tok_text(toks, src, k);
                match t { "(" | "[" | "{" => d += 1, ")" | "]" | "}" => d -= 1, ":" if d == 0 => break, _ => {} }
                if toks[k].kind == TK::Newline && d == 0 { break; }
                end = k + 1;
                k += 1;
            }
            if start < end {
                out.push((toks[start].start, toks[end-1].end));
            }
        }
        let _ = lines;
    }
    merge_ranges(out)
}

// ---------- tree building ----------

pub fn build_tree(src: &str) -> Node {
    let toks = lex(src);
    let mut root = Node::new("module", 0, src.len());
    let mut nodes: Vec<Node> = Vec::new();
    for t in &toks {
        match t.kind {
            TK::Comment => nodes.push(Node::leaf("comment", &src[t.start..t.end], t.start, t.end)),
            TK::Str => {
                let mut node = Node::leaf("string", &src[t.start..t.end], t.start, t.end);
                // children: string_start, string_content segments, string_end approximated
                for (s, e) in &t.str_segments {
                    node.children.push(Node::leaf("string_content", &src[*s..*e], *s, *e));
                }
                nodes.push(node);
            }
            TK::Ident => {
                let w = &src[t.start..t.end];
                if !KEYWORDS.contains(&w) {
                    nodes.push(Node::leaf("identifier", w, t.start, t.end));
                } else {
                    nodes.push(Node::token(w, t.start, t.end));
                }
            }
            TK::Punct => nodes.push(Node::token(&src[t.start..t.end], t.start, t.end)),
            _ => {}
        }
    }
    // construct nodes
    let lines = lines_model(src, &toks);
    let constructs = find_constructs(&lines, &toks, src);
    for c in &constructs {
        let typ = match c.kind.as_str() {
            "class" => "class_definition",
            "def" | "async-def" => "function_definition",
            "with" => "with_statement",
            "try" => "try_statement",
            _ => "statement",
        };
        nodes.push(Node::new(typ, c.start, c.end));
    }
    // nest nodes into root by containment
    nodes.sort_by(|a, b| a.start.cmp(&b.start).then(b.end.cmp(&a.end)));
    fn insert(parent: &mut Node, node: Node) {
        for child in parent.children.iter_mut() {
            if child.start <= node.start && node.end <= child.end && (child.start, child.end) != (node.start, node.end) {
                insert(child, node);
                return;
            }
            if child.start == node.start && child.end == node.end {
                insert(child, node);
                return;
            }
        }
        parent.children.push(node);
    }
    for n in nodes { insert(&mut root, n); }
    fn sort_rec(n: &mut Node) {
        n.children.sort_by(|a, b| a.start.cmp(&b.start));
        for c in n.children.iter_mut() { sort_rec(c); }
    }
    sort_rec(&mut root);
    root
}
