fn traversal_refs(code: &[Token], src: &str, want_type: bool) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut i = 0;
    while i + 2 < code.len() {
        // traversal start: ident not preceded by '.'
        if code[i].kind == TK::Ident && code[i+1].text(src) == "." && code[i+2].kind == TK::Ident {
            let preceded_by_dot = i > 0 && code[i-1].text(src) == ".";
            if preceded_by_dot { i += 1; continue; }
            let root = code[i].text(src);
            if matches!(root, "var" | "data" | "module" | "local" | "locals" | "each" | "count" | "self" | "path" | "terraform") {
                // skip whole traversal
                let mut j = i;
                while j + 2 < code.len() && code[j+1].text(src) == "." && code[j+2].kind == TK::Ident { j += 2; }
                i = j + 1;
                continue;
