            i = j + 1;
            continue;
        }
        i += 1;
    }
    out
}

impl Token {
    fn text<'a>(&self, src: &'a str) -> &'a str { &src[self.start..self.end] }
}

pub fn build_tree(src: &str) -> Node {
    let toks = lex(src);
    let mut root = Node::new("config_file", 0, src.len());
    let mut nodes: Vec<Node> = Vec::new();
    for t in &toks {
        match t.kind {
            TK::Comment => nodes.push(Node::leaf("comment", &src[t.start..t.end], t.start, t.end)),
            TK::Str | TK::Heredoc => {
                let mut node = Node::leaf("string_literal", &src[t.start..t.end], t.start, t.end);
                for (s, e) in &t.str_segments {
                    node.children.push(Node::leaf("template_string", &src[*s..*e], *s, *e));
                }
                nodes.push(node);
            }
            TK::Ident => nodes.push(Node::leaf("identifier", &src[t.start..t.end], t.start, t.end)),
            TK::Punct => nodes.push(Node::token(&src[t.start..t.end], t.start, t.end)),
            _ => {}
        }
    }
    let code = code_tokens(src);
    for b in find_blocks(&code, src) {
        nodes.push(Node::new("block", b.start, b.end));
        let _ = b.kw_tok;
    }
    nodes.sort_by(|a, b| a.start.cmp(&b.start).then(b.end.cmp(&a.end)));
    fn insert(parent: &mut Node, node: Node) {
        for child in parent.children.iter_mut() {
            if child.start <= node.start && node.end <= child.end && (child.start, child.end) != (node.start, node.end) {
                insert(child, node); return;
            }
            if child.start == node.start && child.end == node.end { insert(child, node); return; }
        }
        parent.children.push(node);
    }
    for n in nodes { insert(&mut root, n); }
    fn sort_rec(n: &mut Node) { n.children.sort_by(|a, b| a.start.cmp(&b.start)); for c in n.children.iter_mut() { sort_rec(c); } }
    sort_rec(&mut root);
    root
}
