// HCL (Terraform) scoping.
use super::query::Node;
use super::merge_ranges;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TK { Ident, Number, Str, Heredoc, Comment, Punct }

#[derive(Clone, Debug)]
struct Token {
    kind: TK,
    start: usize,
    end: usize,
    str_segments: Vec<(usize, usize)>, // for Str/Heredoc
    label: bool, // set later
}

fn is_ident_start(c: char) -> bool { c.is_alphabetic() || c == '_' }
fn is_ident_cont(c: char) -> bool { c.is_alphanumeric() || c == '_' || c == '-' }

fn lex(src: &str) -> Vec<Token> {
    let chars: Vec<(usize, char)> = src.char_indices().collect();
    let byte_at = |i: usize, chars: &Vec<(usize, char)>| if i < chars.len() { chars[i].0 } else { src.len() };
    let mut toks = Vec::new();
    let mut i = 0usize;
    while i < chars.len() {
        let (b, c) = chars[i];
        if c.is_whitespace() { i += 1; continue; }
        if src[b..].starts_with("//") || c == '#' {
            // '#' comment only if not interpolation? at token level, # starts comment in HCL
            // But '#{' doesn't exist in HCL. ok
            let mut j = i;
            // for // and #: to end of line
            // '#' could be inside ?? token level outside strings fine
            if src[b..].starts_with("//") || c == '#' {
                while j < chars.len() && chars[j].1 != '\n' { j += 1; }
                toks.push(Token{kind:TK::Comment,start:b,end:byte_at(j,&chars),str_segments:vec![],label:false});
                i = j; continue;
            }
        }
        if src[b..].starts_with("/*") {
            let mut j = i + 2;
            while j < chars.len() && !src[byte_at(j,&chars)..].starts_with("*/") { j += 1; }
            let end = byte_at((j+2).min(chars.len()),&chars);
            toks.push(Token{kind:TK::Comment,start:b,end,str_segments:vec![],label:false});
            i = (j+2).min(chars.len()); continue;
        }
        // heredoc <<EOT or <<-EOT
        if src[b..].starts_with("<<") {
            let mut j = i + 2;
            if j < chars.len() && chars[j].1 == '-' { j += 1; }
            let marker_start = j;
            while j < chars.len() && (chars[j].1.is_alphanumeric() || chars[j].1 == '_') { j += 1; }
            if j > marker_start {
                let marker: String = chars[marker_start..j].iter().map(|&(_, ch)| ch).collect();
                // content starts after newline
                let mut k = j;
                while k < chars.len() && chars[k].1 != '\n' { k += 1; }
                if k < chars.len() {
                    let content_start = byte_at(k+1,&chars);
                    // find line equal to marker
                    let mut pos = content_start;
                    let mut content_end = src.len();
                    let mut tok_end = src.len();
                    let mut found = false;
                    while pos < src.len() {
                        let line_end = src[pos..].find('\n').map_or(src.len(), |p| pos+p);
                        let line = src[pos..line_end].trim();
                        if line == marker {
                            content_end = pos;
                            tok_end = line_end;
                            found = true;
                            break;
                        }
                        pos = line_end + 1;
                    }
                    if found {
                        // segments: each content line trimmed? Original string scope gave whole line "hello"
                        // We give per-line ranges trimmed of trailing \r
                        let mut segs = Vec::new();
                        let mut p = content_start;
                        while p < content_end {
                            let le = src[p..content_end].find('\n').map_or(content_end, |x| p+x);
                            let mut e = le;
                            if e > p && src.as_bytes()[e-1] == b'\r' { e -= 1; }
                            if e > p { segs.push((p, e)); }
                            p = le + 1;
                        }
                        let consumed = src[..tok_end].chars().count();
                        toks.push(Token{kind:TK::Heredoc,start:b,end:tok_end,str_segments:segs,label:false});
                        i = consumed;
                        continue;
                    }
                }
            }
        }
        if c == '"' {
            // quoted template: segments are literal parts between ${ } and %{ }, trimmed ws at edges
            let mut segs = Vec::new();
            let mut j = i + 1;
            let mut seg_start = b + 1;
            let mut end_b = src.len();
            let mut consumed = chars.len();
            while j < chars.len() {
                let (cb, ch) = chars[j];
                if ch == '\\' { j += 2; continue; }
                if ch == '"' {
                    if cb > seg_start { push_trimmed(src, seg_start, cb, &mut segs); }
                    end_b = cb + 1;
                    consumed = j + 1;
                    break;
                }
                if (ch == '$' || ch == '%') && j + 1 < chars.len() && chars[j+1].1 == '{' {
                    if cb > seg_start { push_trimmed(src, seg_start, cb, &mut segs); }
                    // skip to matching }
                    let mut depth = 1i32;
                    j += 2;
                    while j < chars.len() && depth > 0 {
                        if chars[j].1 == '{' { depth += 1; }
                        else if chars[j].1 == '}' { depth -= 1; }
                        j += 1;
                    }
                    seg_start = byte_at(j,&chars);
                    continue;
                }
                j += 1;
            }
            toks.push(Token{kind:TK::Str,start:b,end:end_b,str_segments:segs,label:false});
            i = consumed;
            continue;
        }
        if is_ident_start(c) {
            let mut j = i;
            while j < chars.len() && is_ident_cont(chars[j].1) { j += 1; }
            toks.push(Token{kind:TK::Ident,start:b,end:byte_at(j,&chars),str_segments:vec![],label:false});
            i = j; continue;
        }
        if c.is_ascii_digit() {
            let mut j = i;
            while j < chars.len() && (chars[j].1.is_alphanumeric() || chars[j].1 == '.' || chars[j].1 == '_') { j += 1; }
            toks.push(Token{kind:TK::Number,start:b,end:byte_at(j,&chars),str_segments:vec![],label:false});
            i = j; continue;
        }
        // punctuation
        let rest = &src[b..];
        let mut matched: Option<&str> = None;
        for p in ["==", "!=", "<=", ">=", "&&", "||", "...", "=>", "->"] {
            if rest.starts_with(p) { matched = Some(p); break; }
        }
        if let Some(p) = matched {
            toks.push(Token{kind:TK::Punct,start:b,end:b+p.len(),str_segments:vec![],label:false});
            i += p.chars().count(); continue;
        }
        toks.push(Token{kind:TK::Punct,start:b,end:byte_at(i+1,&chars),str_segments:vec![],label:false});
        i += 1;
    }
    toks
}

fn push_trimmed(src: &str, mut s: usize, mut e: usize, segs: &mut Vec<(usize, usize)>) {
    while s < e && (src.as_bytes()[s] == b' ' || src.as_bytes()[s] == b'\t') { s += 1; }
    while e > s && (src.as_bytes()[e-1] == b' ' || src.as_bytes()[e-1] == b'\t') { e -= 1; }
    if e > s { segs.push((s, e)); }
}

fn tok_text<'a>(toks: &'a [Token], src: &'a str, ti: usize) -> &'a str { &src[toks[ti].start..toks[ti].end] }

struct Block {
    kind: String,
    start: usize,
    end: usize,
    labels: Vec<(usize, usize, String, usize, usize)>, // (content_start, content_end, text, tok_start, tok_end)
    body_open_tok: usize,
    body_close_tok: usize,
    kw_tok: usize,
}

fn find_blocks(code: &[Token], src: &str) -> Vec<Block> {
    let mut blocks = Vec::new();
    for i in 0..code.len() {
        if code[i].kind != TK::Ident { continue; }
        // block starts if sequence ident (string|ident)* '{' and the ident is at a statement start
        // Statement start heuristic: previous token is '{' '}' or start or ';' or newline-start
        let prev_ok = if i == 0 { true } else {
            let p = &code[i-1];
            matches!(tok_text(code, src, i-1), "{" | "}" | ";") || {
                // previous token ends on earlier line
                src[..code[i].start].matches('\n').count() > src[..p.start].matches('\n').count()
            }
        };
        if !prev_ok { continue; }
        // gather labels until '{'
        let mut j = i + 1;
        let mut labels = Vec::new();
        let mut ok = true;
        while j < code.len() {
            let t = &code[j];
            if t.kind == TK::Str {
                // content is segments joined? label content range is inside quotes: first segment may trim; for label we want inside quotes range
                let content = if t.str_segments.len() == 1 { t.str_segments[0] } else { (t.start+1, t.end-1) };
                let text = src[content.0..content.1].to_string();
                labels.push((content.0, content.1, text, t.start, t.end));
                j += 1;
                continue;
            }
            if t.kind == TK::Ident && labels.is_empty() {
                // could be a block without quotes like `required_providers {` (labels empty) or nested object `aws = {` should not be block
                break;
            }
            break;
        }
        if j < code.len() && code[j].text(src) == "{" {
            // exclude object literals: block header before '{' must not contain '=' before '{' (handled because we stopped)
            // Find matching }
            let mut depth = 0i32;
            let mut close: Option<usize> = None;
            for k in j..code.len() {
                match code[k].text(src) { "{" => depth += 1, "}" => { depth -= 1; if depth == 0 { close = Some(k); break; } }, _ => {} }
            }
            if let Some(close) = close {
                blocks.push(Block{kind: tok_text(code, src, i).to_string(), start: code[i].start, end: code[close].end, labels, body_open_tok: j, body_close_tok: close, kw_tok: i});
            }
            let _ = ok;
        }
    }
    blocks
}

fn code_tokens(src: &str) -> Vec<Token> {
    lex(src).into_iter().filter(|t| t.kind != TK::Comment).collect()
}

pub fn prepared(value: &str, src: &str) -> Vec<(usize, usize)> {
    let (base, _pat) = super::ScopeKind::split_dyn(value);
