            let mut label_tok_ranges: Vec<(usize, usize)> = Vec::new();
            for b in &blocks {
                for (_, _, _, ts, te) in &b.labels { label_tok_ranges.push((*ts, *te)); }
            }
            let mut r = Vec::new();
            for t in &all {
