macro_rules! scope_enum {
    ($name:ident, $( $(#[$meta:meta])* $variant:ident = $val:literal ),* $(,)?) => {
        #[derive(Clone, Copy, Debug, PartialEq, Eq, ValueEnum)]
        pub enum $name {
            $(
                $(#[$meta])*
                #[value(name = $val)]
                $variant,
            )*
        }
        impl $name {
            pub fn as_str(&self) -> &'static str {
                match self { $( $name::$variant => $val, )* }
            }
        }
    };
}

