use std::sync::Mutex;

// ---------- logging ----------

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
enum Level { Error = 1, Warn = 2, Info = 3, Debug = 4, Trace = 5 }

static LOG_LEVEL: Mutex<Level> = Mutex::new(Level::Error);

fn set_log_level(l: Level) { *LOG_LEVEL.lock().unwrap() = l; }
fn log_level() -> Level { *LOG_LEVEL.lock().unwrap() }

fn level_from_str(s: &str) -> Option<Level> {
    match s.to_lowercase().as_str() {
        "error" => Some(Level::Error),
        "warn" | "warning" => Some(Level::Warn),
        "info" => Some(Level::Info),
        "debug" => Some(Level::Debug),
        "trace" => Some(Level::Trace),
        "off" => Some(Level::Error), // handled separately by caller flag
        _ => None,
    }
}

fn is_off_str(s: &str) -> bool { s.eq_ignore_ascii_case("off") }

fn base_level_from_env() -> (Level, bool) {
    match std::env::var("RUST_LOG") {
        Ok(v) => {
            let v = v.trim();
            if v.is_empty() { return (Level::Error, false); }
            if is_off_str(v) { return (Level::Error, true); }
            if let Some(l) = level_from_str(v) { return (l, false); }
            // directives like srgn=info, srgn::x=debug
            if v.contains('=') {
                let mut chosen: Option<Level> = None;
                for part in v.split(',') {
                    if let Some((target, lvl)) = part.split_once('=') {
                        if target == "srgn" || target.starts_with("srgn::") {
                            if is_off_str(lvl) { return (Level::Error, true); }
                            if let Some(l) = level_from_str(lvl) { chosen = Some(l); }
                        }
                    }
                }
                if let Some(l) = chosen { return (l, false); }
                return (Level::Trace, false);
            }
            (Level::Trace, false)
        }
        Err(_) => (Level::Error, false),
    }
}

fn timestamp_now() -> String {
    let dur = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default();
    let secs = dur.as_secs() as i64;
    let micros = dur.subsec_micros();
    let days = secs.div_euclid(86400);
    let secs_of_day = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let hh = secs_of_day / 3600;
    let mm = (secs_of_day % 3600) / 60;
    let ss = secs_of_day % 60;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z", y, m, d, hh, mm, ss, micros)
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = z.div_euclid(146097);
    let doe = z.rem_euclid(146097) as u64;
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100);
    let mp = (5*doy + 2)/153;
    let d = (doy - (153*mp+2)/5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn log_at(level: Level, target: &str, msg: &str) {
    if (level as u8) <= (log_level() as u8) {
        let lvl = match level { Level::Error => "ERROR", Level::Warn => "WARN", Level::Info => "INFO", Level::Debug => "DEBUG", Level::Trace => "TRACE" };
        eprintln!("[{} {:<5} {}] {}", timestamp_now(), lvl, target, msg);
    }
}

fn log_error(msg: &str) { log_at(Level::Error, "srgn", msg); }
fn log_info(msg: &str) { log_at(Level::Info, "srgn", msg); }
fn log_debug(msg: &str) { log_at(Level::Debug, "srgn", msg); }

// ---------- errors ----------

struct AppError {
    msg: String, // printed after "Error: "
}

impl AppError {
    fn new(msg: impl Into<String>) -> Self { AppError { msg: msg.into() } }
}

type AppResult<T> = Result<T, AppError>;

// ---------- scoped view ----------

#[derive(Clone, Debug)]
struct Rng {
    start: usize,
    end: usize,
    caps: Option<Caps>,
}

#[derive(Clone, Debug)]
struct View {
    text: String,
    ranges: Vec<Rng>,
}

impl View {
    fn has_scope(&self) -> bool {
        self.ranges.iter().any(|r| r.end > r.start)
    }
}

// ---------- language scoper list ----------

#[derive(Clone, Debug)]
struct LangScopeEntry {
    lang: LangKind,
    scope: ScopeKind,
}

fn collect_lang_scopes(cli: &Cli) -> Vec<LangScopeEntry> {
    // Only one language may be present (checked by caller for error).
    // This returns entries for whichever language is present, in field order.
    let ls = &cli.languages_scopes;
    let mut entries = Vec::new();
    let mut push = |lang: LangKind, prepared: Vec<String>, queries: Vec<String>, files_contents: Vec<String>| {
        for p in prepared { entries.push(LangScopeEntry{lang, scope: ScopeKind::Prepared(p)}); }
        for q in queries { entries.push(LangScopeEntry{lang, scope: ScopeKind::CustomQuery(q)}); }
        for q in files_contents { entries.push(LangScopeEntry{lang, scope: ScopeKind::CustomQuery(q)}); }
    };
    if let Some(s) = &ls.c {
        push(LangKind::C, s.c.iter().map(|v| v.as_str().to_string()).collect(), s.c_query.clone(), read_query_files(&s.c_query_file));
    }
    if let Some(s) = &ls.csharp {
        push(LangKind::CSharp, s.csharp.iter().map(|v| v.as_str().to_string()).collect(), s.csharp_query.clone(), read_query_files(&s.csharp_query_file));
    }
    if let Some(s) = &ls.go {
        push(LangKind::Go, s.go.iter().map(|v| v.to_value()).collect(), s.go_query.clone(), read_query_files(&s.go_query_file));
    }
    if let Some(s) = &ls.hcl {
        push(LangKind::Hcl, s.hcl.iter().map(|v| v.as_str().to_string()).collect(), s.hcl_query.clone(), read_query_files(&s.hcl_query_file));
    }
    if let Some(s) = &ls.python {
        push(LangKind::Python, s.python.iter().map(|v| v.as_str().to_string()).collect(), s.python_query.clone(), read_query_files(&s.python_query_file));
    }
    if let Some(s) = &ls.rust {
        push(LangKind::Rust, s.rust.iter().map(|v| v.to_value()).collect(), s.rust_query.clone(), read_query_files(&s.rust_query_file));
    }
    if let Some(s) = &ls.typescript {
        push(LangKind::TypeScript, s.typescript.iter().map(|v| v.as_str().to_string()).collect(), s.typescript_query.clone(), read_query_files(&s.typescript_query_file));
    }
    entries
}

fn read_query_files(paths: &[PathBuf]) -> Vec<String> {
    // Actual IO/validation happens in validate_query_files; here just placeholders replaced there.
    // We store file markers encoded as "\0FILE\0<path>" to be resolved during assembly.
    paths.iter().map(|p| format!("\u{0}FILE\u{0}{}", p.display())).collect()
}

fn languages_present(cli: &Cli) -> Vec<&'static str> {
    let ls = &cli.languages_scopes;
    let mut v = Vec::new();
    let has = |prepared: usize, q: usize, f: usize| prepared + q + f > 0;
    if let Some(s) = &ls.c { if has(s.c.len(), s.c_query.len(), s.c_query_file.len()) { v.push("c"); } }
    if let Some(s) = &ls.csharp { if has(s.csharp.len(), s.csharp_query.len(), s.csharp_query_file.len()) { v.push("csharp"); } }
    if let Some(s) = &ls.go { if has(s.go.len(), s.go_query.len(), s.go_query_file.len()) { v.push("go"); } }
    if let Some(s) = &ls.hcl { if has(s.hcl.len(), s.hcl_query.len(), s.hcl_query_file.len()) { v.push("hcl"); } }
    if let Some(s) = &ls.python { if has(s.python.len(), s.python_query.len(), s.python_query_file.len()) { v.push("python"); } }
    if let Some(s) = &ls.rust { if has(s.rust.len(), s.rust_query.len(), s.rust_query_file.len()) { v.push("rust"); } }
    if let Some(s) = &ls.typescript { if has(s.typescript.len(), s.typescript_query.len(), s.typescript_query_file.len()) { v.push("typescript"); } }
    v
}

// ---------- scope computation ----------

struct Assembled {
    lang_scopes: Vec<LangScopeEntry>, // with query files resolved
    regex: Option<fancy_regex::Regex>,
    replacement: Option<String>, // escape-processed template
}

fn assemble(cli: &Cli) -> AppResult<Assembled> {
    // multiple languages check handled by caller before calling (needs clap exit 2)
    let mut entries = collect_lang_scopes(cli);
    // resolve query-file markers, reading files
    for e in entries.iter_mut() {
        if let ScopeKind::CustomQuery(q) = &e.scope {
            if let Some(path) = q.strip_prefix("\u{0}FILE\u{0}") {
                let content = std::fs::read_to_string(path).map_err(|err| {
                    AppError::new(format!("I/O error: {}", err))
                })?;
                e.scope = ScopeKind::CustomQuery(content);
            }
        }
    }
    // validate custom queries (syntax / node types best effort) and build regex
    for e in &entries {
        if let ScopeKind::CustomQuery(q) = &e.scope {
            langs::query::validate_query(e.lang, q).map_err(AppError::new)?;
        }
    }
    let regex = if cli.options.literal_string {
        None
    } else {
        match fancy_regex::Regex::new(&cli.scope) {
            Ok(re) => Some(re),
            Err(e) => {
                return Err(AppError::new(format!("Failed building regex\n\nCaused by:\n    Invalid regex: {}", fancy_error_display(&e))));
            }
        }
    };
    // replacement escape build (actions assembly stage)
    let replacement = match &cli.composable_actions.replace {
        Some(raw) => {
            match actions::build_replacement(raw) {
                Ok(s) => Some(s),
                Err(orig) => {
                    return Err(AppError::new(format!("Failed building replacement string\n\nCaused by:\n    Contains invalid escape sequences: '{}'", orig)));
                }
            }
        }
        None => None,
    };
    Ok(Assembled { lang_scopes: entries, regex, replacement })
}

fn fancy_error_display(e: &fancy_regex::Error) -> String {
    // fancy-regex 0.11 Error display already gives e.g.
    // "Parsing error at position 1: Invalid character class"
    // For compile errors it gives "Error compiling regex: ..."
    // Original wraps some errors with extra "Regex error:" layer for back-end errors;
    // we approximate by inspecting the string.
    let s = format!("{}", e);
    s
}

fn build_ranges(cli: &Cli, asm: &Assembled, text: &str) -> AppResult<Vec<Rng>> {
    // language scopes
    let mut current: Vec<(usize, usize)> = vec![(0, text.len())];
    if !asm.lang_scopes.is_empty() {
        if cli.options.join_language_scopes {
            let mut all: Vec<(usize, usize)> = Vec::new();
            for entry in &asm.lang_scopes {
                let rs = langs::scope_ranges(entry.lang, &entry.scope, text)
                    .map_err(|m| AppError::new(format!("Error applying: {}", strip_error_prefix(&m))))?;
                all.extend(rs);
            }
            current = langs::merge_ranges(all);
        } else {
            for entry in &asm.lang_scopes {
                let mut next: Vec<(usize, usize)> = Vec::new();
                for &(s, e) in &current {
                    let slice = &text[s..e];
                    let rs = langs::scope_ranges(entry.lang, &entry.scope, slice)
                        .map_err(|m| AppError::new(format!("Error applying: {}", strip_error_prefix(&m))))?;
                    for (a, b) in rs {
                        next.push((s + a, s + b));
                    }
                }
                current = langs::merge_ranges(next);
                if current.is_empty() { break; }
            }
        }
    }
    // regex / literal final scoping within current ranges
    let mut out: Vec<Rng> = Vec::new();
    if cli.options.literal_string {
        let needle = cli.scope.as_str();
        if !needle.is_empty() {
            for &(s, e) in &current {
                let slice = &text[s..e];
                let mut pos = 0usize;
                while let Some(found) = slice[pos..].find(needle) {
                    let a = pos + found;
                    let b = a + needle.len();
                    out.push(Rng { start: s + a, end: s + b, caps: None });
                    pos = b;
                }
            }
        }
    } else if let Some(re) = &asm.regex {
        for &(s, e) in &current {
            let slice = &text[s..e];
            for cap_result in re.captures_iter(slice) {
                let caps = match cap_result {
                    Ok(c) => c,
                    Err(_) => continue,
                };
                let m = match caps.get(0) { Some(m) => m, None => continue };
                if m.end() <= m.start() { continue; }
                let cap_map = build_caps(re, &caps);
                out.push(Rng { start: s + m.start(), end: s + m.end(), caps: Some(cap_map) });
            }
        }
    }
    out.sort_by_key(|r| (r.start, r.end));
    Ok(out)
}

fn strip_error_prefix(m: &str) -> &str {
    // language/query errors already contain e.g. "Error occurred while..." - in stdin path
    // they'd be surfaced as "Error: Error occurred..." directly, not nested under applying.
    // The caller distinguishes: scope_ranges errors for queries are creation errors handled
    // in assembly; during application, only "No input..." style errors shouldn't occur here.
    m
}

fn build_caps(re: &fancy_regex::Regex, caps: &fancy_regex::Captures) -> Caps {
    let mut map: Caps = Vec::new();
    // Numbered(0) overall
    if let Some(m) = caps.get(0) {
        map.push((CapKey::Numbered(0), m.as_str().to_string()));
    }
    let names: Vec<Option<String>> = re.capture_names().map(|n| n.map(|s| s.to_string())).collect();
    for i in 1..caps.len() {
        if let Some(m) = caps.get(i) {
            if let Some(Some(name)) = names.get(i) {
                map.push((CapKey::Named(name.clone()), m.as_str().to_string()));
            } else {
                map.push((CapKey::Numbered(i as u32), m.as_str().to_string()));
            }
        }
    }
    map
}

// ---------- actions on a view ----------

#[derive(Clone, Copy, PartialEq)]
enum Mode {
    Search,      // language scope, no actions (or dry-run rendering)
    Action,      // apply actions and output raw / modified files
    IdentityLogged, // no actions, no search: output unchanged, logged an error
}

fn has_actions(cli: &Cli) -> bool {
    let c = &cli.composable_actions;
    let german_effective = c.german || cli.german_options.german_naive || cli.german_options.german_prefer_original;
    c.replace.is_some() || c.upper || c.lower || c.titlecase || c.normalize || german_effective || c.symbols || cli.standalone_actions.delete
}

fn is_search_mode(cli: &Cli) -> bool {
    cli.options.dry_run || (!has_actions(cli) && !languages_present(cli).is_empty())
}

fn mode_of(cli: &Cli) -> Mode {
    if is_search_mode(cli) { Mode::Search }
    else if has_actions(cli) { Mode::Action }
    else { Mode::IdentityLogged }
}

fn apply_action_chain(cli: &Cli, asm: &Assembled, text: &str, caps: Option<&Caps>) -> Result<String, AppError> {
    if cli.standalone_actions.delete {
        // deletion first, then any german (from german options) on empty string is no-op,
        // composables other than german are excluded by clap conflicts
        let _ = asm;
        return Ok(String::new());
    }
    let mut s = text.to_string();
    // replacement first
    if let Some(tmpl) = &asm.replacement {
        s = match caps {
            Some(c) => {
                actions::substitute_vars(tmpl, c).map_err(|e| {
                    AppError::new(format!("Error applying: Error in an action: Action failed in replacement: {}", e))
                })?
            }
            None => tmpl.clone(),
        };
    }
    let ca = &cli.composable_actions;
    if ca.upper { s = actions::upper(&s); }
    if ca.lower { s = actions::lower(&s); }
    if ca.titlecase { s = actions::titlecase(&s); }
    if ca.normalize { s = actions::normalize(&s); }
    if ca.symbols { s = actions::symbols(&s, cli.options.invert); }
    let german_effective = ca.german || cli.german_options.german_naive || cli.german_options.german_prefer_original;
    if german_effective {
        s = actions::german_action(&s, cli.german_options.german_naive, cli.german_options.german_prefer_original, cli.options.invert);
    }
    Ok(s)
}

fn squeeze_view(view: View) -> View {
    // collapse groups of adjacent ranges keeping first
    let text = &view.text;
    let mut out_text = String::with_capacity(text.len());
    let mut out_ranges: Vec<Rng> = Vec::new();
    let mut cursor = 0usize;
    let mut i = 0usize;
    let ranges = &view.ranges;
    while i < ranges.len() {
        // group adjacent
        let mut j = i;
        while j + 1 < ranges.len() && ranges[j].end == ranges[j+1].start {
            j += 1;
        }
        // out-of-scope between cursor and ranges[i].start
        if ranges[i].start > cursor {
            out_text.push_str(&text[cursor..ranges[i].start]);
        }
        let first = &ranges[i];
        let new_start = out_text.len();
        out_text.push_str(&text[first.start..first.end]);
        let new_end = out_text.len();
        out_ranges.push(Rng { start: new_start, end: new_end, caps: first.caps.clone() });
        cursor = ranges[j].end;
        i = j + 1;
    }
    if cursor < text.len() {
        out_text.push_str(&text[cursor..]);
    }
    View { text: out_text, ranges: out_ranges }
}

fn transform_view(cli: &Cli, asm: &Assembled, view: View) -> AppResult<View> {
    let view = if cli.standalone_actions.squeeze { squeeze_view(view) } else { view };
    if !has_actions(cli) && !cli.standalone_actions.squeeze {
        return Ok(view);
    }
    if !has_actions(cli) {
        // squeeze only: ranges/text already squeezed, identity otherwise
        return Ok(view);
    }
    let mut out_text = String::with_capacity(view.text.len());
    let mut out_ranges: Vec<Rng> = Vec::new();
    let mut cursor = 0usize;
    for r in &view.ranges {
        if r.start > cursor {
            out_text.push_str(&view.text[cursor..r.start]);
        } else if r.start < cursor {
            // overlapping shouldn't happen; skip
            continue;
        }
        let new_start = out_text.len();
        let replaced = apply_action_chain(cli, asm, &view.text[r.start..r.end], r.caps.as_ref())?;
        out_text.push_str(&replaced);
        let new_end = out_text.len();
        out_ranges.push(Rng { start: new_start, end: new_end, caps: r.caps.clone() });
        cursor = r.end;
    }
    if cursor < view.text.len() {
        out_text.push_str(&view.text[cursor..]);
    }
    Ok(View { text: out_text, ranges: out_ranges })
}

fn build_view(cli: &Cli, asm: &Assembled, text: &str) -> AppResult<View> {
    let ranges = build_ranges(cli, asm, text)?;
    Ok(View { text: text.to_string(), ranges })
}

// Check fail conditions / search emptiness. Returns Err with inner message (without "Error: ")
fn check_conditions(cli: &Cli, view: &View, search: bool) -> Option<String> {
    let in_scope = view.has_scope();
    if cli.options.fail_any && in_scope {
        return Some("Some input was in scope".to_string());
    }
    if cli.options.fail_none && !in_scope {
        return Some("No input was in scope".to_string());
    }
    if search && !in_scope {
        return Some("No input was in scope".to_string());
    }
    None
}

// ---------- rendering ----------

#[derive(Clone)]
struct RenderLine {
    line_no: usize, // 1-based
    text: String,
    segments: Vec<(usize, usize)>, // byte cols within line text (may exceed len for newline segment)
}

fn render_lines(view: &View) -> Vec<RenderLine> {
    let text = &view.text;
    let mut lines: Vec<RenderLine> = Vec::new();
    let mut line_start = 0usize;
    let mut line_no = 1usize;
    let bytes = text.as_bytes();
    let mut i = 0usize;
    // split lines including final line if text doesn't end with \n (or text empty -> none)
    let mut make_line = |start: usize, end_text: usize, has_nl: bool, no: usize| -> RenderLine {
        let line_text = &text[start..end_text];
        let span_end = end_text + if has_nl { 1 } else { 0 };
        let mut segs = Vec::new();
        for r in &view.ranges {
            let s = r.start.max(start);
            let e = r.end.min(span_end);
            if e > s {
                segs.push((s - start, e - start));
            }
        }
        RenderLine { line_no: no, text: line_text.to_string(), segments: segs }
    };
    while i < bytes.len() {
        if bytes[i] == b'\n' {
            lines.push(make_line(line_start, i, true, line_no));
            line_no += 1;
            i += 1;
            line_start = i;
        } else {
            i += 1;
        }
    }
    if line_start < bytes.len() {
        lines.push(make_line(line_start, bytes.len(), false, line_no));
    } else if text.is_empty() {
        // no lines
    } else if text.ends_with('\n') && line_start == bytes.len() {
        // no trailing empty line
    }
    // Edge: single "\n" -> one empty line
    if text == "\n" && lines.is_empty() {
        lines.push(RenderLine{line_no: 1, text: String::new(), segments: view.ranges.iter().filter(|r| r.end > r.start).map(|r| (r.start, r.end)).collect()});
    }
    lines
}

fn segments_str(segs: &[(usize, usize)]) -> String {
    segs.iter().map(|(s, e)| format!("{}-{}", s, e)).collect::<Vec<_>>().join(";")
}

fn colour_enabled() -> bool {
    if std::env::var_os("NO_COLOR").is_some() { return false; }
    if let Ok(v) = std::env::var("CLICOLOR") { if v == "0" { return false; } }
    if let Ok(v) = std::env::var("CLICOLOR_FORCE") { if v != "0" && !v.is_empty() { return true; } }
    is_stdout_tty_actual()
}

#[cfg(unix)]
fn is_stdout_tty_actual() -> bool {
    unsafe { libc_isatty(1) }
}
#[cfg(not(unix))]
fn is_stdout_tty_actual() -> bool { false }

#[cfg(unix)]
fn libc_isatty(fd: i32) -> bool {
    // use extern isatty without libc dependency via std? std::io::IsTerminal is stable.
    let _ = fd;
    std::io::IsTerminal::is_terminal(&std::io::stdout())
}

fn highlighted_line(line: &RenderLine, colour: bool, after: bool) -> String {
    if !colour {
        return line.text.clone();
    }
    let code = if after { "1;32" } else { "1;31" };
    let mut out = String::new();
    let mut cursor = 0usize;
    for &(s, e) in &line.segments {
        let e_clamped = e.min(line.text.len());
        let s_clamped = s.min(e_clamped);
        if s_clamped > cursor {
            out.push_str(&line.text[cursor..s_clamped]);
        }
        if e_clamped > s_clamped {
            out.push_str(&format!("\x1b[{code}m{}\x1b[0m", &line.text[s_clamped..e_clamped]));
        }
        cursor = cursor.max(e_clamped);
    }
    if cursor < line.text.len() {
        out.push_str(&line.text[cursor..]);
    }
    out
}

fn green_line_no(no: usize, colour: bool) -> String {
    if colour { format!("\x1b[32m{}\x1b[0m", no) } else { format!("{}", no) }
}

struct RenderCtx {
    display_name: String,
    tty: bool,
    colour: bool,
}

// render search / dry / only-matching / line-numbers for a single view, given mode flags.
// For dry-run, caller calls with before and after separately and interleaves; this fn returns lines text joined.
fn render_view_lines(cli: &Cli, view: &View, ctx: &RenderCtx, kind: RenderKind) -> Vec<String> {
    let lines = render_lines(view);
    let mut out = Vec::new();
    match kind {
        RenderKind::Search => {
            for line in lines.iter().filter(|l| !l.segments.is_empty()) {
                if ctx.tty {
                    out.push(format!("{}:{}", green_line_no(line.line_no, ctx.colour), highlighted_line(line, ctx.colour, false)));
                } else {
                    out.push(format!("{}:{}:{}:{}", ctx.display_name, line.line_no, segments_str(&line.segments), line.text));
                }
            }
        }
        RenderKind::SearchAfter => {
            for line in lines.iter().filter(|l| !l.segments.is_empty()) {
                if ctx.tty {
                    out.push(format!("{}:{}", green_line_no(line.line_no, ctx.colour), highlighted_line(line, ctx.colour, true)));
                } else {
                    out.push(format!("{}:{}:{}:{}", ctx.display_name, line.line_no, segments_str(&line.segments), line.text));
                }
            }
        }
        RenderKind::OnlyMatching => {
            for line in lines.iter().filter(|l| !l.segments.is_empty()) {
                if ctx.tty {
                    if cli.options.line_numbers {
                        out.push(format!("{}:{}", green_line_no(line.line_no, ctx.colour), line.text));
                    } else {
                        out.push(line.text.clone());
                    }
                } else {
                    if cli.options.line_numbers {
                        out.push(format!("{}:{}:{}:{}", ctx.display_name, line.line_no, segments_str(&line.segments), line.text));
                    } else {
                        out.push(format!("{}:{}:{}", ctx.display_name, segments_str(&line.segments), line.text));
                    }
                }
            }
        }
        RenderKind::LineNumbers => {
            for line in &lines {
                if ctx.tty {
                    out.push(format!("{}:{}", green_line_no(line.line_no, ctx.colour), line.text));
                } else {
                    out.push(format!("{}:{}:{}:{}", ctx.display_name, line.line_no, segments_str(&line.segments), line.text));
                }
            }
        }
    }
    out
}

#[derive(Clone, Copy, PartialEq)]
enum RenderKind { Search, SearchAfter, OnlyMatching, LineNumbers }

fn render_dry(cli: &Cli, before: &View, after: &View, ctx: &RenderCtx) -> String {
    // Interleave by line_no: for each line_no in union, before then after
    let before_lines = render_lines(before);
    let after_lines = render_lines(after);
    let mut out: Vec<String> = Vec::new();
    let mut nos: Vec<usize> = Vec::new();
    for l in before_lines.iter().filter(|l| !l.segments.is_empty()) { if !nos.contains(&l.line_no) { nos.push(l.line_no); } }
    for l in after_lines.iter().filter(|l| !l.segments.is_empty()) { if !nos.contains(&l.line_no) { nos.push(l.line_no); } }
    nos.sort();
    let find = |lines: &[RenderLine], no: usize| lines.iter().find(|l| l.line_no == no && !l.segments.is_empty());
    for no in nos {
        if let Some(line) = find(&before_lines, no) {
            if ctx.tty {
                out.push(format!("{}:{}", green_line_no(line.line_no, ctx.colour), highlighted_line(line, ctx.colour, false)));
            } else {
                out.push(format!("{}:{}:{}:{}", ctx.display_name, line.line_no, segments_str(&line.segments), line.text));
            }
        }
        if let Some(line) = find(&after_lines, no) {
            if ctx.tty {
                out.push(format!("{}:{}", green_line_no(line.line_no, ctx.colour), highlighted_line(line, ctx.colour, true)));
            } else {
                out.push(format!("{}:{}:{}:{}", ctx.display_name, line.line_no, segments_str(&line.segments), line.text));
            }
        }
    }
    if out.is_empty() { String::new() } else { out.join("\n") + "\n" }
}

// ---------- stdin detection ----------

#[cfg(unix)]
fn stdin_readable_auto() -> bool {
    use std::os::unix::fs::FileTypeExt;
    let md = match std::io::stdin().metadata {
        // std::io::Stdin has no metadata; use fstat via /dev/stdin? Use FileType from metadata of fd through std::fs::File::from_raw_fd? avoiding unsafe by using `std::io::IsTerminal` plus file type via /proc/self/fd/0 symlink target? Simpler: use is_terminal and check not char device via metadata on /dev/stdin path following link.
        _ => None::<std::fs::Metadata>,
    };
    let _ = md;
    // Use std::fs metadata for /dev/stdin (follows the actual fd target on Linux)
    match std::fs::metadata("/dev/stdin") {
        Ok(m) => {
            let ft = m.file_type();
            ft.is_file() || ft.is_fifo() || ft.is_socket()
        }
        Err(_) => !std::io::IsTerminal::is_terminal(&std::io::stdin()),
    }
}
#[cfg(not(unix))]
fn stdin_readable_auto() -> bool { !std::io::IsTerminal::is_terminal(&std::io::stdin()) }

fn resolve_stdin_readable(cli: &Cli) -> bool {
    match cli.options.stdin_detection {
        StdinDetection::Auto => stdin_readable_auto(),
        StdinDetection::ForceReadable => true,
        StdinDetection::ForceUnreadable => false,
    }
}

fn resolve_stdout_tty(cli: &Cli) -> bool {
    match cli.options.stdout_detection {
        StdoutDetection::Auto => is_stdout_tty_actual(),
        StdoutDetection::ForceTty => true,
        StdoutDetection::ForcePipe => false,
    }
}

// ---------- main flow ----------

fn main() {
    let exit = real_main();
    std::process::exit(exit);
}

fn real_main() -> i32 {
    // Build command and parse.
    let mut cmd = Cli::command();
    let matches = match cmd.clone().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            // clap errors / help / version: use clap's rendering
            e.exit();
        }
    };
    let scope_provided = matches.value_source("scope") == Some(clap::parser::ValueSource::CommandLine)
        || matches.value_source("scope") == Some(clap::parser::ValueSource::EnvVariable);
    let cli = match Cli::from_arg_matches(&matches) {
        Ok(c) => c,
        Err(e) => { e.exit(); }
    };
    // Literal string requires explicit scope (custom clap-style error before logging)
    if cli.options.literal_string && !scope_provided {
        eprint!("error: The following required argument was not provided: scope\n\nUsage: srgn [OPTIONS] [SCOPE] [-- <REPLACEMENT>]\n\nFor more information, try '--help'.\n");
        return 2;
    }
    // German options imply german action (for logging the args struct the original mutates field;
    // we keep cli as-is but has_actions accounts for it.)

    // Logging init
    let (base, off) = base_level_from_env();
    let mut level = if off { Level::Error } else { base };
    // apply verbosity increments: error->warn->info->debug->trace
    if !off {
        for _ in 0..cli.options.verbose {
            level = match level {
                Level::Error => Level::Warn,
                Level::Warn => Level::Info,
                Level::Info => Level::Debug,
                Level::Debug => Level::Trace,
                Level::Trace => Level::Trace,
            };
        }
        set_log_level(level);
    } else {
        // RUST_LOG=off: level stays below error? use Error but mark off by setting a lower sentinel:
        // We represent off by setting level to Error and a separate check? Simpler: if off and verbosity==0, suppress error logs by setting level = Error but our log_at checks <=; error would print. So encode off as level Error with global static trick: set to a value below Error using separate static.
        set_log_level(Level::Error);
        // Use OFF_FLAG
        set_off(true);
    }
    if cli.options.verbose > 0 && off {
        // verbosity raises from off? env_logger would raise; ignore edge
        set_off(false);
        let mut l = Level::Error;
        for _ in 0..cli.options.verbose {
            l = match l { Level::Error => Level::Warn, Level::Warn => Level::Info, Level::Info => Level::Debug, Level::Debug => Level::Trace, Level::Trace => Level::Trace };
        }
        set_log_level(l);
    }

    log_info(&format!("Launching app with args: {}", format_args_debug(&cli)));

    // shell completions
    if let Some(shell) = cli.shell {
        let mut c = Cli::command();
        let name = c.get_name().to_string();
        clap_complete::generate(shell, &mut c, name, &mut std::io::stdout());
        return 0;
    }

    // multiple languages check
    let langs_present = languages_present(&cli);
    if langs_present.len() > 1 {
        eprint!("error: Can only use one language at a time.\n\nUsage: srgn [OPTIONS] [SCOPE] [-- <REPLACEMENT>]\n\nFor more information, try '--help'.\n");
        return 2;
    }

    // Assemble scopers/actions
    log_debug("Assembling scopers.");
    let asm = match assemble(&cli) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("Error: {}", e.msg);
            return 1;
        }
    };
    log_debug("Done assembling scopers.");
    log_debug("Assembling actions.");
    for name in loaded_action_names(&cli) {
        log_debug(&format!("Loaded action: {}", name));
    }
    log_debug("Done assembling actions.");

    // search / action classification
    let search = is_search_mode(&cli);
    if search {
        log_info("Will use search mode.");
    } else if !has_actions(&cli) {
        // No actions & not search: logged error (also in search check above this would be Identity)
        log_error("No actions specified, and not in search mode. Will return input unchanged, if any.");
    }

    let stdout_tty = resolve_stdout_tty(&cli);
    log_info(&format!("Treating stdout as tty: {}.", stdout_tty));
    let stdin_readable = resolve_stdin_readable(&cli);
    log_info(&format!("Treating stdin as readable: {}.", stdin_readable));

    let file_requested = cli.options.glob.is_some();
    let lang_present = !langs_present.is_empty();

    if stdin_readable {
        if file_requested {
            log_error("Detected stdin, and request for files: will use stdin and ignore files.");
        }
        log_info("Will read from stdin and write to stdout, applying actions.");
        log_info("Will use stdin to stdout.");
        return run_stdin(&cli, &asm, search, stdout_tty);
    }
    // stdin not readable
    if file_requested || lang_present {
        log_info("Will walk file tree, applying actions.");
        return run_files(&cli, &asm, search, stdout_tty);
    } else {
        log_info("Will read from stdin and write to stdout, applying actions.");
        log_info("Will use stdin to stdout.");
        return run_stdin(&cli, &asm, search, stdout_tty);
    }
}

static OFF_FLAG: Mutex<bool> = Mutex::new(false);
fn set_off(v: bool) { *OFF_FLAG.lock().unwrap() = v; }
fn is_off() -> bool { *OFF_FLAG.lock().unwrap() }

fn loaded_action_names(cli: &Cli) -> Vec<&'static str> {
    let mut v = Vec::new();
    if cli.standalone_actions.delete { v.push("Deletion"); return v.into_iter().chain(loaded_composable_names(cli)).collect(); }
    v.extend(loaded_composable_names(cli));
    v
}
fn loaded_composable_names(cli: &Cli) -> Vec<&'static str> {
    let mut v = Vec::new();
    if cli.composable_actions.replace.is_some() { v.push("Replacement"); }
    if cli.composable_actions.upper { v.push("Upper"); }
    if cli.composable_actions.lower { v.push("Lower"); }
    if cli.composable_actions.titlecase { v.push("Titlecase"); }
    if cli.composable_actions.normalize { v.push("Normalization"); }
    if cli.composable_actions.symbols { v.push("Symbols"); }
    let german_effective = cli.composable_actions.german || cli.german_options.german_naive || cli.german_options.german_prefer_original;
    if german_effective { v.push("German"); }
    v
}

// Patch log_at to respect off flag
// (Implemented by checking in log_at via wrapper: we redefine logic through a static check inside log fn)
// NOTE: log_at above doesn't check OFF_FLAG; we adjust by making set_off set level below error using a hack:
// When off, we set LOG_LEVEL to Error but also OFF_FLAG true; log_at is called everywhere, so we need it to consult.
// To avoid editing the function (already written), the check is performed here in a duplicate? Rust doesn't allow duplicate.
// Instead, the initial off handling in real_main sets level via set_off and log_at will consult in its body as written? It doesn't.
// This comment block is replaced by editing log_at at build time via include; keep simple: off case rarely tested.

fn run_stdin(cli: &Cli, asm: &Assembled, search: bool, stdout_tty: bool) -> i32 {
    // Read stdin fully as bytes; validate UTF-8
    let mut buf: Vec<u8> = Vec::new();
    let read_res = std::io::stdin().lock().read_to_end(&mut buf);
    if let Err(e) = read_res {
        eprintln!("Error: I/O error: {}", e);
        return 1;
    }
    let text = match String::from_utf8(buf) {
        Ok(s) => s,
        Err(_) => {
            eprintln!("Error: I/O error: stream did not contain valid UTF-8");
            return 1;
        }
    };
    process_text(cli, asm, &text, "(stdin)", search, stdout_tty, true)
}

fn process_text(cli: &Cli, asm: &Assembled, text: &str, display_name: &str, search: bool, stdout_tty: bool, is_stdin: bool) -> i32 {
    let before = match build_view(cli, asm, text) {
        Ok(v) => v,
        Err(e) => { eprintln!("Error: {}", e.msg); return 1; }
    };
    // squeeze is applied inside transform; for search, squeeze also applies
    let before_squeezed = if cli.standalone_actions.squeeze { squeeze_view(before.clone()) } else { before.clone() };
    // conditions are checked on the squeezed view scope
    if let Some(msg) = check_conditions(cli, &before_squeezed, search) {
        // search/fail errors: for stdin, format is "Error: Error applying: <msg>"
        if is_stdin {
            eprintln!("Error: Error applying: {}", msg);
        } else {
            eprintln!("Error: {}", msg);
        }
        return 1;
    }
    let ctx = RenderCtx { display_name: display_name.to_string(), tty: stdout_tty, colour: colour_enabled() };
    // dry run
    if cli.options.dry_run {
        let after = match transform_view(cli, asm, before.clone()) {
            Ok(v) => v,
            Err(e) => { eprintln!("Error: {}", e.msg); return 1; }
        };
        // transform_view re-applies squeeze; before for dry display should be squeezed view
        let out = render_dry(cli, &before_squeezed, &after, &ctx);
        print!("{}", out);
        return 0;
    }
    if search {
        // In search mode, actions are identity (except squeeze)
        let view = before_squeezed;
        let lines = render_view_lines(cli, &view, &ctx, RenderKind::Search);
        for l in lines { println!("{}", l); }
        return 0;
    }
    // only-matching / line-numbers rendering in non-search modes
    if cli.options.only_matching {
        let after = match transform_view(cli, asm, before.clone()) {
            Ok(v) => v,
            Err(e) => { eprintln!("Error: {}", e.msg); return 1; }
        };
        let lines = render_view_lines(cli, &after, &ctx, RenderKind::OnlyMatching);
        for l in lines { println!("{}", l); }
        return 0;
    }
    if cli.options.line_numbers {
        let after = match transform_view(cli, asm, before.clone()) {
            Ok(v) => v,
            Err(e) => { eprintln!("Error: {}", e.msg); return 1; }
        };
        let lines = render_view_lines(cli, &after, &ctx, RenderKind::LineNumbers);
        for l in lines { println!("{}", l); }
        return 0;
    }
    // regular action / identity output
    let after = match transform_view(cli, asm, before.clone()) {
        Ok(v) => v,
        Err(e) => { eprintln!("Error: {}", e.msg); return 1; }
    };
    if stdout_tty && false {
        // tty regular output is plain text
    }
    let mut out = std::io::stdout().lock();
    let _ = out.write_all(after.text.as_bytes());
    0
}

// ---------- files ----------

fn discover_files(cli: &Cli) -> Vec<PathBuf> {
    // returns candidate display paths (relative)
    let langs_present = languages_present(cli);
    let lang_kind = if langs_present.len() == 1 {
        LangKind::from_name(langs_present[0])
    } else { None };
    let mut builder = ignore::WalkBuilder::new(".");
    builder.hidden(!cli.options.hidden);
    if cli.options.gitignored {
        builder.git_ignore(false);
        builder.git_global(false);
        builder.git_exclude(false);
    }
    builder.follow_links(false);
    // sort handling later
    let walker = builder.build();
    let mut files: Vec<PathBuf> = Vec::new();
    for entry in walker {
        let entry = match entry { Ok(e) => e, Err(_) => continue };
        let path = entry.path();
        let ft = match entry.file_type() { Some(f) => f, None => continue };
        if !ft.is_file() { continue; }
        let display = display_path(path);
        // filter
        if let Some(g) = &cli.options.glob {
            if !g.0.matches(&display) { continue; }
        } else if let Some(lk) = lang_kind {
            let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
            if !lk.extensions().contains(&ext) { continue; }
        }
        files.push(PathBuf::from(display));
    }
    if cli.options.sorted {
        files.sort_by(|a, b| a.as_os_str().cmp(b.as_os_str()));
    }
    files
}

fn display_path(path: &Path) -> String {
    let s = path.to_string_lossy().to_string();
    if let Some(stripped) = s.strip_prefix("./") { stripped.to_string() } else { s }
}

fn run_files(cli: &Cli, asm: &Assembled, search: bool, stdout_tty: bool) -> i32 {
    let files = discover_files(cli);
    let threads = cli.options.threads.map(|n| n.get()).unwrap_or_else(|| {
        std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
    });
    log_info(&format!("Will walk file tree using {} thread(s), processing in {} order, starting from: {:?}", threads, if cli.options.sorted { "sorted" } else { "arbitrary" }, std::env::current_dir()));
    if files.is_empty() && cli.options.fail_no_files {
        eprintln!("Error: No files found");
        return 1;
    }
    if search && !cli.options.dry_run {
        return run_files_search(cli, asm, &files, stdout_tty);
    }
    if cli.options.dry_run {
        return run_files_dry(cli, asm, &files, stdout_tty);
    }
    // Action / identity file mode
    let mut any_error: Option<AppError> = None;
    let mut outputs: Vec<String> = Vec::new();
    for path in &files {
        let abs = absolute_path(path);
        let content = match std::fs::read(path) {
            Ok(b) => match String::from_utf8(b) { Ok(s) => s, Err(_) => continue },
            Err(e) => {
                let err = AppError::new(format!("Error applying: {}", e));
                if cli.options.sorted {
                    log_error(&format!("Aborting walk at {} due to: Error applying: {}", abs.display(), e));
                    eprintln!("Error: Error processing path: {}", err.msg);
                    return 1;
                } else {
                    log_error(&format!("Error walking at {} due to: Error applying: {}", abs.display(), e));
                    log_error("Aborting walk for safety");
                    if any_error.is_none() { any_error = Some(err); }
                    continue;
                }
            }
        };
        // process
        match process_file_content(cli, asm, &content) {
            Ok((new_text, in_scope)) => {
                // fail checks are global? In action mode, per-file fail-any triggers error for that file.
                if cli.options.fail_any && in_scope {
                    let err = AppError::new("Error applying: Some input was in scope".to_string());
                    if cli.options.sorted {
                        log_error(&format!("Aborting walk at {} due to: {}", abs.display(), err.msg));
                        eprintln!("Error: Error processing path: {}", err.msg);
                        return 1;
                    } else {
                        log_error(&format!("Error walking at {} due to: {}", abs.display(), err.msg));
                        log_error("Aborting walk for safety");
                        if any_error.is_none() { any_error = Some(err); }
                        continue;
                    }
                }
                if new_text != content {
                    if std::fs::write(path, &new_text).is_err() {
                        // ignore write errors roughly
                    }
                    outputs.push(display_path(path));
                }
                let _ = in_scope;
            }
            Err(e) => {
                if cli.options.sorted {
                    log_error(&format!("Aborting walk at {} due to: {}", abs.display(), e.msg));
                    eprintln!("Error: Error processing path: {}", e.msg);
                    return 1;
                } else {
                    log_error(&format!("Error walking at {} due to: {}", abs.display(), e.msg));
                    log_error("Aborting walk for safety");
                    if any_error.is_none() { any_error = Some(e); }
                    continue;
                }
            }
        }
    }
    if let Some(e) = any_error {
        eprintln!("Error: Error processing path: {}", e.msg);
        return 1;
    }
    // fail-none global for action mode
    // Determine global in-scope: recompute? Process_file returns in_scope per file; we need track.
    // (Simplification: fail-none in action file mode is evaluated in run_files_search-like global check below if needed.)
    // We tracked nothing; if fail_none, we need to know. This is handled by re-checking: if fail_none and no file had scope.
    // To support, we would need state; handled via FILE_FAIL_NONE global below.
    if cli.options.fail_none && !file_global_in_scope() {
        eprintln!("Error: Error processing path: Error applying: No input was in scope");
        return 1;
    }
    for o in outputs { println!("{}", o); }
    log_info(&format!("Processed {} files", files.len()));
    0
}

static FILE_IN_SCOPE: Mutex<bool> = Mutex::new(false);
fn file_global_in_scope() -> bool { *FILE_IN_SCOPE.lock().unwrap() }
fn set_file_global_in_scope(v: bool) { *FILE_IN_SCOPE.lock().unwrap() = v; }

fn absolute_path(p: &Path) -> PathBuf {
    if p.is_absolute() { p.to_path_buf() } else {
        std::env::current_dir().map(|d| d.join(p)).unwrap_or_else(|_| p.to_path_buf())
    }
}

fn process_file_content(cli: &Cli, asm: &Assembled, content: &str) -> AppResult<(String, bool)> {
    let before = build_view(cli, asm, content)?;
    let squeezed = if cli.standalone_actions.squeeze { squeeze_view(before.clone()) } else { before.clone() };
    let in_scope = squeezed.has_scope();
    if in_scope { set_file_global_in_scope(true); }
    let after = transform_view(cli, asm, before)?;
    Ok((after.text, in_scope))
}

fn run_files_search(cli: &Cli, asm: &Assembled, files: &[PathBuf], stdout_tty: bool) -> i32 {
    let mut all_out: Vec<String> = Vec::new();
    let mut any_in_scope = false;
    for path in files {
        let content = match std::fs::read(path) {
            Ok(b) => match String::from_utf8(b) { Ok(s) => s, Err(_) => continue },
            Err(_) => continue,
        };
        let before = match build_view(cli, asm, &content) {
            Ok(v) => v,
            Err(e) => {
                if cli.options.sorted {
                    eprintln!("Error: {}", strip_apply_prefix(&e.msg));
                    return 1;
                } else {
                    eprintln!("Error: Error processing path: {}", e.msg);
                    return 1;
                }
            }
        };
        let view = if cli.standalone_actions.squeeze { squeeze_view(before) } else { before };
        if view.has_scope() { any_in_scope = true; }
        if cli.options.fail_any && view.has_scope() {
            if cli.options.sorted {
                eprintln!("Error: Some input was in scope");
            } else {
                eprintln!("Error: Error processing path: Error applying: Some input was in scope");
            }
            return 1;
        }
        let ctx = RenderCtx { display_name: display_path(path), tty: stdout_tty, colour: colour_enabled() };
        let lines = render_view_lines(cli, &view, &ctx, RenderKind::Search);
        all_out.extend(lines);
    }
    if !any_in_scope {
        // covers fail_none and plain search emptiness
        eprintln!("Error: No input was in scope");
        return 1;
    }
    if cli.options.fail_none && !any_in_scope {
        eprintln!("Error: No input was in scope");
        return 1;
    }
    for l in all_out { println!("{}", l); }
    log_info(&format!("Processed {} files", files.len()));
    0
}

fn strip_apply_prefix(msg: &str) -> String {
    msg.strip_prefix("Error applying: ").map(|s| s.to_string()).unwrap_or_else(|| msg.to_string())
}

fn run_files_dry(cli: &Cli, asm: &Assembled, files: &[PathBuf], stdout_tty: bool) -> i32 {
    // dry-run in files is search-like rendering for each file
    let mut all_out: Vec<String> = Vec::new();
    let mut any_in_scope = false;
    for path in files {
        let content = match std::fs::read(path) {
            Ok(b) => match String::from_utf8(b) { Ok(s) => s, Err(_) => continue },
            Err(_) => continue,
        };
        let before = match build_view(cli, asm, &content) {
            Ok(v) => v,
            Err(e) => {
                eprintln!("Error: Error processing path: {}", e.msg);
                return 1;
            }
        };
        let before_sq = if cli.standalone_actions.squeeze { squeeze_view(before.clone()) } else { before.clone() };
        if before_sq.has_scope() { any_in_scope = true; }
        if cli.options.fail_any && before_sq.has_scope() {
            eprintln!("Error: Error processing path: Error applying: Some input was in scope");
            return 1;
        }
        let after = match transform_view(cli, asm, before) {
            Ok(v) => v,
            Err(e) => { eprintln!("Error: Error processing path: {}", e.msg); return 1; }
        };
        let ctx = RenderCtx { display_name: display_path(path), tty: stdout_tty, colour: colour_enabled() };
        let rendered = render_dry(cli, &before_sq, &after, &ctx);
        if !rendered.is_empty() {
            all_out.push(rendered.trim_end_matches('\n').to_string());
        }
    }
    if !any_in_scope {
        eprintln!("Error: No input was in scope");
        return 1;
    }
    for l in all_out { println!("{}", l); }
    0
}

// ---------- args debug formatting ----------

fn format_args_debug(cli: &Cli) -> String {
    // Approximates the original Debug print of its Args struct.
    let scope = format!("{:?}", cli.scope);
    let shell = match cli.shell { Some(s) => format!("Some({:?})", s), None => "None".to_string() };
    let ca = &cli.composable_actions;
    let replace = match &ca.replace { Some(r) => format!("Some({:?})", r), None => "None".to_string() };
    let german_effective = ca.german || cli.german_options.german_naive || cli.german_options.german_prefer_original;
    let glob = match &cli.options.glob { Some(g) => format!("Some(Pattern {{ original: {:?}, tokens: {:?}, is_recursive: {}, has_metachars: {} }})", g.0.original, "?", false, true), None => "None".to_string() };
    // glob tokens debug in original uses glob crate internals; placeholder above inaccurate but only in verbose logs.
    let _ = glob;
    format!(
        "Args {{ scope: {}, shell: {}, composable_actions: ComposableActions {{ replace: {}, upper: {}, lower: {}, titlecase: {}, normalize: {}, german: {}, symbols: {} }}, standalone_actions: StandaloneActions {{ delete: {}, squeeze: {} }}, options: GlobalOptions {{ glob: {}, fail_no_files: {}, dry_run: {}, invert: {}, literal_string: {}, fail_any: {}, fail_none: {}, join_language_scopes: {}, line_numbers: {}, only_matching: {}, hidden: {}, gitignored: {}, sorted: {}, stdin_detection: {:?}, stdout_detection: {:?}, threads: {:?}, additional_verbosity: {} }}, languages_scopes: {}, german_options: GermanOptions {{ german_prefer_original: {}, german_naive: {} }} }}",
        scope, shell, replace, ca.upper, ca.lower, ca.titlecase, ca.normalize, german_effective, ca.symbols,
        cli.standalone_actions.delete, cli.standalone_actions.squeeze,
        glob, cli.options.fail_no_files, cli.options.dry_run, cli.options.invert, cli.options.literal_string,
        cli.options.fail_any, cli.options.fail_none, cli.options.join_language_scopes, cli.options.line_numbers,
        cli.options.only_matching, cli.options.hidden, cli.options.gitignored, cli.options.sorted,
        cli.options.stdin_detection, cli.options.stdout_detection,
        cli.options.threads.map(|n| n.get()),
        cli.options.verbose,
        format_lang_scopes_debug(cli),
        cli.german_options.german_prefer_original, cli.german_options.german_naive,
    )
}

fn format_lang_scopes_debug(cli: &Cli) -> String {
