        fmt_opt(present, format!("CSharpScope {{ csharp: {:?}, csharp_query: {}, csharp_query_file: {:?} }}",
            s.csharp.iter().map(|v| v.as_str()).collect::<Vec<_>>(), fmt_queries(&s.csharp_query), s.csharp_query_file))
