            s.go, fmt_queries(&s.go_query), s.go_query_file))
    } else { "None".to_string() };
    let hcl_str = if let Some(s) = &ls.hcl {
        let present = !(s.hcl.is_empty() && s.hcl_query.is_empty() && s.hcl_query_file.is_empty());
        fmt_opt(present, format!("HclScope {{ hcl: {:?}, hcl_query: {}, hcl_query_file: {:?} }}",
            s.hcl.iter().map(|v| v.as_str()).collect::<Vec<_>>(), fmt_queries(&s.hcl_query), s.hcl_query_file))
    } else { "None".to_string() };
    let py_str = if let Some(s) = &ls.python {
        let present = !(s.python.is_empty() && s.python_query.is_empty() && s.python_query_file.is_empty());
        fmt_opt(present, format!("PythonScope {{ python: {:?}, python_query: {}, python_query_file: {:?} }}",
            s.python, fmt_queries(&s.python_query), s.python_query_file))
    } else { "None".to_string() };
    let rust_str = if let Some(s) = &ls.rust {
        let present = !(s.rust.is_empty() && s.rust_query.is_empty() && s.rust_query_file.is_empty());
        fmt_opt(present, format!("RustScope {{ rust: {:?}, rust_query: {}, rust_query_file: {:?} }}",
            s.rust, fmt_queries(&s.rust_query), s.rust_query_file))
    } else { "None".to_string() };
    let ts_str = if let Some(s) = &ls.typescript {
        let present = !(s.typescript.is_empty() && s.typescript_query.is_empty() && s.typescript_query_file.is_empty());
        fmt_opt(present, format!("TypeScriptScope {{ typescript: {:?}, typescript_query: {}, typescript_query_file: {:?} }}",
            s.typescript.iter().map(|v| v.as_str()).collect::<Vec<_>>(), fmt_queries(&s.typescript_query), s.typescript_query_file))
    } else { "None".to_string() };
    format!("LanguageScopes {{ c: {}, csharp: {}, go: {}, hcl: {}, python: {}, rust: {}, typescript: {} }}",
        c_str, csharp_str, go_str, hcl_str, py_str, rust_str, ts_str)
}

fn fmt_queries(qs: &[String]) -> String {
    let items: Vec<String> = qs.iter().map(|q| format!("QueryLiteral({:?})", q)).collect();
    format!("[{}]", items.join(", "))
}

