#[derive(Clone, PartialEq)]
pub struct DynScope {
    pub base: String,
    pub pattern: Option<String>,
}
impl std::fmt::Debug for DynScope {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let variant = |b: &str| -> String {
            match b {
                "struct" => "Struct".to_string(),
                "interface" => "Interface".to_string(),
                "func" => "Func".to_string(),
                "fn" => "Fn".to_string(),
                "enum" => "Enum".to_string(),
                "trait" => "Trait".to_string(),
                "mod" => "Mod".to_string(),
                _ => b.split('-').map(|p| {
                    let mut c = p.chars();
                    match c.next() { Some(x) => x.to_uppercase().collect::<String>() + c.as_str(), None => String::new() }
                }).collect::<Vec<_>>().join(""),
            }
        };
        if let Some(p) = &self.pattern {
            let named = match self.base.as_str() {
                "struct" => "StructNamed",
                "interface" => "InterfaceNamed",
                "func" => "FuncNamed",
                "fn" => "FnNamed",
                "enum" => "EnumNamed",
                "trait" => "TraitNamed",
                "mod" => "ModNamed",
                _ => "Named",
            };
            write!(f, "{}(TreeSitterRegex(Regex({:?})))", named, p)
        } else {
            write!(f, "{}", variant(&self.base))
        }
    }
}
impl DynScope {
    pub fn to_value(&self) -> String {
        match &self.pattern { Some(p) => format!("{}~{}", self.base, p), None => self.base.clone() }
    }
}

pub struct DynSpec {
    pub name: &'static str,
    pub help: &'static str,
    pub patternable: bool,
    pub pattern_help: Option<&'static str>,
}

#[derive(Clone)]
pub struct DynScopeParser {
    pub arg_name: &'static str,
    pub specs: &'static [DynSpec],
}

impl TypedValueParser for DynScopeParser {
    type Value = DynScope;
    fn parse_ref(&self, cmd: &clap::Command, arg: Option<&clap::Arg>, value: &OsStr) -> Result<Self::Value, clap::Error> {
        let val = value.to_str().unwrap_or("");
        if let Some(pos) = val.find('~') {
            let base = &val[..pos];
            let pattern = &val[pos + 1..];
            match self.specs.iter().find(|s| s.name == base) {
                None => return Err(self.invalid_value_error(cmd, arg, base)),
                Some(spec) if !spec.patternable => {
                    let msg = format!("the argument '{}' cannot be used with 'a pattern ('{}')'", base, pattern);
                    return Err(clap::Error::raw(ErrorKind::ArgumentConflict, format!("{}\n", msg)));
                }
                Some(_) => {
                    if let Err(e) = regex::Regex::new(pattern) {
                        let msg = format!("invalid value '{}' for '{}'\n\n  tip: error was: {}\n", pattern, base, e);
                        return Err(clap::Error::raw(ErrorKind::InvalidValue, msg));
                    }
                    return Ok(DynScope { base: base.to_string(), pattern: Some(pattern.to_string()) });
                }
            }
        }
        if self.specs.iter().any(|s| s.name == val) {
            Ok(DynScope { base: val.to_string(), pattern: None })
        } else {
            Err(self.invalid_value_error(cmd, arg, val))
        }
    }
    fn possible_values(&self) -> Option<Box<dyn Iterator<Item = PossibleValue> + '_>> {
        let mut vals: Vec<PossibleValue> = Vec::new();
        for s in self.specs {
            let mut pv = PossibleValue::new(s.name);
            if !s.help.is_empty() { pv = pv.help(s.help); }
            vals.push(pv);
            if s.patternable {
                let pname = format!("{}~<PATTERN>", s.name);
                let mut ppv = PossibleValue::new(pname);
                if let Some(h) = s.pattern_help { ppv = ppv.help(h); }
                vals.push(ppv);
            }
        }
        Some(Box::new(vals.into_iter()))
    }
}

impl DynScopeParser {
    fn invalid_value_error(&self, cmd: &clap::Command, arg: Option<&clap::Arg>, val: &str) -> clap::Error {
        let mut err = clap::Error::new(ErrorKind::InvalidValue).with_cmd(cmd);
        if let Some(arg) = arg {
            err = err.insert_context(ContextKind::InvalidArg, ContextValue::String(arg.to_string()));
        }
        err = err.insert_context(ContextKind::InvalidValue, ContextValue::String(val.to_string()));
        let mut valid: Vec<String> = Vec::new();
        for s in self.specs {
            valid.push(s.name.to_string());
            if s.patternable { valid.push(format!("{}~<PATTERN>", s.name)); }
        }
        err = err.insert_context(ContextKind::ValidValue, ContextValue::Strings(valid));
        if let Some(best) = best_suggestion(val, self.specs.iter().map(|s| s.name)) {
            err = err.insert_context(ContextKind::SuggestedValue, ContextValue::String(best));
        }
        err
    }
}

fn best_suggestion<'a>(val: &str, candidates: impl Iterator<Item = &'a str>) -> Option<String> {
    let mut best: Option<(f64, String)> = None;
    for cand in candidates {
        let conf = strsim::jaro(val, cand);
        if conf > 0.8 && best.as_ref().map_or(true, |(b, _)| conf > *b) {
            best = Some((conf, cand.to_string()));
        }
    }
    best.map(|(_, s)| s)
}

