            .long_help("Perform substitutions on German words, such as 'Abenteuergruesse' to 'Abenteuergrüße', for anything in scope.\n\nASCII spellings for Umlauts (ae, oe, ue) and Eszett (ss) are replaced by their respective native Unicode (ä, ö, ü, ß).\n\nArbitrary compound words are supported.\n\nWords legally containing alternative spellings are not modified.\n\nWords require correct spelling to be detected.")
            .help_heading(HH_ACTIONS))
        .arg(Arg::new("symbols").short('S').long("symbols").action(ArgAction::SetTrue)
            .help("Perform substitutions on symbols, such as '!=' to '≠', '->' to '→', on anything in scope.")
