            .help("Squeeze consecutive occurrences of scope into one.").help_heading(HH_STANDALONE))
        // Global options
        .arg(Arg::new("glob").short('G').long("glob").value_name("GLOB").value_parser(parse_glob)
            .help("Glob of files to work on (instead of reading stdin).")
            .long_help("Glob of files to work on (instead of reading stdin).\n\nIf actions are applied, they overwrite files in-place.\n\nFor supported glob syntax, see:\n<https://docs.rs/glob/0.3.1/glob/struct.Pattern.html>\n\nNames of processed files are written to stdout.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("fail_no_files").long("fail-no-files").action(ArgAction::SetTrue)
            .help("Fail if working on files (e.g. globbing is requested) but none are found.")
