            .help_heading(HH_GLOBAL))
        .arg(Arg::new("stdin_detection").long("stdin-detection").value_name("STDIN_DETECTION").default_value("auto")
            .value_parser(PossibleValuesParser::new([
                PossibleValue::new("auto").help("Automatically detect if stdin is readable"),
                PossibleValue::new("force-readable").help("Act as if stdin is readable"),
