// ---------- command construction ----------

const HH_ACTIONS: &str = "Composable Actions";
const HH_STANDALONE: &str = "Standalone Actions (only usable alone)";
const HH_GLOBAL: &str = "Options (global)";
const HH_LANG: &str = "Language scopes";
const HH_GERMAN: &str = "Options (german)";

fn lang_args(cmd: Command, prefix: &str, long: &str, alias: Option<&str>, env: &str, value_name: &str, help: &str, table: Option<SpecTable>, dyn_parser: Option<DynScopeParser>) -> Command {
    let prepared_id = prefix.to_string();
    let query_id = format!("{}_query", prefix);
    let file_id = format!("{}_query_file", prefix);
    let mut prepared = Arg::new(prepared_id.clone())
        .long(long)
        .env(env)
        .value_name(value_name)
        .help(help)
        .help_heading(HH_LANG)
        .action(ArgAction::Append)
        .num_args(1)
        .conflicts_with_all([query_id.clone(), file_id.clone()]);
    if let Some(a) = alias { prepared = prepared.visible_alias(a); }
    if let Some(t) = table { prepared = prepared.value_parser(possible_parser(t)); }
    if let Some(p) = dyn_parser { prepared = prepared.value_parser(p); }
    let query = Arg::new(query_id.clone())
        .long(format!("{}-query", long))
        .env(format!("{}_QUERY", env))
        .value_name("TREE-SITTER-QUERY-VALUE")
        .help(format!("Scope {} code using a custom tree-sitter query.", lang_display_name(long)))
        .help_heading(HH_LANG)
        .action(ArgAction::Append)
        .num_args(1)
        .conflicts_with_all([prepared_id.clone(), file_id.clone()]);
    let file = Arg::new(file_id.clone())
        .long(format!("{}-query-file", long))
        .env(format!("{}_QUERY_FILE", env))
        .value_name("TREE-SITTER-QUERY-FILENAME")
        .help(format!("Scope {} code using a custom tree-sitter query from file.", lang_display_name(long)))
        .help_heading(HH_LANG)
        .action(ArgAction::Append)
        .num_args(1)
        .conflicts_with_all([prepared_id, query_id]);
    cmd.arg(prepared).arg(query).arg(file)
}

fn lang_display_name(long: &str) -> &'static str {
    match long {
        "c" => "C",
        "csharp" => "C#",
        "go" => "Go",
        "hcl" => "HashiCorp Configuration Language",
        "python" => "Python",
        "rust" => "Rust",
        "typescript" => "TypeScript",
        _ => "code",
    }
}

pub fn build_command() -> Command {
    let mut cmd = Command::new("srgn")
        .version("0.14.1")
        .about("A grep-like tool which understands source code syntax and allows for manipulation in addition to search")
        .arg(
            Arg::new("scope")
                .value_name("SCOPE")
                .default_value(".*")
                .help("Scope to apply to, as a regular expression pattern.")
                .long_help("Scope to apply to, as a regular expression pattern.\n\nIf string literal mode is requested, will be interpreted as a literal string.\n\nActions will apply their transformations within this scope only.\n\nThe default is the global scope, matching the entire input. Where that default is meaningless or dangerous (e.g., deletion), this argument is required."),
        )
        .arg(
            Arg::new("shell")
                .long("completions")
                .value_name("SHELL")
                .value_parser(PossibleValuesParser::new(["bash", "elvish", "fish", "powershell", "zsh"]))
                .help("Print shell completions for the given shell."),
        )
        // Composable actions
        .arg(
            Arg::new("REPLACEMENT")
                .index(2)
                .env("REPLACE")
                .help("Replace anything in scope with this value.")
                .long_help("Replace anything in scope with this value.\n\nVariables are supported: if a regex pattern was used for scoping and captured content in named or numbered capture groups, access these in the replacement value using `$1` etc. for numbered, `$NAME` etc. for named capture groups.\n\nThis action is specially treated as a positional argument for ergonomics and compatibility with `tr`.\n\nIf given, will run before any other action.")
                .help_heading(HH_ACTIONS),
        )
        .arg(Arg::new("upper").short('u').long("upper").env("UPPER").action(ArgAction::SetTrue).help("Uppercase anything in scope.").help_heading(HH_ACTIONS))
        .arg(Arg::new("lower").short('l').long("lower").env("LOWER").action(ArgAction::SetTrue).help("Lowercase anything in scope.").help_heading(HH_ACTIONS))
        .arg(Arg::new("titlecase").short('t').long("titlecase").env("TITLECASE").action(ArgAction::SetTrue).help("Titlecase anything in scope.").help_heading(HH_ACTIONS))
        .arg(Arg::new("normalize").short('n').long("normalize").env("NORMALIZE").action(ArgAction::SetTrue).help("Normalize (Normalization Form D) anything in scope, and throw away marks.").help_heading(HH_ACTIONS))
        .arg(Arg::new("german").short('g').long("german").action(ArgAction::SetTrue)
            .help("Perform substitutions on German words, such as 'Abenteuergruesse' to 'Abenteuergrüße', for anything in scope.")
            .long_help("Perform substitutions on German words, such as 'Abenteuergruesse' to 'Abenteuergrüße', for anything in scope.\n\nASCII spellings for Umlauts (ae, oe, ue) and Eszett (ss) are replaced by their respective native Unicode (ä, ö, ü, ß).\n\nArbitrary compound words are supported.\n\nWords legally containing alternative spellings are not modified.\n\nWords require correct spelling to be detected.")
            .help_heading(HH_ACTIONS))
        .arg(Arg::new("symbols").short('S').long("symbols").action(ArgAction::SetTrue)
            .help("Perform substitutions on symbols, such as '!=' to '≠', '->' to '→', on anything in scope.")
            .long_help("Perform substitutions on symbols, such as '!=' to '≠', '->' to '→', on anything in scope.\n\nHelps translate 'ASCII art' into native Unicode representations.")
            .help_heading(HH_ACTIONS))
        // Standalone
        .arg(Arg::new("delete").short('d').long("delete").action(ArgAction::SetTrue)
            .conflicts_with_all(["REPLACEMENT", "upper", "lower", "titlecase", "normalize", "german", "symbols", "squeeze"])
            .requires("scope")
            .help("Delete anything in scope.")
            .long_help("Delete anything in scope.\n\nCannot be used with any other action: there is no point in deleting and performing any other processing. Sibling actions would either receive empty input or have their work wiped.")
            .help_heading(HH_STANDALONE))
        .arg(Arg::new("squeeze").short('s').long("squeeze").env("SQUEEZE").action(ArgAction::SetTrue).visible_alias("squeeze-repeats")
            .conflicts_with("delete")
            .requires("scope")
            .help("Squeeze consecutive occurrences of scope into one.").help_heading(HH_STANDALONE))
        // Global options
        .arg(Arg::new("glob").short('G').long("glob").value_name("GLOB").value_parser(parse_glob)
            .help("Glob of files to work on (instead of reading stdin).")
            .long_help("Glob of files to work on (instead of reading stdin).\n\nIf actions are applied, they overwrite files in-place.\n\nFor supported glob syntax, see:\n<https://docs.rs/glob/0.3.1/glob/struct.Pattern.html>\n\nNames of processed files are written to stdout.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("fail_no_files").long("fail-no-files").action(ArgAction::SetTrue)
            .help("Fail if working on files (e.g. globbing is requested) but none are found.")
            .long_help("Fail if working on files (e.g. globbing is requested) but none are found.\n\nProcessing no files is not an error condition in itself, but might be an unexpected outcome in some contexts. This flag makes the condition explicit.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("dry_run").long("dry-run").action(ArgAction::SetTrue)
            .help("Do not destructively overwrite files, instead print rich diff only.")
            .long_help("Do not destructively overwrite files, instead print rich diff only.\n\nThe diff details the names of files which would be modified, alongside all changes inside those files which would be performed outside of dry running. It is similar to git diff with word diffing enabled.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("invert").short('i').long("invert").env("INVERT").action(ArgAction::SetTrue).requires("symbols")
            .help("Undo the effects of passed actions, where applicable.")
            .long_help("Undo the effects of passed actions, where applicable.\n\nRequires a 1:1 mapping between replacements and original, which is currently available only for:\n\n- symbols: '≠' <-> '!=' etc.\n\nOther actions:\n\n- german: inverting e.g. 'Ä' is ambiguous (can be 'Ae' or 'AE')\n\n- upper, lower, deletion, squeeze: inversion is impossible as information is lost\n\nThese may still be passed, but will be ignored for inversion and applied normally.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("literal_string").short('L').long("literal-string").env("LITERAL_STRING").action(ArgAction::SetTrue)
            .help("Do not interpret the scope as a regex. Instead, interpret it as a literal string. Will require a scope to be passed.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("fail_any").long("fail-any").action(ArgAction::SetTrue)
            .help("If anything at all is found to be in scope, fail.")
            .long_help("If anything at all is found to be in scope, fail.\n\nThe default is to continue processing normally.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("fail_none").long("fail-none").action(ArgAction::SetTrue)
            .help("If nothing is found to be in scope, fail.")
            .long_help("If nothing is found to be in scope, fail.\n\nThe default is to return the input unchanged (without failure).")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("join_language_scopes").short('j').long("join-language-scopes").action(ArgAction::SetTrue)
            .help("Join (logical 'OR') multiple language scopes, instead of intersecting them.")
            .long_help("Join (logical 'OR') multiple language scopes, instead of intersecting them.\n\nThe default when multiple language scopes are given is to intersect their scopes, left to right. For example, `--go func --go strings` will first scope down to `func` bodies, then look for strings only within those. This flag instead joins (in the set logic sense) all scopes. The example would then scope any `func` bodies, and any strings, anywhere. Language scopers can then also be given in any order.\n\nNo effect if only a single language scope is given. Also does not affect non-language scopers (regex pattern etc.), which always intersect.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("line_numbers").long("line-numbers").hide(true).action(ArgAction::SetTrue).help("Prepend line numbers to output.").help_heading(HH_GLOBAL))
        .arg(Arg::new("only_matching").long("only-matching").hide(true).action(ArgAction::SetTrue).help("Print only matching lines.").help_heading(HH_GLOBAL))
        .arg(Arg::new("hidden").short('H').long("hidden").action(ArgAction::SetTrue).help("Do not ignore hidden files and directories.").help_heading(HH_GLOBAL))
        .arg(Arg::new("gitignored").long("gitignored").action(ArgAction::SetTrue).help("Do not ignore `.gitignore`d files and directories.").help_heading(HH_GLOBAL))
        .arg(Arg::new("sorted").long("sorted").action(ArgAction::SetTrue)
            .help("Process files in lexicographically sorted order, by file path.")
            .long_help("Process files in lexicographically sorted order, by file path.\n\nIn search mode, this emits results in sorted order. Otherwise, it processes files in sorted order.\n\nSorted processing disables parallel processing.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("stdin_detection").long("stdin-detection").value_name("STDIN_DETECTION").default_value("auto")
            .value_parser(PossibleValuesParser::new([
                PossibleValue::new("auto").help("Automatically detect if stdin is readable"),
                PossibleValue::new("force-readable").help("Act as if stdin is readable"),
                PossibleValue::new("force-unreadable").help("Act as if stdin is not readable"),
            ]))
            .help("Control heuristics for stdin readability detection, and force to value.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("stdout_detection").long("stdout-detection").value_name("STDOUT_DETECTION").default_value("auto")
            .value_parser(PossibleValuesParser::new([
                PossibleValue::new("auto").help("Automatically detect if stdout is a TTY and act accordingly"),
                PossibleValue::new("force-tty").help("Act as if stdout is a TTY"),
                PossibleValue::new("force-pipe").help("Act as if stdout is not a TTY, e.g. a pipe, redirect"),
            ]))
            .help("Control heuristics for stdout detection, and potentially force to value.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("threads").long("threads").value_name("THREADS")
            .value_parser(clap::value_parser!(std::num::NonZeroUsize))
            .help("Number of threads to run processing on, when working with files.")
            .long_help("Number of threads to run processing on, when working with files.\n\nIf not specified, will default to available parallelism. Set to 1 for sequential, deterministic (but not sorted) output.")
            .help_heading(HH_GLOBAL))
        .arg(Arg::new("verbose").short('v').long("verbose").action(ArgAction::Count)
            .help("Increase log verbosity level.")
            .long_help("Increase log verbosity level.\n\nThe base log level to use is read from the `RUST_LOG` environment variable (if unspecified, defaults to 'error'), and increased according to the number of times this flag is given, maxing out at 'trace' verbosity.")
            .help_heading(HH_GLOBAL));
    // languages in order: c, csharp, go, hcl, python, rust, typescript
    cmd = lang_args(cmd, "c", "c", None, "C", "C", "Scope C code using a prepared query.", Some(C_SPECS), None);
    cmd = lang_args(cmd, "csharp", "csharp", Some("cs"), "CSHARP", "CSHARP", "Scope C# code using a prepared query.", Some(CSHARP_SPECS), None);
    cmd = lang_args(cmd, "go", "go", None, "GO", "GO", "Scope Go code using a prepared query.", None, Some(go_parser()));
    cmd = lang_args(cmd, "hcl", "hcl", None, "HCL", "HCL", "Scope HashiCorp Configuration Language code using a prepared query.", Some(HCL_SPECS), None);
    cmd = lang_args(cmd, "python", "python", Some("py"), "PYTHON", "PYTHON", "Scope Python code using a prepared query.", Some(PYTHON_SPECS), None);
    cmd = lang_args(cmd, "rust", "rust", Some("rs"), "RUST", "RUST", "Scope Rust code using a prepared query.", None, Some(rust_parser()));
    cmd = lang_args(cmd, "typescript", "typescript", Some("ts"), "TYPESCRIPT", "TYPESCRIPT", "Scope TypeScript code using a prepared query.", Some(TS_SPECS), None);
    // german options
    cmd = cmd
        .arg(Arg::new("german_prefer_original").long("german-prefer-original").env("GERMAN_PREFER_ORIGINAL").action(ArgAction::SetTrue)
            .help("When some original version and its replacement are equally legal, prefer the original and do not modify.")
            .long_help("When some original version and its replacement are equally legal, prefer the original and do not modify.\n\nFor example, \"Busse\" (original) and \"Buße\" (replacement) are equally legal words: by default, the tool would prefer the latter.")
            .help_heading(HH_GERMAN))
        .arg(Arg::new("german_naive").long("german-naive").env("GERMAN_NAIVE").action(ArgAction::SetTrue)
            .help("Always perform any possible replacement ('ae' -> 'ä', 'ss' -> 'ß', etc.), regardless of legality of the resulting word")
            .long_help("Always perform any possible replacement ('ae' -> 'ä', 'ss' -> 'ß', etc.), regardless of legality of the resulting word\n\nUseful for names, which are otherwise not modifiable as they do not occur in dictionaries. Called 'naive' as this does not perform legal checks.")
            .help_heading(HH_GERMAN));
    cmd
}

// ---------- parsing from matches ----------

fn get_bool(m: &clap::ArgMatches, id: &str) -> bool { m.get_flag(id) }
fn get_string(m: &clap::ArgMatches, id: &str) -> Option<String> { m.get_one::<String>(id).cloned() }
fn get_vec_string(m: &clap::ArgMatches, id: &str) -> Vec<String> {
    m.get_many::<String>(id).map(|v| v.cloned().collect()).unwrap_or_default()
}
fn get_vec_path(m: &clap::ArgMatches, id: &str) -> Vec<PathBuf> {
    // query-file values are stored as String by the builder (no value_parser), convert
    get_vec_string(m, id).into_iter().map(PathBuf::from).collect()
}
fn get_vec_dyn(m: &clap::ArgMatches, id: &str) -> Vec<DynScope> {
    m.get_many::<DynScope>(id).map(|v| v.cloned().collect()).unwrap_or_default()
}

pub fn cli_from_matches(m: &clap::ArgMatches) -> Cli {
    let shell = get_string(m, "shell").map(|s| match s.as_str() {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        "zsh" => Shell::Zsh,
        _ => Shell::Bash,
    });
    let lang_group = |prefix: &str| LangGroup {
        values: get_vec_string(m, prefix),
        query: get_vec_string(m, &format!("{}_query", prefix)),
        query_file: get_vec_path(m, &format!("{}_query_file", prefix)),
    };
    let lang_group_dyn = |prefix: &str| LangGroupDyn {
        values: get_vec_dyn(m, prefix),
        query: get_vec_string(m, &format!("{}_query", prefix)),
        query_file: get_vec_path(m, &format!("{}_query_file", prefix)),
    };
    Cli {
        scope: get_string(m, "scope").unwrap_or_else(|| ".*".to_string()),
        shell,
        composable_actions: ComposableActions {
            replace: get_string(m, "REPLACEMENT"),
            upper: get_bool(m, "upper"),
            lower: get_bool(m, "lower"),
            titlecase: get_bool(m, "titlecase"),
            normalize: get_bool(m, "normalize"),
            german: get_bool(m, "german"),
            symbols: get_bool(m, "symbols"),
        },
        standalone_actions: StandaloneActions {
            delete: get_bool(m, "delete"),
            squeeze: get_bool(m, "squeeze"),
        },
        options: GlobalOptions {
            glob: m.get_one::<GlobPattern>("glob").cloned(),
            fail_no_files: get_bool(m, "fail_no_files"),
            dry_run: get_bool(m, "dry_run"),
            invert: get_bool(m, "invert"),
            literal_string: get_bool(m, "literal_string"),
            fail_any: get_bool(m, "fail_any"),
            fail_none: get_bool(m, "fail_none"),
            join_language_scopes: get_bool(m, "join_language_scopes"),
            line_numbers: get_bool(m, "line_numbers"),
            only_matching: get_bool(m, "only_matching"),
            hidden: get_bool(m, "hidden"),
            gitignored: get_bool(m, "gitignored"),
            sorted: get_bool(m, "sorted"),
            stdin_detection: match get_string(m, "stdin_detection").as_deref() {
                Some("force-readable") => StdinDetection::ForceReadable,
                Some("force-unreadable") => StdinDetection::ForceUnreadable,
                _ => StdinDetection::Auto,
            },
            stdout_detection: match get_string(m, "stdout_detection").as_deref() {
                Some("force-tty") => StdoutDetection::ForceTty,
                Some("force-pipe") => StdoutDetection::ForcePipe,
                _ => StdoutDetection::Auto,
            },
            threads: m.get_one::<std::num::NonZeroUsize>("threads").copied(),
            verbose: m.get_count("verbose"),
        },
        languages_scopes: LanguageScopes {
            c: lang_group("c"),
            csharp: lang_group("csharp"),
            go: lang_group_dyn("go"),
            hcl: lang_group("hcl"),
            python: lang_group("python"),
            rust: lang_group_dyn("rust"),
            typescript: lang_group("typescript"),
        },
        german_options: GermanOptions {
            german_prefer_original: get_bool(m, "german_prefer_original"),
            german_naive: get_bool(m, "german_naive"),
        },
    }
}
