pub fn validate_query(lang: super::LangKind, query_text: &str) -> Result<(), String> {
    // Build a dummy empty tree and attempt to run parsing/validation logic
    // by reusing run_query's parse path: we parse tops and validate node types.
    // Simpler: try running the query against an empty tree; syntax errors surface there.
    let root = Node::new(lang.root_node_type(), 0, 0);
    // validate syntax by parsing: run_query returns ranges; creation errors are the ones we want.
    // But node types unknown in an empty tree would all be missing; we validate against a known set instead.
    validate_node_types(lang, query_text)?;
    let _ = run_query(&root, "", query_text)?;
    Ok(())
}

fn validate_node_types(lang: super::LangKind, query_text: &str) -> Result<(), String> {
    let known = known_node_types(lang);
    // Scan for `(name` occurrences where name is not a predicate (#...) and not a capture.
    let chars: Vec<char> = query_text.chars().collect();
    let mut i = 0usize;
    while i < chars.len() {
        if chars[i] == '(' && i + 1 < chars.len() && (chars[i+1].is_alphabetic() || chars[i+1] == '_') {
            let start = i + 1;
            let mut j = start;
            while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_') { j += 1; }
            let name: String = chars[start..j].iter().collect();
            // line/col of name start (1-based)
            let prefix: String = chars[..start].iter().collect();
            let line = prefix.matches('\n').count() + 1;
            let col = start - prefix.rfind('\n').map(|p| p + 1).unwrap_or(0) + 1;
            if !known.contains(&name.as_str()) {
                return Err(format!("Error occurred while creating a tree-sitter query: Query error at {}:{}. Invalid node type {}", line, col, name));
            }
            i = j;
            continue;
        }
        i += 1;
    }
    Ok(())
}

