            let (_, lend) = line_bounds(src, code[i].start);
            let mut j = i;
            while j < code.len() && code[j].start < lend { j += 1; }
            excluded.push((i, j));
        }
        if is_kw(&code[i], src, "import") {
            if i + 1 < code.len() && code[i+1].text(src) == "(" {
                if let Some(close) = matching(code, i+1, "(", ")", src) { excluded.push((i, close+1)); }
            } else {
                let (_, lend) = line_bounds(src, code[i].start);
                let mut j = i;
                while j < code.len() && code[j].start < lend { j += 1; }
                excluded.push((i, j));
            }
        }
        if is_kw(&code[i], src, "type") {
            // exclude until end of the type declaration (group close or spec end)
