    while stack.len() > 1 {
        let completed = stack.pop().unwrap();
        stack.last_mut().unwrap().children.push(completed);
    }
    let mut root = stack.pop().unwrap();
    fn sort_rec(n: &mut Node) {
        n.children.sort_by(|a, b| a.start.cmp(&b.start).then(b.end.cmp(&a.end)));
        for c in n.children.iter_mut() { sort_rec(c); }
