    // Determine bin name and used options from raw args for the usage line.
    let bin = std::env::args().next()
        .map(|p| std::path::Path::new(&p).file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_else(|| "srgn".to_string()))
        .unwrap_or_else(|| "srgn".to_string());
    let mut used: Vec<String> = Vec::new();
    let mut add_used = |used: &mut Vec<String>, disp: String| {
        if !used.contains(&disp) { used.push(disp); }
    };
    let flag_map: std::collections::HashMap<&str, &str> = [
        ("u", "--upper"), ("l", "--lower"), ("t", "--titlecase"), ("n", "--normalize"),
        ("g", "--german"), ("S", "--symbols"), ("d", "--delete"), ("s", "--squeeze"),
        ("i", "--invert"), ("L", "--literal-string"), ("j", "--join-language-scopes"),
        ("H", "--hidden"), ("v", "--verbose..."),
    ].iter().cloned().collect();
    let value_opts: std::collections::HashMap<&str, &str> = [
        ("completions", "--completions <SHELL>"), ("glob", "--glob <GLOB>"),
        ("stdin-detection", "--stdin-detection <STDIN_DETECTION>"), ("stdout-detection", "--stdout-detection <STDOUT_DETECTION>"),
        ("threads", "--threads <THREADS>"),
        ("c", "--c <C>"), ("c-query", "--c-query <TREE-SITTER-QUERY-VALUE>"), ("c-query-file", "--c-query-file <TREE-SITTER-QUERY-FILENAME>"),
