        ("go", "--go <GO>"), ("go-query", "--go-query <TREE-SITTER-QUERY-VALUE>"), ("go-query-file", "--go-query-file <TREE-SITTER-QUERY-FILENAME>"),
        ("hcl", "--hcl <HCL>"), ("hcl-query", "--hcl-query <TREE-SITTER-QUERY-VALUE>"), ("hcl-query-file", "--hcl-query-file <TREE-SITTER-QUERY-FILENAME>"),
        ("python", "--python <PYTHON>"), ("py", "--python <PYTHON>"), ("python-query", "--python-query <TREE-SITTER-QUERY-VALUE>"), ("python-query-file", "--python-query-file <TREE-SITTER-QUERY-FILENAME>"),
        ("rust", "--rust <RUST>"), ("rs", "--rust <RUST>"), ("rust-query", "--rust-query <TREE-SITTER-QUERY-VALUE>"), ("rust-query-file", "--rust-query-file <TREE-SITTER-QUERY-FILENAME>"),
        ("typescript", "--typescript <TYPESCRIPT>"), ("ts", "--typescript <TYPESCRIPT>"), ("typescript-query", "--typescript-query <TREE-SITTER-QUERY-VALUE>"), ("typescript-query-file", "--typescript-query-file <TREE-SITTER-QUERY-FILENAME>"),
    ].iter().cloned().collect();
    let bool_long: std::collections::HashMap<&str, &str> = [
        ("upper", "--upper"), ("lower", "--lower"), ("titlecase", "--titlecase"), ("normalize", "--normalize"),
        ("german", "--german"), ("symbols", "--symbols"), ("delete", "--delete"), ("squeeze", "--squeeze"),
        ("squeeze-repeats", "--squeeze"), ("fail-no-files", "--fail-no-files"), ("dry-run", "--dry-run"),
        ("invert", "--invert"), ("literal-string", "--literal-string"), ("fail-any", "--fail-any"),
        ("fail-none", "--fail-none"), ("join-language-scopes", "--join-language-scopes"),
        ("line-numbers", "--line-numbers"), ("only-matching", "--only-matching"), ("hidden", "--hidden"),
        ("gitignored", "--gitignored"), ("sorted", "--sorted"), ("verbose", "--verbose..."),
        ("german-prefer-original", "--german-prefer-original"), ("german-naive", "--german-naive"),
        ("help", "--help"), ("version", "--version"),
    ].iter().cloned().collect();
    let mut scope_present = false;
    let mut repl_present = false;
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut i = 0usize;
    let mut after_dashes = false;
    let mut positionals = 0usize;
    while i < args.len() {
        let a = &args[i];
        if after_dashes {
            repl_present = true;
            i += 1;
            continue;
        }
        if a == "--" { after_dashes = true; i += 1; continue; }
        if let Some(long) = a.strip_prefix("--") {
            let (name, has_eq) = match long.split_once('=') { Some((n, _)) => (n, true), None => (long, false) };
            if let Some(d) = value_opts.get(name) {
                add_used(&mut used, d.to_string());
                if !has_eq { i += 1; } // skip value
            } else if let Some(d) = bool_long.get(name) {
                add_used(&mut used, d.to_string());
            } else {
                add_used(&mut used, format!("--{}", name));
            }
            i += 1;
            continue;
        }
        if a.starts_with('-') && a.len() > 1 && *a != "-".to_string() {
            // short cluster
            let chars: Vec<char> = a[1..].chars().collect();
            let mut consumed_value = false;
            for (ci, ch) in chars.iter().enumerate() {
                let key = ch.to_string();
                if let Some(d) = flag_map.get(key.as_str()) {
                    add_used(&mut used, d.to_string());
                } else if *ch == 'G' {
                    add_used(&mut used, "--glob <GLOB>".to_string());
                    // rest of token is the value if any, else next token
                    if ci + 1 == chars.len() { consumed_value = true; }
                    break;
                } else {
                    add_used(&mut used, format!("-{}", ch));
                }
            }
            if consumed_value { i += 1; }
            i += 1;
            continue;
        }
        positionals += 1;
        if positionals == 1 { scope_present = true; } else { repl_present = true; }
        i += 1;
    }
    // Include conflicting partner if it came from env and was not in raw args
    // Extract partner from first line: cannot be used with '--upper' or '[REPLACEMENT]'
    let first_line = rendered.lines().next().unwrap_or("");
    if let Some(start) = first_line.find("cannot be used with") {
        let rest = &first_line[start..];
        // clap only names the first partner here; if it is an option not seen, append after --delete position roughly at end
        for opt in ["--upper", "--lower", "--titlecase", "--normalize", "--german", "--symbols"] {
            if rest.contains(opt) && !used.contains(&opt.to_string()) {
                used.push(opt.to_string());
            }
        }
        let _ = rest;
    }
    let _ = scope_present;
    let usage_opts = used.join(" ");
    let repl_disp = if repl_present { "-- <REPLACEMENT>" } else { "[-- <REPLACEMENT>]" };
    let usage = if usage_opts.is_empty() {
        format!("Usage: {} <SCOPE> {}", bin, repl_disp)
    } else {
        format!("Usage: {} {} <SCOPE> {}", bin, usage_opts, repl_disp)
    };
    format!("error: the argument '--delete' cannot be used with:\\n  [REPLACEMENT]\\n  --upper\\n  --lower\\n  --titlecase\\n  --normalize\\n  --german\\n  --symbols\\n\\n{}\\n\\nFor more information, try '--help'.\\n", usage)
}

fn real_main() -> i32 {''')
