// Title casing following the John Gruber-style algorithm used by the
// `titlecase` crate: small words stay lowercase, words with internal
// capitals / dots are preserved, all-uppercase input is converted.

const SMALL_WORDS: &[&str] = &[
    "a", "an", "and", "as", "at", "but", "by", "en", "for", "if", "in", "of", "on", "or",
    "the", "to", "v", "via", "vs",
];

fn is_small(word: &str) -> bool {
    SMALL_WORDS.contains(&word.to_lowercase().as_str())
}

pub fn titlecase(input: &str) -> String {
    let input = input.trim();
    if input.is_empty() {
        return String::new();
    }
    let has_cased = input.chars().any(|c| c.is_lowercase() || c.is_uppercase());
    let all_upper = has_cased && !input.chars().any(|c| c.is_lowercase());
    let lowered_input;
    let input = if all_upper {
        lowered_input = input.to_lowercase();
        &lowered_input
    } else {
        input
    };

    // Tokenise by whitespace only; hyphens/slashes are handled inside chunks.
    #[derive(Clone)]
    enum Tok { Word(String), Sep(String) }
    let mut toks: Vec<Tok> = Vec::new();
    let mut cur = String::new();
    let mut cur_is_sep: Option<bool> = None;
    for c in input.chars() {
        let s = c.is_whitespace();
        match cur_is_sep {
            None => { cur.push(c); cur_is_sep = Some(s); }
            Some(prev) if prev == s => cur.push(c),
            Some(prev) => {
                toks.push(if prev { Tok::Sep(std::mem::take(&mut cur)) } else { Tok::Word(std::mem::take(&mut cur)) });
                cur.push(c); cur_is_sep = Some(s);
            }
        }
    }
    if !cur.is_empty() {
        toks.push(if cur_is_sep.unwrap() { Tok::Sep(cur) } else { Tok::Word(cur) });
    }

    let word_indices: Vec<usize> = toks.iter().enumerate().filter_map(|(i, t)| if matches!(t, Tok::Word(_)) { Some(i) } else { None }).collect();
    let first_word = word_indices.first().copied();
    let last_word = word_indices.last().copied();

    let mut out = String::new();
    for (idx, tok) in toks.iter().enumerate() {
        match tok {
            Tok::Sep(s) => out.push_str(s),
            Tok::Word(w) => {
                let is_first = Some(idx) == first_word;
                let is_last = Some(idx) == last_word;
                let prev_ends_sentence = if idx >= 2 {
                    if let Tok::Word(pw) = &toks[idx - 2] {
                        pw.ends_with(':') || pw.ends_with('.') || pw.ends_with('!') || pw.ends_with('?')
                    } else { false }
                } else { false };
                out.push_str(&title_chunk(w, is_first || is_last || prev_ends_sentence));
            }
        }
    }
    out
}

// Alpha runs in a chunk: (start char idx, end char idx exclusive, text)
fn alpha_runs(chars: &[char]) -> Vec<(usize, usize)> {
    let mut runs = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i].is_alphabetic() {
            let start = i;
            while i < chars.len() && chars[i].is_alphabetic() { i += 1; }
            runs.push((start, i));
        } else {
            i += 1;
        }
    }
    runs
}

fn title_chunk(word: &str, force_cap: bool) -> String {
    let chars: Vec<char> = word.chars().collect();
    // Internal dot (hello.world, e.g.) preserves the chunk.
    let has_internal_dot = (1..chars.len()).any(|i| {
        chars[i] == '.' && i + 1 < chars.len() && chars[i - 1].is_alphanumeric() && chars[i + 1].is_alphanumeric()
    });
    if has_internal_dot {
        return word.to_string();
    }

    let runs = alpha_runs(&chars);
    if runs.is_empty() {
        return word.to_string();
    }
    // Preserve mixed-case chunks (iPhone, McDONALD, HeLLo, getHTTPResponse, hello's with caps etc.)
    let alpha_text: String = chars.iter().filter(|c| c.is_alphabetic()).copied().collect();
    let has_upper = alpha_text.chars().any(|c| c.is_uppercase());
    let has_lower = alpha_text.chars().any(|c| c.is_lowercase());
    if has_upper && has_lower {
        // Determine whether alphabetic runs are already in a simple title/lower pattern.
        // A run is "irregular" if:
        //  - it starts lower and contains an upper later, or
        //  - it starts upper, is not all upper, and rest is not all lower.
        let mut irregular = false;
        for &(s, e) in &runs {
            let run: Vec<char> = chars[s..e].to_vec();
            if run.len() <= 1 { continue; }
            let first = run[0];
            let rest = &run[1..];
            if first.is_lowercase() && rest.iter().any(|c| c.is_uppercase()) {
                irregular = true;
            }
            if first.is_uppercase() && rest.iter().any(|c| c.is_uppercase()) && rest.iter().any(|c| c.is_lowercase()) {
                irregular = true;
            }
        }
        if irregular {
            return word.to_string();
        }
    } else if has_upper && !has_lower {
        // All-uppercase chunk in a mixed-case phrase: an acronym, preserve.
        return word.to_string();
    }

    // Small-word check on the chunk core (stripped of surrounding punctuation).
    let core: String = word.trim_matches(|c: char| !c.is_alphanumeric()).to_string();
    let contains_hyphen_or_slash = word.contains('-') || word.contains('/');
    if !force_cap && !contains_hyphen_or_slash && is_small(&core) {
        return word.to_lowercase();
    }
    if !force_cap && !contains_hyphen_or_slash {
        // small words with a sentence-ending suffix are capitalised by force via prev word handling;
        // here if the chunk itself is small and ends with : . ! ? it is the end of a clause:
        let suffix_sentence = word.ends_with(':');
        if is_small(&core) && !suffix_sentence {
            return word.to_lowercase();
        }
        if is_small(&core) && suffix_sentence {
            // fall through to capitalisation
        }
    }

    // Transform: lowercase everything alphabetic, then uppercase word-start runs.
    let lower_chars: Vec<char> = word.to_lowercase().chars().collect();
    // The lowercasing may change length (e.g. İ -> i + combining dot); rebuild runs on lower text.
    let lower_runs = alpha_runs(&lower_chars);
    let mut result: Vec<char> = lower_chars.clone();
    for (ri, &(s, e)) in lower_runs.iter().enumerate() {
        let should_cap = if ri == 0 {
            // First run: suppress if the chunk starts with ' or [ (quoted/bracketed word),
            // unless the run is a single letter.
            let first_non_alpha = lower_chars[..s].iter().copied().collect::<String>();
            if first_non_alpha.contains('\'') || first_non_alpha.contains('[') {
                e - s == 1
            } else if s > 0 && lower_chars[..s].iter().all(|c| c.is_ascii_digit()) {
                // 123abc
                false
            } else {
                true
            }
        } else {
            // Subsequent runs: capitalise after '-' or '/'
            let prev = lower_chars[s - 1];
            prev == '-' || prev == '/'
        };
        if should_cap && s < result.len() {
            let up: Vec<char> = result[s].to_uppercase().collect();
            // Replace one char with possibly multiple (ß -> SS)
            let mut new_result: Vec<char> = Vec::new();
            new_result.extend_from_slice(&result[..s]);
            new_result.extend(up.iter());
            new_result.extend_from_slice(&result[s + 1..]);
            // Adjust: subsequent run indices are in terms of lower_chars; if up.len() != 1 lengths shift.
            // For simplicity, apply expansions by rebuilding from a char vector with offset tracking.
            result = new_result;
            // NOTE: run indices beyond this point may be off by (up.len()-1) if expansion occurred.
            // Expansions are rare (ß etc.) and runs after an expanded first char are uncommon.
            // To avoid complexity, if expansion happened, return the partially built string with remaining lower runs.
            if up.len() != 1 {
                // lowercase rest already; apply remaining run caps approximately by continuing with result string process:
                // Break and post-process hyphens in string form below.
                let mut st: String = result.iter().collect();
                st = capitalize_after_hyphen_slash(&st);
                return st;
            }
        }
    }
    result.iter().collect()
}

fn capitalize_after_hyphen_slash(s: &str) -> String {
    let mut out = String::new();
    let mut prev: Option<char> = None;
    for c in s.chars() {
        if c.is_alphabetic() && matches!(prev, Some('-') | Some('/')) {
            out.extend(c.to_uppercase());
        } else {
            out.push(c);
        }
        prev = Some(c);
    }
    out
}
