fn match_children(patterns: &[ChildPattern], children: &[Node], source: &str) -> Vec<CapMap> {
    fn rec(pi: usize, ci: usize, patterns: &[ChildPattern], children: &[Node], source: &str) -> Vec<CapMap> {
        if pi >= patterns.len() {
            return vec![Vec::new()];
        }
        let cp = &patterns[pi];
        let mut results = Vec::new();
        match cp.quant {
            Quant::One => {
                for j in ci..children.len() {
                    for caps_child in try_child(cp, &children[j], source) {
                        for caps_rest in rec(pi + 1, j + 1, patterns, children, source) {
                            let mut combined = caps_child.clone();
                            combined.extend(caps_rest);
                            results.push(combined);
                        }
                    }
                }
            }
            Quant::Optional => {
                // skip
                results.extend(rec(pi + 1, ci, patterns, children, source));
                // consume one
                for j in ci..children.len() {
                    for caps_child in try_child(cp, &children[j], source) {
                        for caps_rest in rec(pi + 1, j + 1, patterns, children, source) {
                            let mut combined = caps_child.clone();
                            combined.extend(caps_rest);
                            results.push(combined);
                        }
                    }
                    // Only the first matching position is considered for the consumed branch
                    // to limit duplicates, but all captures from that child are included.
                    if !try_child(cp, &children[j], source).is_empty() { break; }
                }
            }
            Quant::Star | Quant::Plus => {
                // Generate sequences by recursively consuming one child then staying on same pattern,
                // or moving on. We generate via a helper that enumerates consumption counts.
                fn consume(pi: usize, ci: usize, count: usize, patterns: &[ChildPattern], children: &[Node], source: &str, results: &mut Vec<CapMap>) {
                    let cp = &patterns[pi];
                    let min = if cp.quant == Quant::Plus { 1 } else { 0 };
                    if count >= min {
                        // move on
                        for caps_rest in rec(pi + 1, ci, patterns, children, source) {
                            results.push(caps_rest);
                        }
                    }
                    // consume one more
                    for j in ci..children.len() {
                        for caps_child in try_child(cp, &children[j], source) {
                            // recurse consumption with this child's caps prepended
                            let mut sub_results: Vec<CapMap> = Vec::new();
                            consume_with_prefix(pi, j + 1, count + 1, patterns, children, source, &caps_child, &mut sub_results);
                            results.append(&mut sub_results);
                        }
                        if !try_child(cp, &children[j], source).is_empty() { break; }
                    }
                    let _ = results;
                }
                fn consume_with_prefix(pi: usize, ci: usize, count: usize, patterns: &[ChildPattern], children: &[Node], source: &str, prefix: &CapMap, results: &mut Vec<CapMap>) {
                    // Same as consume but prepend prefix to outcomes that move on, and continue consuming
                    let cp = &patterns[pi];
                    let min = if cp.quant == Quant::Plus { 1 } else { 0 };
                    if count >= min {
                        for caps_rest in rec(pi + 1, ci, patterns, children, source) {
                            let mut combined = prefix.clone();
                            combined.extend(caps_rest);
                            results.push(combined);
                        }
                    }
                    for j in ci..children.len() {
                        for caps_child in try_child(cp, &children[j], source) {
                            let mut new_prefix = prefix.clone();
                            new_prefix.extend(caps_child);
                            consume_with_prefix(pi, j + 1, count + 1, patterns, children, source, &new_prefix, results);
                        }
                        if !try_child(cp, &children[j], source).is_empty() { break; }
                    }
                }
                let mut raw: Vec<CapMap> = Vec::new();
                consume(pi, ci, 0, patterns, children, source, &mut raw);
                // The initial consume call pushes results without prefix for move-on cases; consume_with_prefix handles consumed.
                // Dedup is handled by caller ranges merging.
                results.extend(raw);
            }
        }
        results
    }
    rec(0, 0, patterns, children, source)
}

fn try_child(cp: &ChildPattern, node: &Node, source: &str) -> Vec<CapMap> {
    if let Some(f) = &cp.field {
        if node.field.as_deref() != Some(f.as_str()) {
            return Vec::new();
        }
    }
    match_pattern(&cp.pattern, node, source)
